// Gera NOVO orderid repondo a quantidade que falta (remains) no TopFama.
app.post('/api/painel/topfama/reorder', requireAdmin, async (req, res) => {
  try {
    const id = String((req.body && req.body.id) || '').trim();
    const field = TOPFAMA_FIELDS.includes(String((req.body && req.body.field) || '')) ? String(req.body.field) : 'topfama';
    if (!/^[0-9a-fA-F]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'invalid_id' });
    const col = await getCollection('checkout_orders');
    const { ObjectId } = require('mongodb');
    const o = await col.findOne({ _id: new ObjectId(id) });
    if (!o) return res.status(404).json({ ok: false, error: 'not_found' });
    const sub = o[field] || {};
    const remains = Math.floor(Number(sub.remains || 0) || 0);
    if (remains <= 0) return res.status(400).json({ ok: false, error: 'no_remains', message: 'Sem quantidade faltando para repor.' });
    const rp = sub.requestPayload || {};
    const service = rp.service, link = rp.link;
    if (!service || !link) return res.status(400).json({ ok: false, error: 'missing_payload', message: 'Pedido sem service/link do fornecedor.' });
    const provider = refilProviderOf(field);
    const cfg = REFIL_PROVIDER_CFG[provider] || REFIL_PROVIDER_CFG.topfama;
    const key = process.env[cfg.keyEnv] || '';
    if (!key) return res.status(400).json({ ok: false, error: 'missing_key' });
    const payload = new URLSearchParams({ key, action: 'add', service: String(service), link: String(link), quantity: String(remains) });
    const resp = await axios.post(cfg.url, payload.toString(), { headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, timeout: 30000, validateStatus: () => true });
    const d = (resp && resp.data && typeof resp.data === 'object') ? resp.data : {};
    const newOrderId = d.order || d.orderId || (d.data && d.data.order) || null;
    if (!newOrderId) return res.status(502).json({ ok: false, error: 'reorder_failed', message: String(d.error || d.Error || 'fornecedor não retornou order id').slice(0, 200) });
    // Anexa também à cadeia `reorders[]` (mesmo modelo do automático), atrelado ao pai.
    const nowIso = new Date().toISOString();
    const chain = Array.isArray(sub.reorders) ? sub.reorders.slice() : [];
    chain.push({ orderId: String(newOrderId), quantity: remains, reason: 'manual', at: nowIso, status: 'created', remains: null });
    await col.updateOne({ _id: o._id }, { $set: { [`${field}.reorderId`]: String(newOrderId), [`${field}.reorderQty`]: remains, [`${field}.reorderAt`]: nowIso, [`${field}.reorders`]: chain, [`${field}.reorderChainDone`]: false } });
    return res.json({ ok: true, reorderId: String(newOrderId), quantity: remains });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

// Verifica UM pedido sob demanda (status + quantidade faltando) — botão por linha.
app.post('/api/painel/topfama/verify', requireAdmin, async (req, res) => {
  try {
    const id = String((req.body && req.body.id) || '').trim();
    const field = TOPFAMA_FIELDS.includes(String((req.body && req.body.field) || '')) ? String(req.body.field) : 'topfama';
    if (!/^[0-9a-fA-F]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'invalid_id' });
    const col = await getCollection('checkout_orders');
    const { ObjectId } = require('mongodb');
    const o = await col.findOne({ _id: new ObjectId(id) }, { projection: { [field]: 1 } });
    if (!o) return res.status(404).json({ ok: false, error: 'not_found' });
    const sub = o[field] || {};
    const oid = sub && sub.orderId ? String(sub.orderId).trim() : '';
    if (!oid || !/^[0-9]+$/.test(oid)) return res.status(400).json({ ok: false, error: 'no_orderid', message: 'Pedido sem orderid do fornecedor.' });
    const r = await providerFetchStatus(refilProviderOf(field), oid);
    if (!r || r.error) return res.status(502).json({ ok: false, error: 'status_failed', message: String((r && r.error) || 'falha na consulta').slice(0, 200) });
    await col.updateOne({ _id: o._id }, { $set: { [`${field}.status`]: r.status || String(sub.status || ''), [`${field}.remains`]: r.remains, [`${field}.startCount`]: r.startCount, [`${field}.statusPayload`]: r.raw, [`${field}.statusCheckedAt`]: new Date().toISOString() } });
    return res.json({ ok: true, status: r.status, remains: r.remains, startCount: r.startCount });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

// Audita as curtidas ATUAIS de UM pedido concluído (botão por linha). Apify→RocketAPI.
app.post('/api/painel/topfama/audit-likes', requireAdmin, async (req, res) => {
  try {
    const id = String((req.body && req.body.id) || '').trim();
    const field = TOPFAMA_FIELDS.includes(String((req.body && req.body.field) || '')) ? String(req.body.field) : 'topfama';
    if (!/^[0-9a-fA-F]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'invalid_id' });
    const col = await getCollection('checkout_orders');
    const { ObjectId } = require('mongodb');
    const o = await col.findOne({ _id: new ObjectId(id) }, { projection: { [field]: 1 } });
    if (!o) return res.status(404).json({ ok: false, error: 'not_found' });
    const sub = o[field] || {};
    const isDone = TOPFAMA_DONE.has(String(sub.status || '').toLowerCase().trim());
    if (!isDone) return res.status(400).json({ ok: false, error: 'not_completed', message: 'A auditoria de curtidas só roda para pedidos concluídos.' });
    const link = String((sub.requestPayload && sub.requestPayload.link) || '');
    if (!link) return res.status(400).json({ ok: false, error: 'no_link', message: 'Pedido sem link do post.' });
    const r = await fetchPostLikeCount(link);
    if (!r) return res.status(502).json({ ok: false, error: 'audit_failed', message: 'Não foi possível obter as curtidas (RocketAPI e Apify falharam).' });
    const set = { [`${field}.auditLikesSource`]: r.source, [`${field}.auditLikesAt`]: new Date().toISOString(), [`${field}.auditLikesHidden`]: !!r.hidden };
    if (r.hidden) set[`${field}.auditLikes`] = null; else set[`${field}.auditLikes`] = r.likes;
    await col.updateOne({ _id: o._id }, { $set: set });
    return res.json({ ok: true, likes: r.likes, hidden: !!r.hidden, source: r.source });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

// Normaliza a lista de itens {id, field} recebida das ações em massa.
function _topfamaBulkItems(body) {
  const items = Array.isArray(body && body.items) ? body.items : [];
  const out = [];
  const { ObjectId } = require('mongodb');
  for (const it of items.slice(0, 1000)) {
    const id = String((it && it.id) || '').trim();
    if (!/^[0-9a-fA-F]{24}$/.test(id)) continue;
    const field = TOPFAMA_FIELDS.includes(String((it && it.field) || '')) ? String(it.field) : 'topfama';
    out.push({ _id: new ObjectId(id), field });
  }
  return out;
}

// AÇÃO EM MASSA — Verificar status/remains dos pedidos marcados.
app.post('/api/painel/topfama/verify-bulk', requireAdmin, async (req, res) => {
  try {
    const items = _topfamaBulkItems(req.body);
    if (!items.length) return res.status(400).json({ ok: false, error: 'no_items' });
    const col = await getCollection('checkout_orders');
    const out = { checked: 0, updated: 0, errors: 0, skipped: 0 };
    for (const it of items) {
      try {
        const o = await col.findOne({ _id: it._id }, { projection: { [it.field]: 1 } });
        const sub = (o && o[it.field]) || {};
        const oid = sub.orderId ? String(sub.orderId).trim() : '';
        if (!oid || !/^[0-9]+$/.test(oid)) { out.skipped++; continue; }
        const r = await providerFetchStatus(refilProviderOf(it.field), oid);
        out.checked++;
        if (r && !r.error) {
          await col.updateOne({ _id: it._id }, { $set: { [`${it.field}.status`]: r.status || String(sub.status || ''), [`${it.field}.remains`]: r.remains, [`${it.field}.startCount`]: r.startCount, [`${it.field}.statusPayload`]: r.raw, [`${it.field}.statusCheckedAt`]: new Date().toISOString() } });
          out.updated++;
        } else out.errors++;
      } catch (_) { out.errors++; }
      await new Promise((r2) => setTimeout(r2, 200));
    }
    return res.json({ ok: true, result: out });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

// AÇÃO EM MASSA — Auditar curtidas atuais dos pedidos marcados (só concluídos).
app.post('/api/painel/topfama/audit-bulk', requireAdmin, async (req, res) => {
  try {
    const items = _topfamaBulkItems(req.body);
    if (!items.length) return res.status(400).json({ ok: false, error: 'no_items' });
    const col = await getCollection('checkout_orders');
    const out = { audited: 0, hidden: 0, failed: 0, skipped: 0 };
    for (const it of items) {
      try {
        const o = await col.findOne({ _id: it._id }, { projection: { [it.field]: 1 } });
        const sub = (o && o[it.field]) || {};
        if (!TOPFAMA_DONE.has(String(sub.status || '').toLowerCase().trim())) { out.skipped++; continue; }
        const link = String((sub.requestPayload && sub.requestPayload.link) || '');
        if (!link) { out.skipped++; continue; }
        const r = await fetchPostLikeCount(link);
        if (r) {
          const set = { [`${it.field}.auditLikesSource`]: r.source, [`${it.field}.auditLikesAt`]: new Date().toISOString(), [`${it.field}.auditLikesHidden`]: !!r.hidden };
          if (r.hidden) { set[`${it.field}.auditLikes`] = null; out.hidden++; } else { set[`${it.field}.auditLikes`] = r.likes; out.audited++; }
          await col.updateOne({ _id: it._id }, { $set: set });
        } else out.failed++;
      } catch (_) { out.failed++; }
      await new Promise((r2) => setTimeout(r2, 250));
    }
    return res.json({ ok: true, result: out });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

// Página: Gestão Parcial (TopFama)
app.get('/painel/gestao-parcial-topfama', requireAdmin, async (req, res) => {
  try {
    const col = await getCollection('checkout_orders');
    const orQ = TOPFAMA_FIELDS.map((f) => ({ [`${f}.orderId`]: { $exists: true, $nin: [null, ''] } }));
    const orders = await col.find({ $or: orQ }, { projection: Object.assign({ customer: 1, instagramUsername: 1, instauser: 1, additionalInfoMapPaid: 1, additionalInfoMap: 1, additionalInfoPaid: 1, additionalInfo: 1, createdAt: 1, criado: 1, paidAt: 1, 'woovi.paidAt': 1, 'paghiper.paidAt': 1 }, TOPFAMA_PROJ) }).sort({ createdAt: -1, _id: -1 }).limit(3000).toArray();
    const rows = [];
    for (const o of orders) {
      const g = buildOrderFieldGetter(o);
      const nome = String((o.customer && (o.customer.name || o.customer.nome)) || g('nome') || g('name') || '').trim();
      const usuario = String(g('instagram_username') || o.instagramUsername || o.instauser || '').replace(/^@+/, '').trim();
      let dataMs = 0; for (const x of [o.paidAt, o?.woovi?.paidAt, o?.paghiper?.paidAt, o.createdAt, o.criado]) { const t = x ? new Date(x).getTime() : NaN; if (Number.isFinite(t)) { dataMs = t; break; } }
      for (const f of TOPFAMA_FIELDS) {
        const sub = o[f]; if (!sub || !sub.orderId) continue;
        const rp = sub.requestPayload || {};
        rows.push({
          id: String(o._id), field: f, dataMs,
          fornecedor: String(f).replace(/_likes$/, ''), // 'topfama'|'topfama_likes' -> 'topfama'
          orderIdOriginal: String(sub.orderId),
          nome, usuario,
          linkPost: String(rp.link || ''),
          qtdContratada: Number(rp.quantity || 0) || 0,
          status: String(sub.status || ''),
          remains: (sub.remains != null && sub.remains !== '') ? Math.floor(Number(sub.remains) || 0) : null,
          novoOrderId: String(sub.reorderId || ''),
          reorders: (Array.isArray(sub.reorders) ? sub.reorders : []).map((rr) => ({
            orderId: String((rr && rr.orderId) || ''),
            quantity: Number((rr && rr.quantity) || 0) || 0,
            reason: String((rr && rr.reason) || ''),
            status: String((rr && rr.status) || ''),
            remains: (rr && rr.remains != null && rr.remains !== '') ? Math.floor(Number(rr.remains) || 0) : null,
            at: (rr && rr.at) || null,
          })).filter((rr) => rr.orderId),
          reorderChainDone: !!sub.reorderChainDone,
          reorderStopReason: String(sub.reorderStopReason || ''),
          checkedAt: sub.statusCheckedAt || null,
          statusDone: /complet|conclu/.test(String(sub.status || '').toLowerCase()),
          statusCat: (function () {
            const st = String(sub.status || '').toLowerCase();
            if (/complet|conclu/.test(st)) return 'done';
            if (/partial/.test(st)) return 'partial';
            if (/progress|process|pending|andamento/.test(st)) return 'prog';
            if (/cancel|refund|error/.test(st)) return 'canc';
            if (!sub.statusCheckedAt) return 'unverified';
            return 'other';
          })(),
          auditLikes: (sub.auditLikes != null && sub.auditLikes !== '') ? Number(sub.auditLikes) : null,
          auditLikesAt: sub.auditLikesAt || null,
          auditLikesHidden: !!sub.auditLikesHidden,
          // Quantidade INICIAL de curtidas (baseline antes da entrega): nossa medição no
          // despacho (initialLikes) ou o start_count do TopFama como fallback.
          initialLikes: (function () {
            if (sub.initialLikes != null && sub.initialLikes !== '') return Number(sub.initialLikes);
            if (sub.startCount != null && sub.startCount !== '') return Number(sub.startCount);
            return null;
          })(),
        });
      }
    }
    rows.sort((a, b) => (b.dataMs || 0) - (a.dataMs || 0));
    // Entregue (curtidas que o serviço adicionou = atual − inicial) e resultado ok/nok:
    //   ok  = entregou >= a quantidade contratada
    //   nok = entregou <  a quantidade contratada
    // Só faz sentido para pedidos CONCLUÍDOS com atual + inicial conhecidos.
    for (const r of rows) {
      r.entregue = (r.auditLikes != null && r.initialLikes != null) ? (r.auditLikes - r.initialLikes) : null;
      r.okNok = null;
      if (r.statusDone) {
        if (r.auditLikesHidden) r.okNok = 'oculto';                 // pessoa ocultou as curtidas
        else if (r.entregue != null && r.qtdContratada > 0) r.okNok = (r.entregue >= r.qtdContratada) ? 'ok' : 'nok';
      }
    }
    // Filtro por data (De/Até), no fuso de Brasília.
    const parseDay = (s, endOfDay) => { const v = String(s || '').slice(0, 10); if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return null; const t = new Date(v + 'T' + (endOfDay ? '23:59:59' : '00:00:00') + '-03:00').getTime(); return Number.isFinite(t) ? t : null; };
    const startMs = parseDay(req.query.start, false);
    const endMs = parseDay(req.query.end, true);
    const statusFilter = String(req.query.status || '').toLowerCase().trim();
    const validStatus = ['done', 'partial', 'prog', 'canc', 'unverified'];
    const resultFilter = String(req.query.result || '').toLowerCase().trim();
    const validResult = ['ok', 'nok', 'oculto'];
    // Sempre oferece os 2 provedores no filtro (mesmo sem pedidos ainda) + quaisquer outros nos dados.
    const fornecedores = Array.from(new Set([...Object.values(REFIL_FIELD_PROVIDER), ...rows.map((r) => r.fornecedor)].filter(Boolean))).sort();
    const fornecedorFilter = String(req.query.fornecedor || '').toLowerCase().trim();
    const filtered = rows.filter((r) =>
      (startMs == null || r.dataMs >= startMs) &&
      (endMs == null || r.dataMs <= endMs) &&
      (!statusFilter || !validStatus.includes(statusFilter) || r.statusCat === statusFilter) &&
      (!resultFilter || !validResult.includes(resultFilter) || r.okNok === resultFilter) &&
      (!fornecedorFilter || !fornecedores.includes(fornecedorFilter) || r.fornecedor === fornecedorFilter)
    );
    return res.render('painel_gestao_parcial_topfama', {
      page: 'gestao-parcial-topfama',
      rows: filtered,
      totalAll: rows.length,
      fornecedores,
      filter: {
        start: /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.start || '')) ? String(req.query.start).slice(0, 10) : '',
        end: /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.end || '')) ? String(req.query.end).slice(0, 10) : '',
        result: validResult.includes(resultFilter) ? resultFilter : '',
        status: validStatus.includes(statusFilter) ? statusFilter : '',
        fornecedor: fornecedores.includes(fornecedorFilter) ? fornecedorFilter : '',
      },
    });
  } catch (e) { return res.status(500).send(String((e && e.message) || e)); }
});

// ═══════════════════════════════════════════════════════════════════════════
//  TESTES DE SERVIÇOS — cadastra um pedido de teste (serviço/fornecedor) num
//  perfil de teste e mede a quantidade ATUAL de seguidores + % de queda todo
//  dia às 12h (BRT). Coleção: service_tests.
// ═══════════════════════════════════════════════════════════════════════════
// Checa UM teste: busca seguidores atuais, atualiza pico/atual/queda e o histórico
// (1 ponto por dia BRT — reconsulta no mesmo dia substitui o ponto do dia).
async function serviceTestCheckOne(col, rec) {
  // Tipo CURTIDAS → o "perfil" é o LINK DO POST; medimos as CURTIDAS ATUAIS do post
  // (RocketAPI get_info_by_shortcode → Apify). Demais tipos → seguidores do perfil.
  const isCurtidas = /curtida/i.test(String(rec.tipo || ''));
  // Persiste a FALHA de medição no próprio doc (perfil caiu/sumiu/privado). Assim a linha
  // fica marcada (X no painel) e passa a ser IGNORADA nas próximas checagens em lote.
  const markFail = async (reason) => {
    try { await col.updateOne({ _id: rec._id }, { $set: { measureFailed: true, measureFailedAt: new Date().toISOString(), measureFailReason: String(reason || 'fetch_failed'), updatedAt: new Date().toISOString() }, $inc: { measureFailCount: 1 } }); } catch (_) {}
    return { ok: false };
  };
  let count = null, source = '';
  if (isCurtidas) {
    const lr = await fetchPostLikeCount(rec.perfil);
    if (!lr) return await markFail('post_fetch_failed');
    if (lr.hidden) {
      // Curtidas ocultadas no post → sem número; registra o estado e mantém o histórico.
      await col.updateOne({ _id: rec._id }, { $set: { atualSource: lr.source, atualHidden: true, measureFailed: false, lastCheckAt: new Date().toISOString(), updatedAt: new Date().toISOString() } });
      return { ok: true, hidden: true, source: lr.source };
    }
    count = Number(lr.likes); source = lr.source;
  } else {
    const r = await fetchFollowerCount(rec.perfil);
    if (!r) return await markFail('profile_fetch_failed');
    count = Number(r.count); source = r.source;
  }
  if (!Number.isFinite(count)) return await markFail('invalid_count');
  const pico = Math.max(Number(rec.pico || 0) || 0, count);
  const quedaPct = pico > 0 ? Math.round(((pico - count) / pico) * 1000) / 10 : 0;
  let hist = Array.isArray(rec.history) ? rec.history.slice() : [];
  const today = brtDayKey(Date.now());
  const point = { at: new Date().toISOString(), count, source };
  if (hist.length && brtDayKey(hist[hist.length - 1].at) === today) hist[hist.length - 1] = point;
  else hist.push(point);
  if (hist.length > 180) hist = hist.slice(-180);
  await col.updateOne({ _id: rec._id }, { $set: { atual: count, atualSource: source, atualHidden: false, pico, quedaPct, history: hist, measureFailed: false, lastCheckAt: new Date().toISOString(), updatedAt: new Date().toISOString() } });
  return { ok: true, count, pico, quedaPct, source };
}
// Checa TODOS os testes (usado pelo cron das 12h e pelo botão "Checar todos agora").
let __serviceTestsRunning = false;
async function runServiceTestsDailyCheck() {
  if (__serviceTestsRunning) return { skipped: true, reason: 'running' };
  __serviceTestsRunning = true;
  const out = { checked: 0, ok: 0, fail: 0, ignored: 0, failedIds: [] };
  try {
    const col = await getCollection('service_tests');
    // Ignora linhas já marcadas como falha (perfil caiu/sumiu) — não tenta medir de novo.
    const recs = await col.find({ measureFailed: { $ne: true } }).toArray();
    out.ignored = await col.countDocuments({ measureFailed: true }).catch(() => 0);
    for (const rec of recs) {
      out.checked++;
      let ok = false;
      try { const r = await serviceTestCheckOne(col, rec); ok = !!(r && r.ok); } catch (_) { ok = false; }
      if (ok) out.ok++; else { out.fail++; out.failedIds.push(String(rec._id)); }
      await new Promise((res) => setTimeout(res, 400));
    }
  } catch (e) { out.error = e && e.message; }
  __serviceTestsRunning = false;
  return out;
}
// Agenda o check diário às 12h BRT (12:00 BRT = 15:00 UTC).
let __serviceTestsTimer = null;
function startServiceTestsDailyLoop() {
  const scheduleNext = () => {
    const now = Date.now();
    const brt = new Date(now - 3 * 3600000);
    let target = Date.UTC(brt.getUTCFullYear(), brt.getUTCMonth(), brt.getUTCDate(), 12, 0, 0) + 3 * 3600000;
    if (target <= now) target += 24 * 3600000;
    const delay = Math.max(1000, target - now);
    __serviceTestsTimer = setTimeout(async () => {
      try { const r = await runServiceTestsDailyCheck(); console.log('🧪 [testes-servicos] check diário 12h:', JSON.stringify(r)); } catch (_) {}
      scheduleNext();
    }, delay);
    try { __serviceTestsTimer.unref && __serviceTestsTimer.unref(); } catch (_) {}
  };
  scheduleNext();
}

// Página
app.get('/painel/testes-servicos', requireAdmin, async (req, res) => {
  try {
    const col = await getCollection('service_tests');
    const docs = await col.find({}).sort({ dataPedidoMs: -1, createdAt: -1, _id: -1 }).limit(2000).toArray();
    const ENTREGA_VALS = ['Mais', 'Igual', 'Menos'];
    const allRows = docs.map((d) => ({
      id: String(d._id),
      favorito: !!d.favorito,
      serviceId: String(d.serviceId || ''),
      tipo: String(d.tipo || ''),
      perfil: String(d.perfil || ''),
      quantidade: Number(d.quantidade || 0) || 0,
      qualidade: String(d.qualidade || ''),
      temRefil: !!d.temRefil,
      entregaMais: ENTREGA_VALS.includes(String(d.entregaMais)) ? String(d.entregaMais) : '',
      velocidadeInicio: String(d.velocidadeInicio || ''),
      atual: (d.atual != null) ? Number(d.atual) : null,
      atualSource: String(d.atualSource || ''),
      pico: (d.pico != null) ? Number(d.pico) : null,
      quedaPct: (d.quedaPct != null) ? Number(d.quedaPct) : null,
      preco: (d.preco != null) ? Number(d.preco) : null,
      dataPedido: String(d.dataPedido || ''),
      fornecedor: String(d.fornecedor || ''),
      lastCheckAt: d.lastCheckAt || null,
      measureFailed: !!d.measureFailed,
      measureFailReason: String(d.measureFailReason || ''),
      history: Array.isArray(d.history) ? d.history : [],
    }));
    // ── Filtros: tipo de serviço, fornecedor e faixa de taxa de queda (min/max %) ──
    const tipoF = String(req.query.tipo || '').trim();
    const fornF = String(req.query.fornecedor || '').trim();
    const favF = String(req.query.fav || '') === '1';
    const qMinRaw = String(req.query.quedaMin != null ? req.query.quedaMin : '').trim();
    const qMaxRaw = String(req.query.quedaMax != null ? req.query.quedaMax : '').trim();
    const qMin = qMinRaw !== '' && Number.isFinite(Number(qMinRaw)) ? Number(qMinRaw) : null;
    const qMax = qMaxRaw !== '' && Number.isFinite(Number(qMaxRaw)) ? Number(qMaxRaw) : null;
    const fornecedores = Array.from(new Set(allRows.map((r) => r.fornecedor).filter(Boolean))).sort();
    const rows = allRows.filter((r) => {
      if (favF && !r.favorito) return false;
      if (tipoF && r.tipo !== tipoF) return false;
      if (fornF && r.fornecedor !== fornF) return false;
      const q = (r.quedaPct != null) ? r.quedaPct : null;
      if (qMin != null && (q == null || q < qMin)) return false;
      if (qMax != null && (q == null || q > qMax)) return false;
      return true;
    });
    return res.render('painel_testes_servicos', {
      page: 'testes-servicos', rows, totalAll: allRows.length, fornecedores,
      filter: { tipo: tipoF, fornecedor: fornF, fav: favF ? '1' : '', quedaMin: qMinRaw, quedaMax: qMaxRaw },
    });
  } catch (e) { return res.status(500).send(String((e && e.message) || e)); }
});
// Cria um teste
app.post('/api/painel/testes-servicos/create', requireAdmin, async (req, res) => {
  try {
    const b = req.body || {};
    // Baserow-style: pode criar linha vazia e preencher depois (edição inline).
    const perfil = String(b.perfil || '').replace(/^@+/, '').replace(/\/+$/g, '').trim();
    // Data do pedido = AGORA (registro automático, sem campo no formulário). Fuso BRT.
    const _nb = new Date(Date.now() - 3 * 3600000);
    const dataPedido = `${_nb.getUTCFullYear()}-${String(_nb.getUTCMonth() + 1).padStart(2, '0')}-${String(_nb.getUTCDate()).padStart(2, '0')}`;
    const dataPedidoMs = Date.now();
    const doc = {
      favorito: (b.favorito === true || b.favorito === 'true' || b.favorito === '1'),
      serviceId: String(b.serviceId || '').trim(),
      tipo: String(b.tipo || '').slice(0, 40),
      perfil,
      quantidade: Math.max(0, Math.floor(Number(b.quantidade || 0) || 0)),
      qualidade: String(b.qualidade || '').slice(0, 60),
      temRefil: b.temRefil === true || b.temRefil === 'true' || b.temRefil === 'on' || b.temRefil === '1',
      entregaMais: (['Mais', 'Igual', 'Menos'].includes(String(b.entregaMais)) ? String(b.entregaMais) : ''),
      velocidadeInicio: String(b.velocidadeInicio || '').slice(0, 60),
      preco: (b.preco != null && b.preco !== '') ? Math.round(Number(String(b.preco).replace(',', '.')) * 100) / 100 : null,
      dataPedido, dataPedidoMs,
      fornecedor: String(b.fornecedor || '').slice(0, 60),
      atual: null, atualSource: '', pico: null, quedaPct: null, history: [],
      lastCheckAt: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
    };
    const col = await getCollection('service_tests');
    const ins = await col.insertOne(doc);
    // Checagem inicial (best-effort) para já mostrar a quantidade atual.
    try { const rec = await col.findOne({ _id: ins.insertedId }); if (rec) await serviceTestCheckOne(col, rec); } catch (_) {}
    return res.json({ ok: true, id: String(ins.insertedId) });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});
// Edita campos manuais de um teste
app.post('/api/painel/testes-servicos/update', requireAdmin, async (req, res) => {
  try {
    const b = req.body || {};
    const id = String(b.id || '').trim();
    if (!/^[0-9a-fA-F]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'invalid_id' });
    const { ObjectId } = require('mongodb');
    const $set = { updatedAt: new Date().toISOString() };
    if (b.favorito != null) $set.favorito = (b.favorito === true || b.favorito === 'true' || b.favorito === '1');
    if (b.serviceId != null) $set.serviceId = String(b.serviceId).trim();
    if (b.tipo != null) $set.tipo = String(b.tipo).slice(0, 40);
    if (b.quantidade != null) $set.quantidade = Math.max(0, Math.floor(Number(b.quantidade) || 0));
    if (b.qualidade != null) $set.qualidade = String(b.qualidade).slice(0, 60);
    if (b.temRefil != null) $set.temRefil = (b.temRefil === true || b.temRefil === 'true' || b.temRefil === '1');
    if (b.entregaMais != null) $set.entregaMais = (['Mais', 'Igual', 'Menos'].includes(String(b.entregaMais)) ? String(b.entregaMais) : '');
    if (b.velocidadeInicio != null) $set.velocidadeInicio = String(b.velocidadeInicio).slice(0, 60);
    if (b.preco != null) $set.preco = (b.preco === '') ? null : Math.round(Number(String(b.preco).replace(',', '.')) * 100) / 100;
    if (b.fornecedor != null) $set.fornecedor = String(b.fornecedor).slice(0, 60);
    if (b.perfil != null) $set.perfil = String(b.perfil).replace(/^@+/, '').replace(/\/+$/g, '').trim();
    if (b.dataPedido != null && /^\d{4}-\d{2}-\d{2}/.test(String(b.dataPedido))) { $set.dataPedido = String(b.dataPedido).slice(0, 10); $set.dataPedidoMs = new Date($set.dataPedido + 'T12:00:00-03:00').getTime(); }
    const col = await getCollection('service_tests');
    await col.updateOne({ _id: new ObjectId(id) }, { $set });
    return res.json({ ok: true });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});
