// ── Harness de teste da IA de vendas (sem WhatsApp): roda o agente e devolve as respostas.
//    Reusa o histórico por telefone (dá pra testar multi-turno passando o mesmo phone). ──
app.post('/api/whatsapp-ia/agent-test', requireAdmin, async (req, res) => {
  try {
    const text = String((req.body && req.body.text) || '').trim();
    const phone = String((req.body && req.body.phone) || 'test-agent').trim();
    if (!text) return res.status(400).json({ ok: false, error: 'no_text' });
    const agent = require('./whatsappAgent.js');
    // Simula o gatilho do menu de boas-vindas (no WhatsApp real isso vira BOTÕES).
    try {
      const wa = require('./whatsappCloud.js');
      if (wa.isTriggerMessage(text)) {
        const menu = wa.WELCOME_TEXT + '\n\n' + wa.MENU_BUTTONS.map((b) => '▶ ' + b.title).join('\n') + '\n\n(no WhatsApp real, essas 3 opções aparecem como BOTÕES clicáveis)';
        return res.json({ ok: true, phone, openai: agent.isEnabled(), replies: [menu] });
      }
    } catch (_) {}
    const replies = [];
    const result = await agent.handleAgentMessage({ phone, text }, async (to, msg) => { replies.push(String(msg || '')); });
    // "Cutucão": no WhatsApp real, se a IA pediu a confirmação do @ e o cliente sumir
    // ~2min, ela manda esse retorno. A página de teste entrega isso após uma contagem
    // curta (cancelável), pra você RECEBER o cutucão sem esperar 2min nem usar o real.
    let nudgePreview = null, nudgeMs = 120000;
    if (result && result.awaitingConfirm) {
      try {
        const wa = require('./whatsappCloud.js');
        nudgeMs = wa.CONFIRM_NUDGE_MS || 120000;
        nudgePreview = wa.buildConfirmNudgeText(result.username);
      } catch (_) {}
    }
    return res.json({ ok: true, phone, openai: agent.isEnabled(), replies, awaitingConfirm: !!(result && result.awaitingConfirm), nudgePreview, nudgeMs });
  } catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'internal' }); }
});

