// Helper: validar hosts permitidos para proxy de imagem
function isAllowedImageHost(urlStr) {
  try {
    const u = new URL(urlStr);
    const host = u.hostname.toLowerCase();
    // Host da self-API de perfil (serve as fotos via /media em HTTP) — liberado para o
    // /image-proxy buscar server-side e entregar em HTTPS (senão dá mixed-content no site).
    try { const selfHost = new URL(SELF_PROFILE_API).hostname.toLowerCase(); if (selfHost && host === selfHost) return true; } catch (_) {}
    return (
      host.includes('instagram') ||
      host.includes('cdninstagram') ||
      host.includes('fbcdn') ||
      host.includes('scontent')
    );
  } catch (e) {
    return false;
  }
}

// Endpoint de proxy de imagem para evitar bloqueios de CSP/Proxy
app.get('/image-proxy', async (req, res) => {
  const targetUrl = req.query.url;
  if (!targetUrl || !isAllowedImageHost(targetUrl)) {
    return res.status(400).send('Invalid image URL');
  }
  try {
    const headersBase = {
      'User-Agent': req.get('User-Agent') || 'Mozilla/5.0',
      'Accept': 'image/*,video/*,*/*;q=0.8'
    };

    const tryFetch = async ({ headers, httpsAgent }) => {
      return axios.get(targetUrl, {
        responseType: 'arraybuffer',
        timeout: 25000,
        headers,
        httpsAgent: httpsAgent || undefined,
        validateStatus: () => true
      });
    };

    let response = await tryFetch({ headers: headersBase });

    if (response.status === 403 || response.status === 429) {
      const now = Date.now();
      const candidates = (cookieProfiles || [])
        .filter(p => p && p.ds_user_id && p.sessionid && (Number(p.disabledUntil || 0) <= now))
        .sort((a, b) => {
          const ea = Number(a.errorCount || 0);
          const eb = Number(b.errorCount || 0);
          if (ea !== eb) return ea - eb;
          return Number(a.lastUsed || 0) - Number(b.lastUsed || 0);
        })
        .slice(0, 3);

      for (const profile of candidates) {
        try {
          const proxyAgent = igBuildProxyAgent(profile);
          const headers = {
            ...headersBase,
            'User-Agent': profile.userAgent || headersBase['User-Agent'],
            'Accept-Language': 'pt-BR,pt;q=0.9,en;q=0.8',
            'Cache-Control': 'no-cache',
            'Pragma': 'no-cache',
            'Referer': 'https://www.instagram.com/',
            'Origin': 'https://www.instagram.com',
            'Cookie': `sessionid=${profile.sessionid}; ds_user_id=${profile.ds_user_id}`
          };
          response = await tryFetch({ headers, httpsAgent: proxyAgent });
          profile.lastUsed = Date.now();
          if (response.status === 200) {
            profile.errorCount = 0;
            break;
          }
          if (response.status === 403 || response.status === 429) {
            profile.errorCount = Number(profile.errorCount || 0) + 1;
          }
        } catch (_) {}
      }
    }

    if (response.status !== 200) {
      return res.status(502).send('Failed to fetch image');
    }

    const contentType = response.headers['content-type'] || 'image/jpeg';
    // Não repassa HTML/erro do CDN como se fosse imagem (renderizava foto branca/quebrada).
    if (/^\s*text\//i.test(contentType)) {
      return res.status(502).send('Failed to fetch image');
    }
    res.setHeader('Content-Type', contentType);
    res.setHeader('Cache-Control', 'public, max-age=3600');
    return res.send(response.data);
  } catch (err) {
    console.error('Erro proxy de imagem:', err.message);
    return res.status(502).send('Failed to fetch image');
  }
});

