// ─────────────────────────────────────────────────────────────────────────────
// REMARKETING WABA — deep-link "engajamento" para quem JÁ COMPROU.
// Reaproveita o recovery token (mesma máquina do email de recuperação de Pix):
// o link curto /engajamento/<slug> resolve o slug -> pedido do cliente e redireciona
// pro checkout já com PERFIL VALIDADO + CUPOM APLICADO + ETAPA 3 (runAuto no front).
// O <slug> é o valor dinâmico {{1}} do template WABA.
// ─────────────────────────────────────────────────────────────────────────────
const REMARKETING_BASE_URL = String(process.env.PUBLIC_BASE_URL || 'https://agenciaoppus.site').replace(/\/+$/, '');

// slug curto url-safe (base62) usando aleatoriedade forte
const genRemarketingSlug = (len) => {
  const alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const n = Math.max(5, Number(len) || 7);
  const bytes = crypto.randomBytes(n);
  let out = '';
  for (let i = 0; i < n; i++) out += alpha[bytes[i] % alpha.length];
  return out;
};

// normaliza telefone BR -> E.164 (55 + DDD + numero). Retorna '' se inválido.
const normalizePhoneBR = (raw) => {
  try {
    let d = String(raw || '').replace(/\D+/g, '');
    if (!d) return '';
    d = d.replace(/^0+/, '');
    // Corrige "+55" DUPLICADO: venda manual do WhatsApp salvava `+55` + número que
    // já vinha com 55 → "5555DDXXXXXXXX" (14/15 díg). Tira um 55 e volta ao normal.
    if ((d.length === 14 || d.length === 15) && d.startsWith('5555')) d = d.slice(2);
    if (d.startsWith('55') && (d.length === 12 || d.length === 13)) return d; // já com DDI
    if (d.length === 10 || d.length === 11) return '55' + d;                   // DDD + numero
    if (d.length === 12 || d.length === 13) return d;                          // provável DDI estrangeiro
    return '';
  } catch (_) { return ''; }
};

// leitor unificado dos campos do pedido (map/array, pago/normal)
const buildOrderFieldGetter = (order) => {
  const mapPaid = (order && order.additionalInfoMapPaid && typeof order.additionalInfoMapPaid === 'object') ? order.additionalInfoMapPaid : {};
  const map = (order && order.additionalInfoMap && typeof order.additionalInfoMap === 'object') ? order.additionalInfoMap : {};
  const arrPaid = Array.isArray(order && order.additionalInfoPaid) ? order.additionalInfoPaid : [];
  const arr = Array.isArray(order && order.additionalInfo) ? order.additionalInfo : [];
  const fromArr = (a, k) => { const it = a.find(x => x && String(x.key || '').trim() === k); return it ? it.value : undefined; };
  return (k) => {
    if (typeof mapPaid[k] !== 'undefined') return mapPaid[k];
    if (typeof map[k] !== 'undefined') return map[k];
    const v1 = fromArr(arrPaid, k);
    if (typeof v1 !== 'undefined') return v1;
    return fromArr(arr, k);
  };
};

// Cria OU RENOVA ("recicla") um cupom de remarketing com janela de N dias.
// Reaproveita o schema de cupom existente (validFrom/validTo já são respeitados por
// getCouponEligibility → "Cupom expirado"). Chamar de novo com o mesmo código = reciclar.
const ensureRemarketingCoupon = async (code, pct, days) => {
  const c = normalizeCouponCode(code);
  const p = Math.max(1, Math.min(95, Math.round(Number(pct) || 0)));
  const d = Math.max(1, Math.min(30, Number(days) || 2));
  if (!c || !p) return null;
  const couponsCol = await getCollection('coupons');
  const now = new Date();
  const validTo = new Date(now.getTime() + d * 24 * 60 * 60 * 1000);
  await couponsCol.updateOne(
    { code: c },
    {
      $set: { code: c, discountPercentage: p, validFrom: now, validTo, isActive: true, maxUsesPerProfile: 1, remarketing: true, updatedAt: now },
      $setOnInsert: { usedCount: 0, createdAt: now, maxUsesTotal: null, blockedServices: [] }
    },
    { upsert: true }
  );
  return { code: c, pct: p, validFrom: now, validTo };
};

// ═══════════════════════════════════════════════════════════════════
//  CUPONS DE LTV — pool de rodízio, NÃO expiram, 1 uso por perfil.
//  Fonte única de verdade: generate, dispatch, D+2 e o painel derivam daqui.
// ═══════════════════════════════════════════════════════════════════
const LTV_COUPON_POOL = [
  { code: 'VOLTA20',   pct: 20 },
  { code: 'VOLTA15',   pct: 15 },
  { code: 'RETORNO20', pct: 20 },
  { code: 'RETORNO15', pct: 15 },
  { code: 'DEVOLTA20', pct: 20 },
  { code: 'DEVOLTA15', pct: 15 },
];
const LTV_POOL_CODES = LTV_COUPON_POOL.map(c => c.code);

// Cria/atualiza um cupom de LTV SEM expiração (validTo removido) e 1 uso por perfil.
const ensureLtvCoupon = async (code, pct) => {
  const c = normalizeCouponCode(code);
  const p = Math.max(1, Math.min(95, Math.round(Number(pct) || 0)));
  if (!c || !p) return null;
  const couponsCol = await getCollection('coupons');
  const now = new Date();
  await couponsCol.updateOne(
    { code: c },
    {
      // getCouponEligibility só bloqueia por validade SE validTo existir → removendo, nunca expira.
      $set: { code: c, discountPercentage: p, validFrom: now, isActive: true, maxUsesPerProfile: 1, remarketing: true, ltv: true, updatedAt: now },
      $unset: { validTo: '' },
      $setOnInsert: { usedCount: 0, createdAt: now, maxUsesTotal: null, blockedServices: [] }
    },
    { upsert: true }
  );
  return { code: c, pct: p };
};
const ensureLtvCouponPool = async () => { for (const x of LTV_COUPON_POOL) { try { await ensureLtvCoupon(x.code, x.pct); } catch (_) {} } };

// Escolhe, para um perfil, o 1º cupom do pool que ele AINDA NÃO usou (respeita 1 uso/perfil).
// Assim, cliente que volta várias vezes sempre recebe um cupom válido e diferente.
// Sem perfil (ou já usou todos): cai no rodízio por índice.
async function pickLtvCouponForProfile(profileKey, idx = 0) {
  try {
    const pk = normalizeProfileKey(profileKey || '');
    if (pk) {
      const couponsCol = await getCollection('coupons');
      const usesCol = await getCollection('coupon_uses');
      const poolDocs = await couponsCol.find({ code: { $in: LTV_POOL_CODES } }, { projection: { _id: 1, code: 1 } }).toArray();
      if (poolDocs.length) {
        const idByCode = new Map(poolDocs.map(d => [String(d.code), d._id]));
        const usedIds = await usesCol.distinct('couponId', { profileKey: pk, status: 'consumed', couponId: { $in: poolDocs.map(d => d._id) } });
        const usedSet = new Set((usedIds || []).map(String));
        for (const x of LTV_COUPON_POOL) { const id = idByCode.get(x.code); if (id && !usedSet.has(String(id))) return { code: x.code, pct: x.pct }; }
      }
    }
  } catch (_) {}
  const n = LTV_COUPON_POOL.length;
  const pick = LTV_COUPON_POOL[((idx % n) + n) % n] || LTV_COUPON_POOL[0];
  return { code: pick.code, pct: pick.pct };
}

// Rota pública do link curto do WhatsApp. NÃO conflita com /engajamento (exato) nem /engajamento-novo.
app.get('/engajamento/:slug', async (req, res) => {
  try {
    let slug = String(req.params.slug || '').trim();
    // Tolera template com botão mal-configurado (URL virou /engajamento/{{1}}<slug>): remove
    // qualquer prefixo "{{...}}" que tenha sobrado na frente do slug real antes de validar.
    slug = slug.replace(/^(?:\{\{[^}]*\}\})+/, '').trim();
    if (!/^[A-Za-z0-9]{4,40}$/.test(slug)) return res.redirect(302, '/servicos-instagram');
    const links = await getCollection('remarketing_links');
    const doc = links ? await links.findOne({ slug }) : null;
    if (!doc || !doc.token) return res.redirect(302, '/servicos-instagram?src=waba_remarketing');
    // rastreia o clique (não bloqueia o redirect se falhar)
    try {
      const now = new Date();
      await links.updateOne({ slug }, { $inc: { clicks: 1 }, $set: { lastClickAt: now }, $min: { firstClickAt: now } });
      // Clique DURÁVEL no ltv_contacts (o link some após 2 dias, mas o clique fica).
      if (String(doc.campaign || '') === 'ltv' && doc.phoneE164) {
        try { const contacts = await getCollection('ltv_contacts'); await contacts.updateOne({ phoneE164: String(doc.phoneE164) }, { $inc: { clicks: 1 }, $set: { lastClickAt: now } }, { upsert: true }); } catch (_) {}
      }
    } catch (_) {}
    // Redireciona pro checkout com o recovery token -> front valida perfil + aplica cupom + etapa 3.
    // Sem autopix (decisão: cliente vê o total com desconto e decide).
    const qs = new URLSearchParams();
    qs.set('rt', doc.token);
    qs.set('src', 'waba_remarketing');
    if (doc.campaign) qs.set('rmk', String(doc.campaign));

    // Destino pela CATEGORIA do último pedido: curtidas/visualizações vão para a
    // própria página (o front mira o MESMO post do último pedido); senão seguidores.
    let destPath = '/servicos-instagram';
    try {
      const ident = String(doc.identifier || '').trim();
      const corr = String(doc.correlationID || '').trim();
      const conds = [];
      if (ident) { conds.push({ identifier: ident }, { 'paghiper.transactionId': ident }, { 'woovi.identifier': ident }, { 'expay.transactionId': ident }); }
      if (corr) conds.push({ correlationID: corr });
      if (conds.length) {
        const col = await getCollection('checkout_orders');
        const ord = await col.findOne({ $or: conds }, { projection: { additionalInfoMapPaid: 1, additionalInfoMap: 1, additionalInfoPaid: 1, additionalInfo: 1, tipoServico: 1, tipo: 1 } });
        if (ord) {
          const getAdd = buildOrderFieldGetter(ord);
          const cat = String(getAdd('categoria_servico') || '').trim().toLowerCase();
          if (cat === 'curtidas') destPath = '/servicos-curtidas';
          else if (cat === 'visualizacoes') destPath = '/servicos-visualizacoes';
        }
      }
    } catch (_) {}
    return res.redirect(302, destPath + '?' + qs.toString());
  } catch (e) {
    return res.redirect(302, '/servicos-instagram?src=waba_remarketing');
  }
});

// ADMIN: gera a campanha de remarketing (tokens + slugs + links) a partir de quem já comprou seguidores.
app.post('/api/painel/remarketing/generate', requireAdmin, async (req, res) => {
  try {
    const b = (req.body && typeof req.body === 'object') ? req.body : {};
    const campaign = (String(b.campaign || '').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '_').slice(0, 60)) || 'engajamento';
    const coupon = String(b.coupon || '').trim().toUpperCase().slice(0, 40);
    const couponPct = Math.max(0, Math.min(95, Number(b.couponPct || 0) || 0));
    const couponDays = Math.max(1, Math.min(30, Number(b.couponDays || 2) || 2));  // validade do CUPOM (urgência)
    const expDays = Math.max(1, Math.min(365, Number(b.expDays || 2) || 2));         // validade do LINK/token (padrão = igual ao cupom)
    const limit = Math.max(0, Math.min(100000, Number(b.limit || 0) || 0));
    const dryRun = (b.dryRun === true || String(b.dryRun || '') === '1');
    const requestedBy = (req.session && req.session.adminUser && req.session.adminUser.username) ? String(req.session.adminUser.username) : 'admin';

    // Cria/renova ("recicla") o cupom da campanha com janela de couponDays (padrão 2 dias).
    let couponInfo = null;
    if (coupon && couponPct > 0 && !dryRun) {
      try { couponInfo = await ensureRemarketingCoupon(coupon, couponPct, couponDays); } catch (_) {}
    }

    const col = await getCollection('checkout_orders');
    const links = await getCollection('remarketing_links');

    // índice de slug único (idempotente)
    try { await links.createIndex({ slug: 1 }, { unique: true }); } catch (_) {}
    try { await links.createIndex({ campaign: 1, phoneE164: 1 }, { unique: false }); } catch (_) {}

    const paidOr = [
      { status: 'pago' }, { 'woovi.status': 'pago' },
      { paidAt: { $exists: true, $nin: [null, ''] } },
      { 'woovi.paidAt': { $exists: true, $nin: [null, ''] } },
      { 'paghiper.paidAt': { $exists: true, $nin: [null, ''] } }
    ];
    const projection = {
      customer: 1, additionalInfoMapPaid: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfo: 1,
      tipo: 1, tipoServico: 1, instagramUsername: 1, instauser: 1,
      identifier: 1, correlationID: 1, 'woovi.identifier': 1, 'woovi.paidAt': 1,
      'paghiper.transactionId': 1, 'paghiper.paidAt': 1, 'expay.transactionId': 1, paidAt: 1, createdAt: 1
    };
    const cursor = col.find({ $or: paidOr }, { projection }).sort({ 'woovi.paidAt': -1, paidAt: -1, createdAt: -1, _id: -1 }).limit(50000);
    const orders = await cursor.toArray();

    // pré-carrega links já existentes dessa campanha (reaproveita slug/token já disparados)
    const existing = await links.find({ campaign }, { projection: { phoneE164: 1, slug: 1, token: 1, instagram_username: 1, name: 1 } }).toArray();
    const existingByPhone = new Map();
    for (const e of existing) { if (e && e.phoneE164) existingByPhone.set(String(e.phoneE164), e); }

    const seen = new Set();      // phoneE164 já processados nesta geração
    const result = [];
    const stats = { scanned: orders.length, eligible: 0, created: 0, reused: 0, skip_no_phone: 0, skip_no_ig: 0, skip_not_seguidores: 0, skip_no_identifier: 0, skip_dup: 0 };

    const isSeguidores = (categoria, tipo) => {
      const c = String(categoria || '').toLowerCase();
      const t = String(tipo || '').toLowerCase();
      if (/curtida|like|visualiz|view|reel|coment/.test(c)) return false;
      if (c === 'seguidores') return true;
      if (t === 'mistos' || t === 'brasileiros' || t === 'organicos') return true;
      return false;
    };

    for (const order of orders) {
      const getAdd = buildOrderFieldGetter(order);
      const categoria = String(getAdd('categoria_servico') || '').trim();
      const tipo = String(getAdd('tipo_servico') || getAdd('tipoServico') || getAdd('tipo') || order.tipoServico || order.tipo || '').trim();
      if (!isSeguidores(categoria, tipo)) { stats.skip_not_seguidores++; continue; }

      const customer = (order.customer && typeof order.customer === 'object') ? order.customer : {};
      const phoneRaw = getAdd('phone') || getAdd('telefone') || getAdd('whatsapp') || customer.phone || customer.telefone || customer.whatsapp || '';
      const phoneE164 = normalizePhoneBR(phoneRaw);
      if (!phoneE164) { stats.skip_no_phone++; continue; }
      if (seen.has(phoneE164)) { stats.skip_dup++; continue; }

      const igRaw = String(
        getAdd('instagram_username') || getAdd('instagramUsername') || getAdd('username') ||
        getAdd('perfil') || getAdd('instagram') || order.instagramUsername || order.instauser || ''
      ).replace(/^@+/, '').replace(/\/+$/g, '').trim();
      if (!igRaw) { stats.skip_no_ig++; continue; }

      const identifier = String(order.identifier || (order.woovi && order.woovi.identifier) || (order.expay && order.expay.transactionId) || (order.paghiper && order.paghiper.transactionId) || '').trim();
      const correlationID = String(order.correlationID || '').trim();
      if (!identifier && !correlationID) { stats.skip_no_identifier++; continue; }

      seen.add(phoneE164);
      stats.eligible++;

      const name = String(customer.name || customer.nome || getAdd('nome') || getAdd('name') || '').trim();

      // reaproveita link já existente da campanha (mantém válido o que já foi enviado)
      const prev = existingByPhone.get(phoneE164);
      let slug, token;
      if (prev && prev.slug && prev.token) {
        slug = prev.slug; token = prev.token; stats.reused++;
      } else {
        token = signRecoveryToken({ identifier, correlationID, exp: Date.now() + expDays * 24 * 60 * 60 * 1000, coupon, couponPct });
        // slug único (poucas tentativas bastam)
        slug = genRemarketingSlug(7);
        stats.created++;
        if (!dryRun) {
          let inserted = false;
          for (let attempt = 0; attempt < 5 && !inserted; attempt++) {
            try {
              await links.insertOne({
                slug, campaign, token, phone: String(phoneRaw || '').trim(), phoneE164,
                instagram_username: igRaw, name, coupon, couponPct,
                identifier, correlationID, orderId: String(order._id || ''),
                createdAt: new Date(), createdBy: requestedBy,
                expAt: new Date(Date.now() + expDays * 24 * 60 * 60 * 1000),
                clicks: 0, sent: false
              });
              inserted = true;
            } catch (e) {
              if (e && e.code === 11000) { slug = genRemarketingSlug(7); } else { throw e; }
            }
          }
        }
      }

      const link = `${REMARKETING_BASE_URL}/engajamento/${slug}`;
      result.push({ phone: phoneE164, name, instagram_username: igRaw, slug, param1: slug, link, coupon });
      if (limit && result.length >= limit) break;
    }

    return res.json({
      ok: true, campaign, coupon, couponPct, couponDays, expDays, dryRun,
      couponValidTo: couponInfo ? couponInfo.validTo : null,
      total: result.length, stats,
      exportUrl: `/api/painel/remarketing/export?campaign=${encodeURIComponent(campaign)}`,
      sample: result.slice(0, 10)
    });
  } catch (e) {
    console.error('❌ remarketing/generate:', e && e.message);
    return res.status(500).json({ ok: false, error: 'internal_error', message: String(e && e.message || e) });
  }
});

// ADMIN: lista/estatísticas de uma campanha
app.get('/api/painel/remarketing/list', requireAdmin, async (req, res) => {
  try {
    const campaign = String(req.query.campaign || '').trim().toLowerCase();
    const links = await getCollection('remarketing_links');
    const q = campaign ? { campaign } : {};
    const rows = await links.find(q, { projection: { token: 0 } }).sort({ createdAt: -1 }).limit(5000).toArray();
    const campaigns = await links.distinct('campaign');
    const clicked = rows.filter(r => Number(r.clicks) > 0).length;
    const totalClicks = rows.reduce((a, r) => a + (Number(r.clicks) || 0), 0);
    const sentCount = rows.filter(r => !!r.sent).length;
    const failedCount = rows.filter(r => !r.sent && r.sendError).length;
    return res.json({
      ok: true, campaign, campaigns,
      total: rows.length, clicked, totalClicks, sentCount, failedCount,
      rows: rows.map(r => ({
        slug: r.slug, phone: r.phoneE164 || r.phone, name: r.name || '',
        instagram_username: r.instagram_username || '', coupon: r.coupon || '',
        clicks: Number(r.clicks) || 0, lastClickAt: r.lastClickAt || null, sent: !!r.sent,
        sendError: r.sendError || '',
        link: `${REMARKETING_BASE_URL}/engajamento/${r.slug}`
      }))
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: 'internal_error' });
  }
});

// ADMIN: exporta CSV da campanha (telefone + {{1}} + link) pro disparo no WABA
app.get('/api/painel/remarketing/export', requireAdmin, async (req, res) => {
  try {
    const campaign = String(req.query.campaign || '').trim().toLowerCase();
    if (!campaign) return res.status(400).send('campaign obrigatório');
    const links = await getCollection('remarketing_links');
    const rows = await links.find({ campaign }, { projection: { token: 0 } }).sort({ createdAt: 1 }).limit(100000).toArray();
    const esc = (v) => {
      const s = String(v == null ? '' : v);
      return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const header = ['phone', 'name', 'instagram_username', 'param1_slug', 'full_link', 'coupon', 'clicks', 'sent'];
    const lines = [header.join(',')];
    for (const r of rows) {
      lines.push([
        esc(r.phoneE164 || r.phone), esc(r.name || ''), esc(r.instagram_username || ''),
        esc(r.slug), esc(`${REMARKETING_BASE_URL}/engajamento/${r.slug}`),
        esc(r.coupon || ''), esc(Number(r.clicks) || 0), esc(r.sent ? '1' : '0')
      ].join(','));
    }
    res.set('Content-Type', 'text/csv; charset=utf-8');
    res.set('Content-Disposition', `attachment; filename="remarketing_${campaign}.csv"`);
    return res.send('﻿' + lines.join('\n'));
  } catch (e) {
    return res.status(500).send('erro ao exportar');
  }
});

// ADMIN: renova ("recicla") a janela de validade de um cupom de remarketing
app.post('/api/painel/remarketing/coupon/refresh', requireAdmin, async (req, res) => {
  try {
    const b = (req.body && typeof req.body === 'object') ? req.body : {};
    const code = String(b.code || '').trim();
    const pct = Number(b.pct || b.couponPct || 0) || 0;
    const days = Number(b.days || b.couponDays || 2) || 2;
    if (!code || !pct) return res.status(400).json({ ok: false, error: 'missing', message: 'Informe código e %.' });
    const info = await ensureRemarketingCoupon(code, pct, days);
    if (!info) return res.status(400).json({ ok: false, error: 'invalid' });
    return res.json({ ok: true, code: info.code, pct: info.pct, validFrom: info.validFrom, validTo: info.validTo });
  } catch (e) {
    return res.status(500).json({ ok: false, error: 'internal_error' });
  }
});

// ADMIN: status do pool de cupons de remarketing (quais estão ativos/expirados e quanto falta)
app.get('/api/painel/remarketing/coupons', requireAdmin, async (req, res) => {
  try {
    const couponsCol = await getCollection('coupons');
    const rows = await couponsCol.find({ $or: [{ remarketing: true }, { code: /^VOLTA/i }] }).sort({ code: 1 }).toArray();
    const now = Date.now();
    return res.json({
      ok: true,
      coupons: rows.map(c => {
        const toMs = c.validTo ? new Date(c.validTo).getTime() : 0;
        const fromMs = c.validFrom ? new Date(c.validFrom).getTime() : 0;
        const notYet = fromMs && now < fromMs;
        const expired = toMs && now > toMs;
        const active = (c.isActive !== false) && !notYet && !expired;
        const hoursLeft = (toMs && toMs > now) ? Math.round(((toMs - now) / 3600000) * 10) / 10 : 0;
        return { code: c.code, pct: c.discountPercentage || 0, validTo: c.validTo || null, active, expired: !!expired, hoursLeft, usedCount: c.usedCount || 0 };
      })
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: 'internal_error' });
  }
});

// ADMIN: processa os bounces (DSN) da caixa e suprime os endereços mortos. Roda em background.
app.post('/api/painel/email/process-bounces', requireAdmin, async (req, res) => {
  try {
    if (!getImapConfig()) return res.status(400).json({ ok: false, error: 'no_imap_config', message: 'Sem IMAP configurado (IMAP_* ou SMTP_*).' });
    if (__bounceJob.running) return res.status(409).json({ ok: false, error: 'already_running', job: __bounceJob });
    const onlyUnseen = !(req.body && (req.body.all === true || String(req.body.all) === '1'));
    const max = Math.max(1, Math.min(20000, Number(req.body && req.body.max || 2000) || 2000));
    processEmailBounces({ onlyUnseen, max }).catch(() => {}); // background
    return res.json({ ok: true, started: true, onlyUnseen });
  } catch (e) { return res.status(500).json({ ok: false, error: 'internal_error' }); }
});
app.get('/api/painel/email/process-bounces/status', requireAdmin, (req, res) => {
  return res.json({ ok: true, job: __bounceJob });
});
app.get('/api/painel/email/suppression-stats', requireAdmin, async (req, res) => {
  try {
    const col = await getCollection('email_suppression');
    const total = await col.countDocuments({});
    const byReason = await col.aggregate([{ $group: { _id: '$lastReason', n: { $sum: 1 } } }, { $sort: { n: -1 } }, { $limit: 20 }]).toArray();
    return res.json({ ok: true, total, byReason: byReason.map(r => ({ reason: r._id || '(sem)', n: r.n })) });
  } catch (e) { return res.status(500).json({ ok: false, error: 'internal_error' }); }
});

// ─── Envio integrado via Meta WhatsApp Cloud API ───
// Credenciais (SECRETAS) vêm do .env: WHATSAPP_PHONE_NUMBER_ID, WHATSAPP_ACCESS_TOKEN, WHATSAPP_API_VERSION.
// Config do template (NÃO secreta) fica em settings.key='waba_remarketing': { name, language, bodyFields }.
const getWabaConfig = async () => {
  const phoneId = String(process.env.WHATSAPP_PHONE_NUMBER_ID || '').trim();
  const token = String(process.env.WHATSAPP_ACCESS_TOKEN || '').trim();
  const version = String(process.env.WHATSAPP_API_VERSION || 'v21.0').trim();
  let tpl = { name: '', language: 'pt_BR', bodyFields: [] };
  try {
    const settings = await getCollection('settings');
    const doc = settings ? await settings.findOne({ key: 'waba_remarketing' }) : null;
    if (doc && doc.value && typeof doc.value === 'object') tpl = Object.assign(tpl, doc.value);
  } catch (_) {}
  return { phoneId, token, version, tpl, configured: !!(phoneId && token) };
};

// ── Analytics OFICIAL da Meta (WABA) — MESMA fonte da tela "Insights sobre entrega
//    de mensagens". Retorna enviadas/entregues no período (soma + por dia). É o número
//    assertivo que casa com a cobrança da Meta. Cache em memória (TTL 1h): os números
//    da Meta têm lag de horas e isso evita bater na API a cada refresh do painel.
//    Requer WHATSAPP_BUSINESS_ACCOUNT_ID no .env. Best-effort: nunca lança. ──
const __wabaAnalyticsCache = new Map(); // `${startSec}_${endSec}` → { at, data }
const WABA_ANALYTICS_TTL_MS = 60 * 60 * 1000;
async function fetchWabaMetaAnalytics(startMs, endMs) {
  const wabaId = String(process.env.WHATSAPP_BUSINESS_ACCOUNT_ID || '').trim();
  const token = String(process.env.WHATSAPP_ACCESS_TOKEN || '').trim();
  const version = String(process.env.WHATSAPP_API_VERSION || 'v21.0').trim();
  if (!wabaId || !token) return { configured: false };
  const startSec = Math.floor(Number(startMs) / 1000);
  const endSec = Math.floor(Number(endMs) / 1000);
  if (!(startSec > 0 && endSec > startSec)) return { configured: true, ok: false, error: 'periodo_invalido' };
  const key = startSec + '_' + endSec;
  const hit = __wabaAnalyticsCache.get(key);
  if (hit && (Date.now() - hit.at) < WABA_ANALYTICS_TTL_MS) return hit.data;
  let data;
  try {
    const axios = require('axios');
    const url = `https://graph.facebook.com/${version}/${wabaId}`;
    const field = `analytics.start(${startSec}).end(${endSec}).granularity(DAY)`;
    const resp = await axios.get(url, { params: { access_token: token, fields: field }, timeout: 8000, validateStatus: () => true });
    if (!resp || resp.status < 200 || resp.status >= 300 || !resp.data || resp.data.error) {
      data = { configured: true, ok: false, error: (resp && resp.data && resp.data.error && resp.data.error.message) || ('HTTP ' + (resp && resp.status)) };
    } else {
      const dp = (resp.data.analytics && resp.data.analytics.data_points) || [];
      let sent = 0, delivered = 0; const byDay = [];
      for (const d of dp) { const s = Number(d.sent) || 0, de = Number(d.delivered) || 0; sent += s; delivered += de; byDay.push({ start: d.start, sent: s, delivered: de }); }
      data = { configured: true, ok: true, sent, delivered, byDay, syncedAt: new Date().toISOString() };
    }
  } catch (e) {
    data = { configured: true, ok: false, error: (e && e.message) || 'net' };
  }
  __wabaAnalyticsCache.set(key, { at: Date.now(), data });
  return data;
}

// Envia UM template com o botão de URL dinâmico (index 0) = slug, e opcionalmente variáveis do corpo.
const sendWabaTemplate = async (cfg, to, slug, bodyValues) => {
  const axios = require('axios');
  const url = `https://graph.facebook.com/${cfg.version}/${cfg.phoneId}/messages`;
  const components = [];
  if (Array.isArray(bodyValues) && bodyValues.length) {
    components.push({ type: 'body', parameters: bodyValues.map(v => ({ type: 'text', text: String(v == null ? '' : v) })) });
  }
  components.push({ type: 'button', sub_type: 'url', index: '0', parameters: [{ type: 'text', text: String(slug) }] });
  const payload = { messaging_product: 'whatsapp', to: String(to), type: 'template', template: { name: cfg.tpl.name, language: { code: cfg.tpl.language || 'pt_BR' }, components } };
  return axios.post(url, payload, { headers: { Authorization: 'Bearer ' + cfg.token, 'Content-Type': 'application/json' }, timeout: 20000, validateStatus: () => true });
};

// Envia mensagem de TEXTO LIVRE (só permitido dentro da janela de 24h da Meta —
// quando o cliente mandou mensagem nas últimas 24h). Usado pela resposta do CRM.
const sendWhatsappText = async (cfg, to, text) => {
  const axios = require('axios');
  const url = `https://graph.facebook.com/${cfg.version}/${cfg.phoneId}/messages`;
  const payload = { messaging_product: 'whatsapp', to: String(to), type: 'text', text: { preview_url: false, body: String(text || '').slice(0, 4096) } };
  return axios.post(url, payload, { headers: { Authorization: 'Bearer ' + cfg.token, 'Content-Type': 'application/json' }, timeout: 20000, validateStatus: () => true });
};

// Faz upload de um arquivo (buffer) para a Meta e devolve o media id. Usado pelo CRM
// para enviar imagem/vídeo/áudio (o envio por id é o fluxo recomendado da Cloud API).
const uploadWhatsappMedia = async (cfg, buffer, mime, filename) => {
  const axios = require('axios');
  const FormDataLib = require('form-data');
  const url = `https://graph.facebook.com/${cfg.version}/${cfg.phoneId}/media`;
  const form = new FormDataLib();
  form.append('messaging_product', 'whatsapp');
  form.append('type', String(mime || 'application/octet-stream'));
  form.append('file', buffer, { filename: filename || 'file', contentType: String(mime || 'application/octet-stream') });
  const resp = await axios.post(url, form, { headers: Object.assign({ Authorization: 'Bearer ' + cfg.token }, form.getHeaders()), maxBodyLength: Infinity, maxContentLength: Infinity, timeout: 60000, validateStatus: () => true });
  if (resp && resp.status >= 200 && resp.status < 300 && resp.data && resp.data.id) return { ok: true, id: String(resp.data.id) };
  const em = (resp && resp.data && resp.data.error) ? (resp.data.error.message || JSON.stringify(resp.data.error)) : ('HTTP ' + (resp && resp.status));
  return { ok: false, message: String(em).slice(0, 300) };
};

// Envia uma mensagem de MÍDIA (imagem/vídeo/áudio) por media id — só dentro da janela
// de 24h da Meta. caption só vale para imagem/vídeo.
const sendWhatsappMedia = async (cfg, to, kind, mediaId, caption, filename) => {
  const axios = require('axios');
  const url = `https://graph.facebook.com/${cfg.version}/${cfg.phoneId}/messages`;
  const media = { id: String(mediaId) };
  if (caption && (kind === 'image' || kind === 'video' || kind === 'document')) media.caption = String(caption).slice(0, 1024);
  if (kind === 'document' && filename) media.filename = String(filename).slice(0, 240);
  const payload = { messaging_product: 'whatsapp', to: String(to), type: kind, [kind]: media };
  return axios.post(url, payload, { headers: { Authorization: 'Bearer ' + cfg.token, 'Content-Type': 'application/json' }, timeout: 30000, validateStatus: () => true });
};

