    const b = (req.body && typeof req.body === 'object') ? req.body : {};
    const minPurchases = Math.max(2, Math.min(20, Number(b.minPurchases || 2) || 2));
    // Validade do link/cupom: 2 dias (bate com a cópia do template "Válido por 2 dias").
    const expDays = Math.max(1, Math.min(60, Number(b.expDays || 2) || 2));
