// ── Webhook do WhatsApp (opt-out). Recebe direto OU repassado pelo famaapp.site. ──
// Verificação (Meta chama com hub.challenge). Verify token no .env: WHATSAPP_WEBHOOK_VERIFY_TOKEN.
app.get('/api/whatsapp/webhook', (req, res) => {
  const mode = String(req.query['hub.mode'] || '');
  const token = String(req.query['hub.verify_token'] || '');
  const challenge = req.query['hub.challenge'];
  const expected = String(process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN || '');
  // Sem token configurado → rejeita sempre (não deixa passar com token vazio).
  if (expected && mode === 'subscribe' && token === expected) return res.status(200).send(String(challenge == null ? '' : challenge));
  return res.sendStatus(403);
});
// Recebimento: qualquer resposta de opt-out (botão "Não tenho interesse", "sair", etc.) → suprime o telefone.
app.post('/api/whatsapp/webhook', async (req, res) => {
  res.sendStatus(200); // responde rápido sempre (Meta exige 200 em segundos)
  try {
    // Quando WHATSAPP_FORWARD_SECRET está definido, só aceita encaminhamento autenticado (header).
    const fwdSecret = String(process.env.WHATSAPP_FORWARD_SECRET || '');
    if (fwdSecret && String(req.headers['x-oppus-forward-token'] || '') !== fwdSecret) return;
    const ltvPid = String(process.env.WHATSAPP_PHONE_NUMBER_ID || '').trim();
    const body = (req.body && typeof req.body === 'object') ? req.body : {};
    const entries = Array.isArray(body.entry) ? body.entry : [];
    for (const e of entries) {
      const changes = Array.isArray(e.changes) ? e.changes : [];
      for (const ch of changes) {
        const val = (ch && ch.value) || {};
        // Defesa: só processa eventos do NOSSO número (LTV), mesmo se vier corpo misto.
        const pid = String((val.metadata && val.metadata.phone_number_id) || '').trim();
        if (ltvPid && pid && pid !== ltvPid) continue;
        const msgs = Array.isArray(val.messages) ? val.messages : [];
        // Nome de perfil do WhatsApp que a Meta manda junto (val.contacts).
        const profileNameByWa = {};
        for (const ct of (Array.isArray(val.contacts) ? val.contacts : [])) { try { const wa = String((ct && ct.wa_id) || ''); const nm = String((ct && ct.profile && ct.profile.name) || ''); if (wa) profileNameByWa[wa] = nm; } catch (_) {} }
        for (const m of msgs) {
          const from = m && m.from;
          const mtype = String((m && m.type) || 'text');
          let text = '';
          if (mtype === 'button' && m.button) text = m.button.text || m.button.payload || '';
          else if (mtype === 'interactive' && m.interactive) { const i = m.interactive; text = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || ''; }
          else if (mtype === 'text' && m.text) text = m.text.body || '';
          else if (mtype === 'image') text = '[imagem]' + (m.image && m.image.caption ? (' ' + m.image.caption) : '');
          else if (mtype === 'audio') text = '[áudio]';
          else if (mtype === 'video') text = '[vídeo]' + (m.video && m.video.caption ? (' ' + m.video.caption) : '');
          else if (mtype === 'document') text = '[documento]' + (m.document && m.document.filename ? (' ' + m.document.filename) : '');
          else if (mtype === 'sticker') text = '[figurinha]';
          else if (mtype === 'location') text = '[localização]';
          else if (mtype === 'contacts') text = '[contato]';
          else if (mtype === 'reaction' && m.reaction) text = (m.reaction.emoji || '') + ' (reação)';
          else text = '[' + mtype + ']';
          // Mídia recebida: captura o media id + mime da Meta (para tocar/ver no CRM via proxy).
          let mediaId = '', mime = '';
          try {
            const mo = (m && m[mtype] && typeof m[mtype] === 'object') ? m[mtype] : null;
            if (mo && (mtype === 'image' || mtype === 'audio' || mtype === 'video' || mtype === 'document' || mtype === 'sticker' || mtype === 'voice')) {
              mediaId = String(mo.id || '').trim();
              mime = String(mo.mime_type || '').trim();
            }
          } catch (_) {}
          if (from) {
            if (isHardOptOut(text)) await markWhatsappOptOut(from, 'hard:' + String(text).slice(0, 60));
            else if (isSoftReject(text)) await registerWhatsappRejection(from, 'soft:' + String(text).slice(0, 60));
            // CRM: salva a resposta recebida (best-effort, nunca quebra o webhook).
            try {
              const ctx = await lookupWaContact(String(from), normOptoutPhone(from));
              await logWaMessage({ phone: String(from), phoneE164: String(from), direction: 'in', type: mtype, text, mediaId, mime, wamid: (m && m.id), campaign: 'ltv', name: ctx.name || profileNameByWa[String(from)] || '', ig: ctx.ig, ts: (m && m.timestamp) ? Number(m.timestamp) * 1000 : null });
            } catch (_) {}
          }
        }
      }
    }
  } catch (_) {}
});
