// Webhook público que recebe as atualizações de status das notas da Spedy.
// Protegido por um token compartilhado (SPEEDY_WEBHOOK_TOKEN) enviado via
// query (?token=), header (x-spedy-token) ou no path (/api/spedy/webhook/:token).
async function _handleSpedyWebhook(req, res) {
  try {
    const expected = String(process.env.SPEEDY_WEBHOOK_TOKEN || '').trim();
    if (expected) {
      const got = String(
        req.query?.token || req.headers['x-spedy-token'] || req.params?.token || ''
      ).trim();
      if (got !== expected) {
        return res.status(401).json({ ok: false, error: 'invalid_token' });
      }
    }
    const col = await getCollection('checkout_orders');
    const result = await notaFiscalManager.handleWebhookEvent(req.body || {}, col);
    // Sempre 200 para a Spedy não reenfileirar em casos de "pedido não encontrado".
    return res.status(200).json({ ok: true, result });
  } catch (e) {
    console.error('[Spedy][webhook] erro:', e?.message);
    return res.status(200).json({ ok: false, error: 'internal_error' });
  }
}
app.post('/api/spedy/webhook', _handleSpedyWebhook);
app.post('/api/spedy/webhook/:token', _handleSpedyWebhook);

