// Corrige CPF (e opcionalmente endereço) de um pedido e, se pedido, reemite.
app.post('/api/admin/fiscal/set-cpf/:orderId', requireAdmin, async (req, res) => {
  try {
    const id = String(req.params.orderId || '').trim();
    if (!/^[0-9a-fA-F]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'invalid_order_id' });
    const cpf = String(req.body?.cpf || req.query?.cpf || '').replace(/\D/g, '');
    if (cpf.length !== 11 && cpf.length !== 14) return res.status(400).json({ ok: false, error: 'cpf_invalido' });
    const col = await getCollection('checkout_orders');
    const oid = new (require('mongodb').ObjectId)(id);
    const record = await col.findOne({ _id: oid });
    if (!record) return res.status(404).json({ ok: false, error: 'order_not_found' });

    const set = { 'customer.cpf': cpf, 'fiscalData.cpf': cpf, 'fiscalData.cpfManual': true, 'fiscalData.updatedAt': new Date().toISOString() };
    await col.updateOne({ _id: oid }, { $set: set });

    let emit = null;
    if (String(req.query.reemitir || req.body?.reemitir || '') === 'true') {
      const fresh = await col.findOne({ _id: oid });
      emit = await notaFiscalManager.emitirNotaParaPedido(fresh, col, { force: true });
    }
    return res.json({ ok: true, cpf, emit });
  } catch (e) { return res.status(500).json({ ok: false, error: e && e.message }); }
});

// Página do painel: Notas Fiscais (represadas / com erro / emitidas)
app.get('/painel/notas-fiscais', requireAdmin, async (req, res) => {
  try {
    const col = await getCollection('checkout_orders');
    const state = String(req.query.state || 'held');
    const q = state === 'all'
      ? { 'notaFiscal': { $exists: true } }
      : { 'notaFiscal.emissionState': state };
    const docs = await col.find(q, {
      projection: {
        customer: 1, instauser: 1, instagramUsername: 1, valueCents: 1,
        paidAt: 1, criado: 1, createdAt: 1, notaFiscal: 1, fiscalData: 1,
        additionalInfoMapPaid: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfo: 1,
      },
    }).sort({ 'notaFiscal.updatedAt': -1 }).limit(500).toArray();

    const countBy = async (st) => { try { return await col.countDocuments({ 'notaFiscal.emissionState': st }); } catch (_) { return 0; } };
    const counts = {
      held: await countBy('held'),
      error: await countBy('error'),
      enqueued: await countBy('enqueued'),
      authorized: await countBy('authorized'),
      rejected: await countBy('rejected'),
    };

    const rows = docs.map((o) => {
      const getAdd = buildOrderFieldGetter(o);
      const c = (o.customer && typeof o.customer === 'object') ? o.customer : {};
      const nf = o.notaFiscal || {};
      const fd = o.fiscalData || {};
      return {
        id: String(o._id || ''),
        date: o.paidAt || o.createdAt || o.criado || null,
        name: c.name || c.nome || fd.nome || '-',
        phone: String(c.phone_number || c.phone || c.telefone || c.whatsapp || getAdd('telefone') || getAdd('phone') || '').trim(),
        cpf: String(c.cpf || c.federalTaxNumber || fd.cpf || '').replace(/\D/g, ''),
        hasAddress: !!(fd.endereco || (c.address && (c.address.street || c.address.postalCode))),
        valueReais: (Number(o.valueCents || 0) / 100),
        state: String(nf.emissionState || '-'),
        heldReason: nf.heldReason || null,
        error: nf.error || null,
        number: nf.number || null,
        status: nf.status || null,
        updatedAt: nf.updatedAt || null,
      };
    });

    return res.render('painel_notas_fiscais', { page: 'notas-fiscais', rows, state, counts });
  } catch (e) {
    return res.status(500).send(String((e && e.message) || e));
  }
});

