app.post('/api/painel/refil/special/add', requireAdmin, async (req, res) => {
  try {
    const username = String((req.body && req.body.username) || '').trim().replace(/^@+/, '').toLowerCase().replace(/[^a-z0-9._]/g, '');
    if (!username) return res.status(400).json({ ok: false, error: 'missing_username', message: 'Informe o @ do perfil.' });
    let orderId = String((req.body && req.body.orderId) || '').replace(/[^0-9]/g, '');
    const intervalHours = Math.max(1, Math.min(168, parseInt((req.body && req.body.intervalHours), 10) || 48));
    const minDrop = Math.max(1, parseInt((req.body && req.body.minDrop), 10) || 1);
    const col = await getCollection('special_profiles');
    if (await col.findOne({ username })) return res.status(400).json({ ok: false, error: 'already_exists', message: 'Esse perfil já está na lista.' });
    let orderIdAuto = false, orderIdSource = '';
    let tipo = '';
    if (!orderId) {
      // OrderId vem do NOSSO MongoDB (rápido). Removido o refilfama síncrono — era o que travava o
      // cadastro. Se o @ não tiver orderId no banco, o campo fica vazio e você edita inline.
      const fromMongo = await getFamaOrderIdFromMongo(username);
      if (fromMongo && fromMongo.orderId) { orderId = fromMongo.orderId; tipo = fromMongo.tipo || ''; orderIdAuto = true; orderIdSource = 'mongodb'; }
    }
    // Baseline = ALVO FINAL (seguidores iniciais + qtd comprada) do pedido. É o "valor que tem que ter":
    // se já caiu abaixo dele, a reposição dispara. Não depende de busca ao vivo (resolve o timeout).
    let baseline = null;
    try { const tb = await getOrderInitialAndQty(orderId, username); if (tb && tb.target > 0) baseline = tb.target; } catch (_) {}
    // Atual (ao vivo) com timeout curto — só pra já mostrar; se falhar, o 1º audit preenche.
    let currentNow = null;
    try {
      const live = await Promise.race([ fetchCurrentFollowersLive(username), new Promise(r => setTimeout(() => r(null), 9000)) ]);
      if (live && live.ok && typeof live.currentFollowers === 'number') currentNow = Math.trunc(live.currentFollowers);
    } catch (_) {}
    if (baseline == null && currentNow != null) baseline = currentNow; // sem pedido vinculado → usa o atual como alvo
    const now = new Date();
    const ins = await col.insertOne({ username, orderId: orderId || '', tipo: tipo || '', active: true, intervalHours, minDrop, baselineFollowers: baseline, lastFollowers: currentNow, addedAt: now, addedBy: (req.session && req.session.adminUser && req.session.adminUser.username) || '', lastCheckAt: currentNow != null ? now : null, nextCheckAt: new Date(now.getTime() + intervalHours * 3600000), refilCount: 0 });
    return res.json({ ok: true, id: String(ins.insertedId), orderId: orderId || '', orderIdAuto, orderIdSource, baselineFollowers: baseline, currentFollowers: currentNow });
  } catch (e) { return res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/painel/refil/special/update', requireAdmin, async (req, res) => {
  try {
    const { ObjectId } = require('mongodb');
    const id = String((req.body && req.body.id) || '').trim();
    if (!/^[a-fA-F0-9]{24}$/.test(id)) return res.status(400).json({ ok: false, error: 'bad_id' });
    const b = req.body || {}; const set = {};
    const col = await getCollection('special_profiles');
    const doc = await col.findOne({ _id: new ObjectId(id) });
    if (!doc) return res.status(404).json({ ok: false, error: 'not_found' });

    if (typeof b.active !== 'undefined') set.active = !(b.active === false || b.active === 'false');
    if (typeof b.intervalHours !== 'undefined') set.intervalHours = Math.max(1, Math.min(168, parseInt(b.intervalHours, 10) || 48));
    if (typeof b.minDrop !== 'undefined') set.minDrop = Math.max(1, parseInt(b.minDrop, 10) || 1);
    let baselineManual = false;
    if (typeof b.baselineFollowers !== 'undefined') { const v = parseInt(b.baselineFollowers, 10); if (Number.isFinite(v) && v > 0) { set.baselineFollowers = v; baselineManual = true; } }

    if (typeof b.orderId !== 'undefined') {
      const newOrderId = String(b.orderId || '').replace(/[^0-9]/g, '');
      set.orderId = newOrderId;
      // Registrou um pedido NOVO/diferente → esse vira a referência: recalcula o BASELINE
      // (alvo = inicial + qtd do novo pedido) e re-lê o ATUAL ao vivo. Não sobrescreve o
      // baseline se o admin mandou um manual junto na mesma edição.
      const orderChanged = !!newOrderId && newOrderId !== String(doc.orderId || '').replace(/[^0-9]/g, '');
      if (orderChanged && !baselineManual) {
        try { const tb = await getOrderInitialAndQty(newOrderId, doc.username); if (tb && tb.target > 0) set.baselineFollowers = tb.target; } catch (_) {}
        let liveOk = false;
        try {
          const live = await Promise.race([ fetchCurrentFollowersLive(doc.username), new Promise(r => setTimeout(() => r(null), 9000)) ]);
          if (live && live.ok && typeof live.currentFollowers === 'number') { set.lastFollowers = Math.trunc(live.currentFollowers); set.lastCheckAt = new Date(); liveOk = true; }
        } catch (_) {}
        // se conseguiu o atual agora, agenda normal; se não, marca como vencido pra o loop reler já.
        const iv = (set.intervalHours || Number(doc.intervalHours) || 48);
        set.nextCheckAt = liveOk ? new Date(Date.now() + iv * 3600000) : new Date(Date.now() - 1000);
      }
    }

    if (!Object.keys(set).length) return res.status(400).json({ ok: false, error: 'nothing_to_update' });
    await col.updateOne({ _id: new ObjectId(id) }, { $set: set });
    return res.json({ ok: true, orderId: set.orderId, baselineFollowers: set.baselineFollowers, lastFollowers: set.lastFollowers });
  } catch (e) { return res.status(500).json({ ok: false, error: e.message }); }
});
