          const answers = data && Array.isArray(data.Answer) ? data.Answer : [];
          const a = answers.find((x) => x && x.type === 1 && x.data) || null;
          const ip = a && a.data ? String(a.data || '').trim() : '';
          if (!ip) return null;
          return ip;
