app.get('/api/painel/whatsapp-sales', requireAdmin, async (req, res) => {
  try {
    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');
    const limitRaw = Number(req.query?.limit || 50) || 50;
    const limit = Math.min(200, Math.max(1, Math.floor(limitRaw)));
    const purchaseRaw = String(req.query?.purchase || '').trim();

    const wppBaseQuery = { $or: [{ saleChannel: 'whatsapp' }, { isWhatsappSale: true }, { 'additionalInfoMapPaid.saleChannel': 'whatsapp' }, { 'additionalInfoMap.saleChannel': 'whatsapp' }] };
    let query = wppBaseQuery;

    if (purchaseRaw) {
      const safe = purchaseRaw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const rx = new RegExp(safe, 'i');
      const digits = purchaseRaw.replace(/\D/g, '');
      const usernameRaw = purchaseRaw.replace(/^@+/, '').trim();
      const orConds = [
        { identifier: rx },
        { correlationID: rx },
        { instagramUsername: rx },
        { instauser: rx },
        { 'additionalInfoMapPaid.instagram_username': rx },
        { 'additionalInfoMapPaid.phone': rx },
        { 'additionalInfoPaid': { $elemMatch: { key: 'instagram_username', value: rx } } },
        { 'additionalInfoPaid': { $elemMatch: { key: 'phone', value: rx } } }
      ];

      if (digits && digits.length >= 6) {
        const digitsRx = new RegExp(digits.split('').join('\\D*'), 'i');
        orConds.push({ 'customer.phone': { $regex: digitsRx } });
      }

      if (/^[0-9a-fA-F]{24}$/.test(purchaseRaw)) {
        try {
          const { ObjectId } = require('mongodb');
          orConds.push({ _id: new ObjectId(purchaseRaw) });
        } catch (_) {}
      }

      if (usernameRaw) {
        const userSafe = usernameRaw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const userRx = new RegExp(userSafe, 'i');
        orConds.push({ instagramUsername: userRx });
        orConds.push({ instauser: userRx });
        orConds.push({ 'additionalInfoMapPaid.instagram_username': userRx });
      }

      query = { $and: [wppBaseQuery, { $or: orConds }] };
    }

    const docs = await col.find(
      query,
      { projection: { _id: 1, createdAt: 1, paidAt: 1, woovi: 1, status: 1, customer: 1, instagramUsername: 1, instauser: 1, tipo: 1, tipoServico: 1, qtd: 1, quantidade: 1, additionalInfoMapPaid: 1, additionalInfoPaid: 1 } }
    ).sort({ createdAt: -1, _id: -1 }).limit(limit).toArray();
    res.json({ ok: true, sales: docs });
  } catch (e) {
    res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.post('/api/painel/whatsapp-sales', requireAdmin, async (req, res) => {
  try {
    const body = req.body || {};
    const phoneRaw = String(body.phone || '').trim();
    const phoneDigits = phoneRaw.replace(/\D/g, '');
    const phone = phoneDigits ? (`+55${phoneDigits.replace(/^55/, '')}`) : '';
    const usernameRaw = String(body.username || body.instauser || body.instagram_username || '').trim();
    const username = usernameRaw.replace(/^@+/, '').trim();
    const tipoRaw = String(body.tipo || body.tipoServico || body.serviceType || '').trim();
    const tipo = tipoRaw ? tipoRaw : '';
    const qty = Math.max(0, Math.floor(Number(body.quantidade || body.qtd || 0) || 0));
    const parseMoneyToCents = (v) => {
      const raw = String(v == null ? '' : v).trim();
      if (!raw) return 0;
      let s = raw.replace(/[^\d,.\-]/g, '');
      const hasComma = s.includes(',');
      const hasDot = s.includes('.');
      if (hasComma && hasDot) {
        if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
          s = s.replace(/\./g, '').replace(/,/g, '.');
        } else {
          s = s.replace(/,/g, '');
        }
      } else if (hasComma && !hasDot) {
        s = s.replace(/,/g, '.');
      }
      const n = Number(s);
      if (!Number.isFinite(n) || n <= 0) return 0;
      return Math.round(n * 100);
    };
    const valueCents = parseMoneyToCents(body.value || body.valor || 0);

    if (!phone || phone.replace(/\D/g, '').length < 10) return res.status(400).json({ ok: false, error: 'Telefone inválido' });
    if (!username) return res.status(400).json({ ok: false, error: 'Perfil inválido' });
    if (!tipo) return res.status(400).json({ ok: false, error: 'Tipo inválido' });
    if (!qty) return res.status(400).json({ ok: false, error: 'Quantidade inválida' });

    const now = new Date();
    const nowIso = now.toISOString();
    const rand = Math.random().toString(36).slice(2, 8);
    const identifier = `wpp_${Date.now()}_${rand}`;
    const correlationID = `wpp_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

    const additionalInfoMapPaid = {
      phone: phoneDigits.replace(/^55/, ''),
      instagram_username: username,
      categoria_servico: 'seguidores',
      tipo_servico: tipo,
      quantidade: String(qty),
      saleChannel: 'whatsapp'
    };
    if (valueCents) additionalInfoMapPaid.valor = String((valueCents / 100).toFixed(2));

    const additionalInfoPaid = Object.keys(additionalInfoMapPaid).map((k) => ({ key: k, value: String(additionalInfoMapPaid[k]) }));

    const doc = {
      createdAt: now,
      paidAt: nowIso,
      status: 'pago',
      woovi: { status: 'pago', paidAt: nowIso, paymentMethods: { pix: { value: valueCents || 0 } } },
      valueCents: valueCents || 0,
      identifier,
      correlationID,
      customer: { phone },
      instagramUsername: username,
      instauser: username,
      tipo,
      tipoServico: tipo,
      qtd: qty,
      quantidade: qty,
      additionalInfoPaid,
      additionalInfoMapPaid,
      saleChannel: 'whatsapp',
      isWhatsappSale: true
    };

    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');
    const ins = await col.insertOne(doc);
    res.json({ ok: true, id: ins?.insertedId ? String(ins.insertedId) : null });
  } catch (e) {
    res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.get('/api/painel/whatsapp-sales/followers-current', requireAdmin, async (req, res) => {
  try {
    const purchaseRaw = String(req.query?.purchase || '').trim();
    const force = String(req.query?.force || '').trim() === '1';
    if (!purchaseRaw) return res.status(400).json({ ok: false, error: 'missing_purchase' });

    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');

    const wppBaseQuery = { $or: [{ saleChannel: 'whatsapp' }, { isWhatsappSale: true }, { 'additionalInfoMapPaid.saleChannel': 'whatsapp' }, { 'additionalInfoMap.saleChannel': 'whatsapp' }] };

    const safe = purchaseRaw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rx = new RegExp(safe, 'i');
    const digits = purchaseRaw.replace(/\D/g, '');
    const usernameCandidate = purchaseRaw.replace(/^@+/, '').trim();
    const orConds = [
      { identifier: rx },
      { correlationID: rx },
      { instagramUsername: rx },
      { instauser: rx },
      { 'additionalInfoMapPaid.instagram_username': rx },
      { 'additionalInfoMapPaid.phone': rx },
      { 'additionalInfoPaid': { $elemMatch: { key: 'instagram_username', value: rx } } },
      { 'additionalInfoPaid': { $elemMatch: { key: 'phone', value: rx } } }
    ];

    if (digits && digits.length >= 6) {
      const digitsRx = new RegExp(digits.split('').join('\\D*'), 'i');
      orConds.push({ 'customer.phone': { $regex: digitsRx } });
    }

    if (/^[0-9a-fA-F]{24}$/.test(purchaseRaw)) {
      try {
        const { ObjectId } = require('mongodb');
        orConds.push({ _id: new ObjectId(purchaseRaw) });
      } catch (_) {}
    }

    if (usernameCandidate) {
      const userSafe = usernameCandidate.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const userRx = new RegExp(userSafe, 'i');
      orConds.push({ instagramUsername: userRx });
      orConds.push({ instauser: userRx });
      orConds.push({ 'additionalInfoMapPaid.instagram_username': userRx });
    }

    const doc = await col.findOne(
      { $and: [wppBaseQuery, { $or: orConds }] },
      { projection: { _id: 1, createdAt: 1, paidAt: 1, woovi: 1, identifier: 1, correlationID: 1, status: 1, customer: 1, instagramUsername: 1, instauser: 1, tipo: 1, tipoServico: 1, qtd: 1, quantidade: 1, additionalInfoMapPaid: 1, additionalInfoPaid: 1 } }
    );
    if (!doc) return res.status(404).json({ ok: false, error: 'not_found' });

    const pickInfoPaid = (o, key) => {
      try {
        if (o && o.additionalInfoMapPaid && typeof o.additionalInfoMapPaid[key] !== 'undefined') return o.additionalInfoMapPaid[key];
        const arrPaid = Array.isArray(o && o.additionalInfoPaid) ? o.additionalInfoPaid : [];
        const itemPaid = arrPaid.find(i => i && i.key === key);
        if (itemPaid && typeof itemPaid.value !== 'undefined') return itemPaid.value;
      } catch (_) {}
      return '';
    };

    const usernameRaw = String(pickInfoPaid(doc, 'instagram_username') || doc.instagramUsername || doc.instauser || '').trim();
    const username = usernameRaw.toLowerCase().replace(/^@+/, '').trim();
    if (!username) return res.status(400).json({ ok: false, error: 'missing_username' });

    const out = await followersMgmtGetCurrent(req, username, force);
    return res.status(out.code).json({
      purchase: purchaseRaw,
      sale: {
        id: doc._id ? String(doc._id) : null,
        identifier: doc.identifier ? String(doc.identifier) : null,
        correlationID: doc.correlationID ? String(doc.correlationID) : null,
        phone: (doc.customer && doc.customer.phone) ? String(doc.customer.phone) : null,
        paidAt: doc.woovi?.paidAt || doc.paidAt || doc.createdAt || null,
        tipo: String(pickInfoPaid(doc, 'tipo_servico') || doc.tipoServico || doc.tipo || '').trim() || null,
        quantidade: Number(doc.quantidade || doc.qtd || pickInfoPaid(doc, 'quantidade') || 0) || null
      },
      ...out.body
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

const followersMgmtSerial = new Map();
const followersMgmtThrottle = new Map();
const followersMgmtEnqueue = (key, fn) => {
  const prev = followersMgmtSerial.get(key) || Promise.resolve();
  const next = prev.catch(() => undefined).then(fn);
  followersMgmtSerial.set(key, next.finally(() => {
    try {
      if (followersMgmtSerial.get(key) === next) followersMgmtSerial.delete(key);
    } catch (_) {}
  }));
  return next;
};

const fetchInstagramFollowersInfoRocketApi = async (username) => {
  // PRIMÁRIA: self-API (grátis, <5s). Fallback = RocketAPI abaixo.
  try {
    const _self = await fetchProfileSelfApi(username, 5000);
    if (_self && _self.success && _self.profile && Number(_self.profile.followersCount) > 0) {
      return { success: true, profile: { username: _self.profile.username, followersCount: _self.profile.followersCount, profilePicUrl: _self.profile.profilePicUrl || null, isPrivate: _self.profile.isPrivate, checkedAt: new Date().toISOString(), source: 'self_api' } };
    }
  } catch (_) {}
  if (!process.env.ROCKETAPI_TOKEN) return { success: false, error: 'rocketapi_token_missing' };
  if (global.rocketApiDisabledUntil && Date.now() <= global.rocketApiDisabledUntil) return { success: false, error: 'rocketapi_temporarily_disabled' };

  const TOKEN = process.env.ROCKETAPI_TOKEN;
  const rkPost = (url, payload) => axios.post(url, payload, { headers: { Authorization: `Token ${TOKEN}` }, timeout: 15000, validateStatus: () => true });
  const rkBody = (rData) => { let b = rData && rData.response ? rData.response.body : null; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (_) { b = null; } } return b; };
  // get_info/web devolvem em body.data.user; get_info_by_id devolve em body.user.
  const rkUser = (body) => (body && body.data && body.data.user) ? body.data.user : ((body && body.user) ? body.user : null);
  const rkProfile = (u) => {
    const followersCount = (u.edge_followed_by && typeof u.edge_followed_by.count === 'number')
      ? u.edge_followed_by.count
      : ((typeof u.follower_count === 'number') ? u.follower_count : null);
    let profilePicUrl = null; try { profilePicUrl = String(u.profile_pic_url_hd || u.profile_pic_url || '').trim() || null; } catch (_) {}
    return { username: String(u.username || username), followersCount, profilePicUrl, isPrivate: !!u.is_private, checkedAt: new Date().toISOString(), source: 'rocket_api' };
  };

  // 1) get_info (mobile) e get_web_profile_info (web) — rápidos; funcionam p/ contas PESSOAIS
  //    e de CRIADOR/PROFISSIONAL. Contas COMERCIAIS (business) devolvem 400 "Asset
  //    ig_business_category_subvertical has been deleted" (campo que o IG removeu e o RocketAPI
  //    ainda pede) — nesse caso caímos no passo 2 (search → get_info_by_id, que usa outra rota).
  let schemaError = false;
  let lastErr = 'rocket_invalid_data';
  for (const rocketUrl of ['https://v1.rocketapi.io/instagram/user/get_info', 'https://v1.rocketapi.io/instagram/user/get_web_profile_info']) {
    try {
      const r = await rkPost(rocketUrl, { username });
      if (r.status !== 200) { lastErr = `rocket_http_${r.status}`; continue; }
      const rData = r.data;
      const okStatus = rData && (rData.status === 'ok' || rData.status === 'done');
      const u = okStatus ? rkUser(rkBody(rData)) : null;
      if (u && u.username) { global.rocketApiDisabledUntil = 0; return { success: true, profile: rkProfile(u) }; }
      const raw = String(JSON.stringify(rData || {}).slice(0, 500)).toLowerCase();
      if (raw.includes('expired') || raw.includes('renew') || raw.includes('plan is')) { global.rocketApiDisabledUntil = Date.now() + (10 * 60 * 1000); return { success: false, error: 'rocketapi_temporarily_disabled' }; }
      const innerCode = (rData && rData.response && typeof rData.response.status_code === 'number') ? rData.response.status_code : null;
      if (raw.includes('has been deleted') || raw.includes('cannot use this schema') || raw.includes('ig_business_category_subvertical') || innerCode === 400) {
        schemaError = true; lastErr = 'rocket_business_schema';
        break; // o outro endpoint tem o MESMO problema de schema — vai direto pro passo 2
      }
      lastErr = 'rocket_invalid_data';
    } catch (e) {
      const msg = String(e?.response?.data || e?.message || e || '').toLowerCase();
      if (msg.includes('expired')) { global.rocketApiDisabledUntil = Date.now() + (10 * 60 * 1000); return { success: false, error: 'rocketapi_temporarily_disabled' }; }
      lastErr = e?.message || String(e);
    }
  }

  // 2) Contas COMERCIAIS: resolve o id via `search` e busca por `get_info_by_id` (rota que NÃO
  //    pede o campo removido) — recupera os perfis business que o get_info recusa.
  try {
    const s = await rkPost('https://v1.rocketapi.io/instagram/user/search', { query: username });
    if (s.status === 200) {
      const sb = rkBody(s.data);
      const arr = sb && (sb.users || (sb.data && sb.data.users));
      const want = String(username || '').toLowerCase().replace(/^@+/, '');
      let pk = null;
      for (const w of (Array.isArray(arr) ? arr : [])) {
        const usr = (w && w.user) ? w.user : w;
        if (usr && String(usr.username || '').toLowerCase() === want) { pk = usr.pk || usr.pk_id || usr.id; break; }
      }
      if (pk) {
        const idr = await rkPost('https://v1.rocketapi.io/instagram/user/get_info_by_id', { id: String(pk) });
        if (idr.status === 200) {
          const u = rkUser(rkBody(idr.data));
          if (u && (u.username || typeof u.follower_count === 'number' || u.edge_followed_by)) { global.rocketApiDisabledUntil = 0; return { success: true, profile: rkProfile(u) }; }
        }
      }
    }
  } catch (_) {}

  return { success: false, error: schemaError ? 'rocket_business_schema' : lastErr };
};

const fetchInstagramFollowersInfoInstagramProxy = async (username) => {
  const safeJsonResponse = (data) => {
    try {
      if (data == null) return null;
      if (typeof data === 'string') return JSON.parse(data);
      if (typeof data === 'object') return data;
      return null;
    } catch (_) {
      return null;
    }
  };
  const safeInt = (v) => {
    try {
      if (typeof v === 'number' && Number.isFinite(v)) return Math.trunc(v);
      const s0 = String(v == null ? '' : v).trim();
      if (!s0) return null;
      const s = s0.replace(/\s+/g, '');
      const normalizeThousands = (raw) => {
        const x0 = String(raw || '').trim();
        if (!x0) return '';
        const x = x0.replace(/\s+/g, '');
        if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(x)) return x.replace(/\./g, '').replace(',', '.');
        if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(x)) return x.replace(/,/g, '');
        if (/^\d+(\.\d{3})+$/.test(x)) return x.replace(/\./g, '');
        if (/^\d+(,\d{3})+$/.test(x)) return x.replace(/,/g, '');
        return x0;
      };
      const n = Number(normalizeThousands(s));
      if (Number.isFinite(n)) return Math.trunc(n);
      const digits = s0.replace(/[^\d-]/g, '');
      if (!digits) return null;
      const n2 = Number(digits);
      return Number.isFinite(n2) ? Math.trunc(n2) : null;
    } catch (_) {
      return null;
    }
  };

  const timeoutMsRaw = Number(String(process.env.FOLLOWERS_MGMT_INSTAGRAM_PROXY_TIMEOUT_MS || process.env.REFIL2_UPSTREAM_TIMEOUT_MS || '12000').trim());
  const timeoutMs = (Number.isFinite(timeoutMsRaw) && timeoutMsRaw > 0) ? Math.max(5000, Math.min(60000, Math.trunc(timeoutMsRaw))) : 12000;

  const maxAttemptsRaw = Number(String(process.env.FOLLOWERS_MGMT_INSTAGRAM_PROXY_MAX_ATTEMPTS || process.env.REFIL2_UPSTREAM_MAX_ATTEMPTS || '2').trim());
  const maxAttempts = (Number.isFinite(maxAttemptsRaw) && maxAttemptsRaw > 0) ? Math.max(1, Math.min(4, Math.trunc(maxAttemptsRaw))) : 2;

  const waitMs = (ms) => new Promise((r) => setTimeout(r, ms));
  const requestWithRetry = async (fn) => {
    let lastErr = null;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const resp = await fn();
        return resp;
      } catch (err) {
        lastErr = err;
        const code = String(err?.code || '').trim();
        const msg = String(err?.message || String(err) || '').trim();
        const retryable = code === 'ECONNABORTED' || code === 'ETIMEDOUT' || code === 'ECONNRESET' || /timeout/i.test(msg);
        if (!retryable || attempt === maxAttempts) throw err;
        await waitMs(250 * attempt);
      }
    }
    throw lastErr || new Error('upstream_failed');
  };

  // Circuit-breaker: se o refilfama acabou de dar timeout, nem tenta (economiza as 9 combinações).
  if (global.refilfamaProxyDownUntil && Date.now() < global.refilfamaProxyDownUntil) {
    return { success: false, error: 'instagram_proxy_down_recent' };
  }
  try {
    // 1 variante só — as 3 URLs e 3 params batiam no MESMO host morto (9 tentativas por perfil).
    const profileUrlCandidates = [
      `https://www.instagram.com/${username}/`
    ];
    const profileParamCandidates = ['name_url'];

    let lastStatus = null;
    let lastData = null;
    for (const paramName of profileParamCandidates) {
      for (const profileUrl of profileUrlCandidates) {
        const url = `https://www.refilfama24h.com/instagram_proxy.php?${paramName}=${encodeURIComponent(profileUrl)}`;
        let resp;
        try {
          resp = await requestWithRetry(() => axios.get(url, { timeout: timeoutMs, validateStatus: () => true }));
        } catch (ePx) {
          const c = String(ePx && ePx.code ? ePx.code : '').trim();
          if (c === 'ECONNABORTED' || c === 'ETIMEDOUT' || c === 'ECONNREFUSED' || c === 'ENOTFOUND' || c === 'EAI_AGAIN') global.refilfamaProxyDownUntil = Date.now() + 5 * 60 * 1000;
          throw ePx;
        }
        lastStatus = resp && typeof resp.status === 'number' ? resp.status : null;
        const json = safeJsonResponse(resp && resp.data);
        lastData = json;
        const first = Array.isArray(json) ? json[0] : json;

        const followersCount = safeInt(
          (first && (first.followerCount ?? first.follower_count ?? first.followers)) ??
          (first && first.data && (first.data.followerCount ?? first.data.follower_count ?? first.data.followers))
        );
        if (followersCount == null || !(followersCount > 0)) continue;

        const isPrivateRaw =
          (first && (first.isPrivate ?? first.is_private ?? first.private)) ??
          (first && first.data && (first.data.isPrivate ?? first.data.is_private ?? first.data.private));
        const isPrivate = (typeof isPrivateRaw === 'boolean')
          ? isPrivateRaw
          : (String(isPrivateRaw || '').trim().toLowerCase() === 'true' ? true : (String(isPrivateRaw || '').trim().toLowerCase() === 'false' ? false : null));

        return {
          success: true,
          profile: {
            username,
            followersCount,
            isPrivate,
            checkedAt: new Date().toISOString(),
            source: 'instagram_proxy'
          }
        };
      }
    }

    return { success: false, error: `instagram_proxy_failed${lastStatus ? `_http_${lastStatus}` : ''}`, detail: lastData ? 'has_data' : null };
  } catch (e) {
    return { success: false, error: e?.message || String(e) };
  }
};

// Consulta a API de profile dedicada (187.124.91.24) — retorna seguidores E status de privado.
// Usada no audit do gerenciamento de seguidores para detectar contas privadas.
const fetchInstagramProfileApiInfo = async (username) => {
  try {
    const base = String(process.env.PROFILE_API_URL || 'http://187.124.91.24:8080').replace(/\/+$/, '');
    const url = `${base}/api/profile?user=${encodeURIComponent(username)}`;
    const toMsRaw = Number(String(process.env.FOLLOWERS_MGMT_PROFILE_API_TIMEOUT_MS || process.env.REFIL2_UPSTREAM_TIMEOUT_MS || '12000').trim());
    const timeoutMs = (Number.isFinite(toMsRaw) && toMsRaw > 0) ? Math.max(5000, Math.min(60000, Math.trunc(toMsRaw))) : 12000;
    const resp = await axios.get(url, { timeout: timeoutMs, validateStatus: () => true });
    let root = resp ? resp.data : null;
    try { if (typeof root === 'string') { const s = root.trim(); root = (s.startsWith('{') || s.startsWith('[')) ? JSON.parse(s) : null; } } catch (_) { root = null; }
    if (Array.isArray(root)) root = root[0];
    if (!root || typeof root !== 'object') return { success: false, error: `profile_api_failed${resp && resp.status ? `_http_${resp.status}` : ''}` };
    const toInt = (v) => { if (typeof v === 'number' && Number.isFinite(v)) return Math.trunc(v); const d = String(v == null ? '' : v).replace(/[^\d-]/g, ''); if (!d) return null; const n = Number(d); return Number.isFinite(n) ? Math.trunc(n) : null; };
    const pickFollowers = (o, depth) => {
      if (!o || typeof o !== 'object' || depth > 4) return null;
      const direct = [o.followers, o.followerCount, o.follower_count, o.followers_count, o.followed_by, o.followers_total, o.total_followers, (o.edge_followed_by && o.edge_followed_by.count)];
      for (const c of direct) { const n = toInt(c); if (n != null && n > 0) return n; }
      for (const sub of ['data', 'user', 'profile', 'result', 'account', 'graphql']) { if (o[sub] && typeof o[sub] === 'object') { const n = pickFollowers(o[sub], depth + 1); if (n != null) return n; } }
      return null;
    };
    const pickPrivate = (o, depth) => {
      if (!o || typeof o !== 'object' || depth > 4) return null;
      const cands = [o.is_private, o.isPrivate, o.private, o.is_private_account, o.privateAccount, o.is_private_profile];
      for (const c of cands) {
        if (typeof c === 'boolean') return c;
        const s = String(c == null ? '' : c).trim().toLowerCase();
        if (s === 'true' || s === '1' || s === 'yes' || s === 'sim') return true;
        if (s === 'false' || s === '0' || s === 'no' || s === 'nao' || s === 'não') return false;
      }
      for (const sub of ['data', 'user', 'profile', 'result', 'account', 'graphql']) { if (o[sub] && typeof o[sub] === 'object') { const n = pickPrivate(o[sub], depth + 1); if (n != null) return n; } }
      return null;
    };
    const followersCount = pickFollowers(root, 0);
    const isPrivate = pickPrivate(root, 0);
    if ((followersCount == null || !(followersCount > 0)) && typeof isPrivate !== 'boolean') {
      return { success: false, error: `profile_api_no_data${resp && resp.status ? `_http_${resp.status}` : ''}` };
    }
    return { success: true, profile: { username, followersCount: (followersCount != null && followersCount > 0) ? followersCount : null, isPrivate: (typeof isPrivate === 'boolean') ? isPrivate : null, checkedAt: new Date().toISOString(), source: 'profile_api' } };
  } catch (e) {
    return { success: false, error: e?.message || String(e) };
  }
};

// Consulta seguidores/privado via APIFY (actor instagram-profile-scraper) — a MESMA fonte que o
// check do site usa como fallback do RocketAPI. Funciona para contas BUSINESS (que o RocketAPI
// hoje recusa por schema do IG). Só seguidores + privado; sem posts (leve).
const fetchInstagramFollowersInfoApify = async (username) => {
  try {
    const apifyToken = process.env.APIFY_TOKEN;
    if (!apifyToken) return { success: false, error: 'apify_token_missing' };
    const toMsRaw = Number(String(process.env.FOLLOWERS_MGMT_APIFY_TIMEOUT_MS || '90000').trim());
    const timeoutMs = (Number.isFinite(toMsRaw) && toMsRaw > 0) ? Math.max(20000, Math.min(180000, Math.trunc(toMsRaw))) : 90000;
    const apifyUrl = `https://api.apify.com/v2/acts/apify~instagram-profile-scraper/run-sync-get-dataset-items?token=${apifyToken}`;
    const resp = await axios.post(apifyUrl, { usernames: [username], resultsLimit: 1 }, { headers: { 'Content-Type': 'application/json' }, timeout: timeoutMs, validateStatus: () => true });
    const items = resp && resp.data;
    if (!Array.isArray(items) || !items.length || (items[0] && items[0].error)) return { success: false, error: 'apify_no_data' };
    const item = items[0];
    const followersCount = (typeof item.followersCount === 'number' && Number.isFinite(item.followersCount)) ? item.followersCount : null;
    const isPrivateRaw = (typeof item.private !== 'undefined') ? item.private : item.isPrivate;
    const isPrivate = (typeof isPrivateRaw === 'boolean') ? isPrivateRaw : null;
    if (followersCount == null && typeof isPrivate !== 'boolean') return { success: false, error: 'apify_invalid_data' };
    return {
      success: true,
      profile: {
        username: String(item.username || username),
        followersCount,
        profilePicUrl: String(item.profilePicUrlHD || item.profilePicUrl || '').trim() || null,
        isPrivate,
        checkedAt: new Date().toISOString(),
        source: 'apify'
      }
    };
  } catch (e) {
    return { success: false, error: e?.message || String(e) };
  }
};

const followersMgmtGetCurrent = async (req, username, force) => {
  const { getCollection } = require('./mongodbClient');
  const monitorCol = await getCollection('followers_monitor');

  const key = String((req.session && req.session.adminUser && req.session.adminUser.username) ? req.session.adminUser.username : 'admin') + '|' + String(req.realIP || req.ip || '');

  return followersMgmtEnqueue(key, async () => {
    const traceId = Math.random().toString(36).slice(2, 8);
    const startedAtMs = Date.now();
    const cached = await monitorCol.findOne({ username }, { projection: { _id: 0 } });
    if (!force && cached && cached.checkedAt) {
      const cachedUsable = !!(
        (typeof cached.followersCount === 'number' && Number.isFinite(cached.followersCount) && cached.followersCount > 0) ||
        (typeof cached.isPrivate === 'boolean')
      );
      // Se a última verificação terminou em ERRO, nunca serve cache-hit: força uma
      // nova verificação real para tentar resolver o erro (ex.: rocket_invalid_data,
      // instagram_proxy_down). Sem isso, a linha com erro ficava "pulada" pelo cache.
      const hadCachedError = !!(cached && String(cached.error || '').trim());
      const diffDaysBrt = (function(){
        try {
          const brtOffsetMs = 3 * 60 * 60 * 1000;
          const toDayNum = (ms) => {
            const d = new Date(Number(ms || 0) - brtOffsetMs);
            if (!Number.isFinite(d.getTime())) return null;
            return Math.floor(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / (24 * 60 * 60 * 1000));
          };
          const nowNum = toDayNum(Date.now());
          const checkedNum = toDayNum(new Date(String(cached.checkedAt)).getTime());
          if (nowNum == null || checkedNum == null) return null;
          return nowNum - checkedNum;
        } catch (_) {
          return null;
        }
      })();
      if (diffDaysBrt != null && Number.isFinite(diffDaysBrt) && diffDaysBrt >= 0 && diffDaysBrt < 2) {
        if (cachedUsable && !hadCachedError) {
          try { console.log(`🧾 [followers-mgmt:${traceId}] cache-hit @${username} source=${String(cached.source || '')} ms=${Date.now() - startedAtMs}`); } catch (_) {}
          return { code: 200, body: { ok: true, cached: true, username, followersCount: cached.followersCount, isPrivate: cached.isPrivate, checkedAt: cached.checkedAt, source: cached.source || null } };
        }
        try { console.log(`🧾 [followers-mgmt:${traceId}] cache-bypass-${hadCachedError ? 'error' : 'invalid'} @${username} source=${String(cached.source || '')} err=${hadCachedError ? String(cached.error || '').slice(0, 60) : ''} fc=${(typeof cached.followersCount === 'number') ? cached.followersCount : ''} private=${typeof cached.isPrivate === 'boolean' ? (cached.isPrivate ? '1' : '0') : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {}
      }
    }

    if (force && cached && cached.lastAttemptAt) {
      const ageMs = Date.now() - new Date(String(cached.lastAttemptAt)).getTime();
      if (Number.isFinite(ageMs) && ageMs >= 0 && ageMs < (60 * 1000)) {
        return {
          code: 200,
          body: {
            ok: true,
            cached: !!(cached && cached.checkedAt),
            stale: !!(cached && cached.checkedAt && (!cached.followersCount && cached.followersCount !== 0)),
            throttled: true,
            username,
            followersCount: cached.followersCount,
            isPrivate: cached.isPrivate,
            checkedAt: cached.checkedAt || null,
            source: cached.source || null,
            error: cached.error || null
          }
        };
      }
    }

    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const minIntervalMs = 4500;
    const now = Date.now();
    const nextAllowedAt = Number(followersMgmtThrottle.get(key) || 0) || 0;
    const waitMs = Math.max(0, nextAllowedAt - now);
    if (waitMs > 0) await sleep(waitMs);
    await sleep(450 + Math.floor(Math.random() * 900));
    followersMgmtThrottle.set(key, Date.now() + minIntervalMs);

    let result = null;
    let profile = null;
    let source = 'instagram_proxy';
    let isPrivate = null;
    let followersCount = null;
    let error = null;
    let primaryReturnedZeroFollowers = false;

    // ── RocketAPI PRIMEIRO (rápido/confiável). O instagram_proxy (refilfama24h) está
    //    fora do ar; deixá-lo primeiro gastava o timeout inteiro (9 tentativas) por
    //    perfil antes de chegar no RocketAPI. Agora RocketAPI é a fonte primária.
    if (process.env.ROCKETAPI_TOKEN && (!global.rocketApiDisabledUntil || Date.now() > global.rocketApiDisabledUntil)) {
      try {
        try { console.log(`🚀 [followers-mgmt:${traceId}] @${username} method=rocket_api (primary)`); } catch (_) {}
        const rkP = await fetchInstagramFollowersInfoRocketApi(username);
        if (rkP && rkP.success && rkP.profile) {
          profile = rkP.profile;
          source = String(profile.source || 'rocket_api');
          isPrivate = (typeof profile.isPrivate === 'boolean') ? profile.isPrivate : null;
          followersCount = (typeof profile.followersCount === 'number' && profile.followersCount > 0) ? profile.followersCount : null;
          if (followersCount != null || typeof isPrivate === 'boolean') { error = null; }
          else { profile = null; } // sem dado útil → deixa o proxy tentar
        }
      } catch (_) {}
    }

    // Fallback: instagram_proxy — só roda se o RocketAPI não trouxe dado fresco.
    for (let attempt = 1; attempt <= 1 && !profile; attempt++) {
      try {
        try { console.log(`👣 [followers-mgmt:${traceId}] @${username} attempt=${attempt} method=instagram_proxy`); } catch (_) {}
        result = await fetchInstagramFollowersInfoInstagramProxy(username);
        profile = result && result.success ? result.profile : null;
        source = profile ? String(profile.source || 'instagram_proxy') : 'instagram_proxy';
        isPrivate = profile ? ((typeof profile.isPrivate === 'boolean') ? profile.isPrivate : null) : null;
        followersCount = profile && typeof profile.followersCount === 'number' ? profile.followersCount : null;
        error = result && !result.success ? (result.error || 'unknown_error') : null;
        if (typeof followersCount === 'number' && !(followersCount > 0)) {
          primaryReturnedZeroFollowers = true;
          followersCount = null;
          if (!error) error = 'invalid_followers_count';
        }
        if (profile) {
          try { console.log(`✅ [followers-mgmt:${traceId}] @${username} ok source=${source} private=${isPrivate === true ? '1' : (isPrivate === false ? '0' : '')} fc=${typeof followersCount === 'number' ? followersCount : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {}
          break;
        }
      } catch (e) {
        error = e?.message || String(e);
        try { console.warn(`⚠️ [followers-mgmt:${traceId}] @${username} fail method=instagram_proxy attempt=${attempt}:`, error); } catch (_) {}
      }
      if (attempt < 1) await sleep(900 * attempt);
    }

    const nowIso = new Date().toISOString();
    let hasFresh = !!(profile && ((typeof followersCount === 'number' && followersCount > 0) || typeof isPrivate === 'boolean'));

    if (!hasFresh || primaryReturnedZeroFollowers) {
      try {
        try { console.log(`🚀 [followers-mgmt:${traceId}] @${username} fallback=rocket_api start`); } catch (_) {}
        const r = await fetchInstagramFollowersInfoRocketApi(username);
        if (r && r.success && r.profile) {
          profile = r.profile;
          source = String(profile.source || 'rocket_api');
          isPrivate = (typeof profile.isPrivate === 'boolean') ? profile.isPrivate : null;
          followersCount = (typeof profile.followersCount === 'number') ? profile.followersCount : null;
          error = null;
          if (typeof followersCount === 'number' && !(followersCount > 0)) {
            followersCount = null;
            error = 'invalid_followers_count';
          }
          hasFresh = !!(typeof followersCount === 'number' || typeof isPrivate === 'boolean');
          if (hasFresh) {
            try { console.log(`✅ [followers-mgmt:${traceId}] @${username} ok source=${source} private=${isPrivate === true ? '1' : (isPrivate === false ? '0' : '')} fc=${typeof followersCount === 'number' ? followersCount : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {}
          }
        } else {
          const rErr = String((r && r.error) || 'unknown');
          const tag = `rocket_api:${rErr}`;
          if (!error) error = tag;
          else {
            const eStr = String(error || '');
            if (!eStr.includes(tag)) error = eStr ? (eStr + ' | ' + tag) : tag;
          }
          try { console.warn(`❌ [followers-mgmt:${traceId}] @${username} rocket_api fail error=${rErr}`); } catch (_) {}
        }
      } catch (e) {
        const tag = `rocket_api:${String(e?.message || e)}`;
        if (!error) error = tag;
        else {
          const eStr = String(error || '');
          if (!eStr.includes(tag)) error = eStr ? (eStr + ' | ' + tag) : tag;
        }
        try { console.warn(`❌ [followers-mgmt:${traceId}] @${username} rocket_api error:`, e?.message || String(e)); } catch (_) {}
      }
    }

    // Fallback FINAL: Apify (a MESMA fonte que o check do site usa quando o RocketAPI falha).
    // Cobre as contas BUSINESS que o RocketAPI recusa (erro de schema do IG) e o caso do
    // instagram_proxy estar fora do ar. Sem isto, o painel ficava sem nenhuma fonte.
    if (!hasFresh) {
      try {
        try { console.log(`🚀 [followers-mgmt:${traceId}] @${username} fallback=apify start`); } catch (_) {}
        const a = await fetchInstagramFollowersInfoApify(username);
        if (a && a.success && a.profile) {
          profile = a.profile;
          source = String(profile.source || 'apify');
          const apiPriv = (typeof profile.isPrivate === 'boolean') ? profile.isPrivate : null;
          const apiFc = (typeof profile.followersCount === 'number' && profile.followersCount > 0) ? profile.followersCount : null;
          if (apiPriv != null) isPrivate = apiPriv;
          if (apiFc != null) followersCount = apiFc;
          if (apiFc != null || apiPriv != null) error = null;
          hasFresh = !!((typeof followersCount === 'number' && followersCount > 0) || typeof isPrivate === 'boolean');
          if (hasFresh) { try { console.log(`✅ [followers-mgmt:${traceId}] @${username} ok source=apify private=${isPrivate === true ? '1' : (isPrivate === false ? '0' : '')} fc=${typeof followersCount === 'number' ? followersCount : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {} }
        } else {
          const aErr = String((a && a.error) || 'unknown');
          const tag = `apify:${aErr}`;
          if (!error) error = tag; else { const eStr = String(error || ''); if (!eStr.includes(tag)) error = eStr ? (eStr + ' | ' + tag) : tag; }
          try { console.warn(`❌ [followers-mgmt:${traceId}] @${username} apify fail error=${aErr}`); } catch (_) {}
        }
      } catch (e) {
        const tag = `apify:${String(e?.message || e)}`;
        if (!error) error = tag; else { const eStr = String(error || ''); if (!eStr.includes(tag)) error = eStr ? (eStr + ' | ' + tag) : tag; }
        try { console.warn(`❌ [followers-mgmt:${traceId}] @${username} apify error:`, e?.message || String(e)); } catch (_) {}
      }
    }

    if (!hasFresh) {
      const prevFollowers = (cached && typeof cached.followersCount === 'number') ? cached.followersCount : null;
      const prevPrivate = (cached && typeof cached.isPrivate === 'boolean') ? cached.isPrivate : null;
      const prevCheckedAt = (cached && cached.checkedAt) ? cached.checkedAt : null;

      if (followersCount == null && prevFollowers != null) followersCount = prevFollowers;
      if (isPrivate == null && prevPrivate != null) isPrivate = prevPrivate;

      await monitorCol.updateOne(
        { username },
        { $set: { username, followersCount, isPrivate, source, error, lastAttemptAt: nowIso } },
        { upsert: true }
      );

      try { console.log(`🧊 [followers-mgmt:${traceId}] @${username} stale cached=${prevCheckedAt ? '1' : '0'} source=${source} private=${isPrivate === true ? '1' : (isPrivate === false ? '0' : '')} fc=${typeof followersCount === 'number' ? followersCount : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {}
      return { code: 200, body: { ok: true, cached: !!prevCheckedAt, stale: true, username, followersCount, isPrivate, checkedAt: prevCheckedAt, source, error } };
    }

    // Detecção de privado no audit: quando a fonte primária trouxe os seguidores mas
    // NÃO o status de privado, consulta a profile API (187.124.91.24, self-hosted) e a
    // Rocket como reforço, só para resolver is_private. Evita conta privada passar sem flag.
    if (isPrivate == null) {
      try {
        const pa = await fetchInstagramProfileApiInfo(username);
        if (pa && pa.success && pa.profile && typeof pa.profile.isPrivate === 'boolean') {
          isPrivate = pa.profile.isPrivate;
          try { console.log(`🔒 [followers-mgmt:${traceId}] @${username} private-fill source=profile_api private=${isPrivate ? '1' : '0'}`); } catch (_) {}
        }
      } catch (_) {}
      if (isPrivate == null) {
        try {
          const rp = await fetchInstagramFollowersInfoRocketApi(username);
          if (rp && rp.success && rp.profile && typeof rp.profile.isPrivate === 'boolean') {
            isPrivate = rp.profile.isPrivate;
            try { console.log(`🔒 [followers-mgmt:${traceId}] @${username} private-fill source=rocket_api private=${isPrivate ? '1' : '0'}`); } catch (_) {}
          }
        } catch (_) {}
      }
    }

    const prevFollowersFinal = (cached && typeof cached.followersCount === 'number') ? cached.followersCount : null;
    if (followersCount == null && prevFollowersFinal != null && prevFollowersFinal > 0) followersCount = prevFollowersFinal;

    await monitorCol.updateOne(
      { username },
      { $set: { username, followersCount, isPrivate, checkedAt: nowIso, source, error, lastAttemptAt: nowIso } },
      { upsert: true }
    );

    try { console.log(`📌 [followers-mgmt:${traceId}] @${username} saved source=${source} private=${isPrivate === true ? '1' : (isPrivate === false ? '0' : '')} fc=${typeof followersCount === 'number' ? followersCount : ''} ms=${Date.now() - startedAtMs}`); } catch (_) {}
    return { code: 200, body: { ok: true, cached: false, username, followersCount, isPrivate, checkedAt: nowIso, source, error } };
  });
};

app.post('/api/painel/gerenciamento-seguidores/settings', requireAdmin, async (req, res) => {
  try {
    const dailyLimitRaw = parseInt(String((req.body && req.body.dailyLimit) || '50'), 10);
    const dailyLimit = Math.min(1000, Math.max(1, Number.isFinite(dailyLimitRaw) ? dailyLimitRaw : 50));
    const orderRaw = String((req.body && req.body.order) || 'newest').trim().toLowerCase();
    const order = (orderRaw === 'oldest') ? 'oldest' : 'newest';

    const { getCollection } = require('./mongodbClient');
    const settingsCol = await getCollection('settings');
    await settingsCol.updateOne(
      { _id: 'followers_mgmt_settings' },
      { $set: { values: { dailyLimit, order }, updatedAt: new Date().toISOString() } },
      { upsert: true }
    );
    return res.json({ ok: true, dailyLimit, order });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.get('/api/painel/gerenciamento-seguidores/current', requireAdmin, async (req, res) => {
  try {
    const username = String(req.query.username || '').trim().toLowerCase().replace(/^@/, '');
    const force = String(req.query.force || '').trim() === '1';
    if (!username) return res.status(400).json({ ok: false, error: 'missing_username' });

    const out = await followersMgmtGetCurrent(req, username, force);
    return res.status(out.code).json(out.body);
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

async function followersMgmtComputeAutoNotifyCandidates({ limit, order }) {
  const limitRaw = parseInt(String(limit || '0'), 10);
  const lim = Math.max(0, Math.min(5000, Number.isFinite(limitRaw) ? limitRaw : 0));
  const orderRaw = String(order || 'recent').trim().toLowerCase();
  const ord = (orderRaw === 'oldest') ? 'oldest' : 'recent';
  const safe = (v) => String(v == null ? '' : v).trim();
  const brtOffsetMs = 3 * 60 * 60 * 1000;
  const dayKeyBrt = (ms) => {
    const d = new Date(Number(ms || 0) - brtOffsetMs);
    const y = String(d.getUTCFullYear());
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${dd}`;
  };
  const dayRangeBrtUtcMs = (dayKey) => {
    try {
      const s = String(dayKey || '').trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return { startMs: 0, endMs: 0 };
      const parts = s.split('-').map(Number);
      const y = parts[0];
      const m = parts[1];
      const d = parts[2];
      const startUtcMs = Date.UTC(y, m - 1, d, 0, 0, 0, 0) + brtOffsetMs;
      const endUtcMs = startUtcMs + (24 * 60 * 60 * 1000);
      return { startMs: startUtcMs, endMs: endUtcMs };
    } catch (_) {
      return { startMs: 0, endMs: 0 };
    }
  };

  const { getCollection } = require('./mongodbClient');
  const col = await getCollection('checkout_orders');
  const monitorCol = await getCollection('followers_monitor');
  const validatedCol = await getCollection('validated_insta_users');

  const stats = {
    monitorDocs: 0,
    monitorUsable: 0,
    monitorSkippedNoFollowers: 0,
    monitorSkippedNoCheckedAt: 0,
    validatedDocs: 0,
    validatedUsable: 0,
    validatedSkippedNoFollowers: 0,
    validatedSkippedNoCheckedAt: 0,
    ordersScanned: 0,
    ordersSkippedNoUsername: 0,
    ordersSkippedNoMonitor: 0,
    ordersSkippedPrivate: 0,
    ordersSkippedOrganicos: 0,
    ordersLatestByUser: 0,
    candidatesScanned: 0,
    candidatesSkippedMissingQtyOrInitial: 0,
    candidatesSkippedNoCurrent: 0,
    candidatesSkippedDropBelow100: 0,
    candidatesSkippedAlreadyNotified: 0,
    candidatesStage0FirstEmail: 0,
    candidatesStage1SecondEmail: 0,
    candidatesStage1SkippedNoNewCheck: 0,
    eligible: 0
  };

  const todayBrtKey = dayKeyBrt(Date.now());
  const { startMs: todayStartMs, endMs: todayEndMs } = dayRangeBrtUtcMs(todayBrtKey);
  const toIso = (ms) => (Number.isFinite(ms) && ms > 0) ? new Date(ms).toISOString() : '';
  const todayStartIso = toIso(todayStartMs);
  const todayEndIso = toIso(todayEndMs);
  const dailyMaxRaw = parseInt(String(process.env.RECOVERY_EMAIL_DAILY_LIMIT || process.env.EMAIL_DAILY_LIMIT || '1000'), 10);
  const dailyMax = Math.max(1, Number.isFinite(dailyMaxRaw) ? dailyMaxRaw : 1000);
  const reservePctRaw = Number(String(process.env.RECOVERY_EMAIL_RESERVE_PCT || '0.2'));
  const reservePct = (Number.isFinite(reservePctRaw) && reservePctRaw >= 0 && reservePctRaw <= 0.9) ? reservePctRaw : 0.2;
  let paidEmailCountToday = 0;
  let createdEmailCountToday = 0;
  let recoveryEmailSentEventsToday = 0;
  let recoveryEmailSentOrdersToday = 0;
  try {
    if (todayStartIso && todayEndIso) {
      paidEmailCountToday = await col.countDocuments({
        $or: [
          { 'woovi.paidAt': { $gte: todayStartIso, $lt: todayEndIso } },
          { paidAt: { $gte: todayStartIso, $lt: todayEndIso } }
        ]
      });
      createdEmailCountToday = await col.countDocuments({
        createdAt: { $gte: todayStartIso, $lt: todayEndIso }
      });
      const agg = await col.aggregate([
        { $match: { 'recoveryNotify.email.history': { $exists: true, $ne: [] } } },
        { $unwind: '$recoveryNotify.email.history' },
        { $match: { 'recoveryNotify.email.history.status': 'sent', 'recoveryNotify.email.history.at': { $gte: todayStartIso, $lt: todayEndIso } } },
        { $count: 'c' }
      ]).toArray();
      recoveryEmailSentEventsToday = agg && agg[0] && typeof agg[0].c === 'number' ? agg[0].c : 0;
      const agg2 = await col.aggregate([
        { $match: { 'recoveryNotify.email.history': { $exists: true, $ne: [] } } },
        { $unwind: '$recoveryNotify.email.history' },
        { $match: { 'recoveryNotify.email.history.status': 'sent', 'recoveryNotify.email.history.at': { $gte: todayStartIso, $lt: todayEndIso } } },
        { $group: { _id: '$_id' } },
        { $count: 'c' }
      ]).toArray();
      recoveryEmailSentOrdersToday = agg2 && agg2[0] && typeof agg2[0].c === 'number' ? agg2[0].c : 0;
    }
  } catch (_) {}
  const pedidosEmailCountToday = Math.max(0, Number(paidEmailCountToday || 0) + Number(createdEmailCountToday || 0));
  const availableAfterPedidos = Math.max(0, dailyMax - pedidosEmailCountToday);
  const allowedForRecoveryToday = Math.max(0, Math.floor(availableAfterPedidos * (1 - reservePct)));
  const remainingRecoveryToday = Math.max(0, allowedForRecoveryToday - Number(recoveryEmailSentEventsToday || 0));

  const parseDateMsLoose = (raw) => {
    try {
      const s0 = String(raw || '').trim();
      if (!s0) return 0;
      const s = s0.replace(',', ' ').replace(/\s+/g, ' ').trim();
      const mBr = s.match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?/);
      if (mBr) {
        const yyyy = String(mBr[3]);
        const mm = String(mBr[2]).padStart(2, '0');
        const dd = String(mBr[1]).padStart(2, '0');
        const hh = String(mBr[4] || '00').padStart(2, '0');
        const mi = String(mBr[5] || '00').padStart(2, '0');
        const ss = String(mBr[6] || '00').padStart(2, '0');
        const iso = `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}-03:00`;
        const t = new Date(iso).getTime();
        return Number.isFinite(t) ? t : 0;
      }
      const t = new Date(s).getTime();
      return Number.isFinite(t) ? t : 0;
    } catch (_) {
      return 0;
    }
  };

  const monDocs = await monitorCol.find(
    { checkedAt: { $exists: true, $ne: '' }, hidden: { $ne: true } },
    { projection: { _id: 0, username: 1, followersCount: 1, checkedAt: 1, hidden: 1 } }
  ).limit(50000).toArray();

  const vuDocs = await validatedCol.find(
    { checkedAt: { $exists: true, $ne: '' } },
    { projection: { _id: 0, username: 1, followersCount: 1, checkedAt: 1 } }
  ).limit(50000).toArray();

  const monByUser = new Map();
  stats.monitorDocs = Array.isArray(monDocs) ? monDocs.length : 0;
  for (const m of (monDocs || [])) {
    const u = safe(m && m.username).toLowerCase().replace(/^@/, '');
    if (!u) continue;
    const checkedAtMs = parseDateMsLoose(m && m.checkedAt);
    const followersCount = (typeof m?.followersCount === 'number') ? m.followersCount : null;
    if (!checkedAtMs) { stats.monitorSkippedNoCheckedAt += 1; continue; }
    if (followersCount == null) { stats.monitorSkippedNoFollowers += 1; continue; }
    stats.monitorUsable += 1;
    const prev = monByUser.get(u);
    if (!prev || Number(checkedAtMs || 0) >= Number(prev.checkedAtMs || 0)) {
      monByUser.set(u, { checkedAtMs, followersCount });
    }
  }
  stats.validatedDocs = Array.isArray(vuDocs) ? vuDocs.length : 0;
  for (const v of (vuDocs || [])) {
    const u = safe(v && v.username).toLowerCase().replace(/^@/, '');
    if (!u) continue;
    const checkedAtMs = parseDateMsLoose(v && v.checkedAt);
    const followersCount = (typeof v?.followersCount === 'number') ? v.followersCount : null;
    if (!checkedAtMs) { stats.validatedSkippedNoCheckedAt += 1; continue; }
    if (followersCount == null) { stats.validatedSkippedNoFollowers += 1; continue; }
    stats.validatedUsable += 1;
    const prev = monByUser.get(u);
    if (!prev || Number(checkedAtMs || 0) >= Number(prev.checkedAtMs || 0)) {
      monByUser.set(u, { checkedAtMs, followersCount });
    }
  }
  if (!monByUser.size) return { ok: true, total: 0, candidates: [], emailBudget: null, stats };

  const vuByUser = new Map();
  for (const v of (vuDocs || [])) {
    const u = safe(v && v.username).toLowerCase().replace(/^@/, '');
    if (!u) continue;
    const followersCount = (typeof v?.followersCount === 'number') ? v.followersCount : null;
    if (followersCount == null) continue;
    vuByUser.set(u, { followersCount, checkedAtMs: parseDateMsLoose(v && v.checkedAt) });
  }

  const followersQuery = {
    $and: [
      {
        $or: [
          { status: 'paid' },
          { paymentStatus: 'paid' },
          { paymentStatus: 'approved' },
          { paymentStatus: 'succeeded' },
          { paymentStatus: 'received' },
          { 'woovi.status': { $in: ['PAID', 'COMPLETED'] } },
          { paidAt: { $exists: true, $ne: null } },
          { 'woovi.paidAt': { $exists: true, $ne: null } }
        ]
      },
      {
        $or: [
          { categoria_servico: { $regex: '^seguidores$', $options: 'i' } },
          { 'additionalInfoMapPaid.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
          { 'additionalInfoMap.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
          { tipo: { $regex: 'seguidores', $options: 'i' } },
          { tipoServico: { $regex: 'seguidores', $options: 'i' } }
        ]
      }
    ]
  };
  const ordersCursor = col.find(followersQuery, {
    projection: {
      _id: 1, createdAt: 1, paidAt: 1, woovi: 1, tipo: 1, tipoServico: 1, qtd: 1, quantidade: 1,
      instagramUsername: 1, instauser: 1, initialFollowersCount: 1, isPrivate: 1, profilePrivacy: 1,
      additionalInfo: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfoMapPaid: 1,
      recoveryNotify: 1
    }
  }).sort({ createdAt: -1 }).limit(50000);

  const getMapObj = (o, k) => {
    try {
      if (o?.additionalInfoMapPaid && typeof o.additionalInfoMapPaid[k] !== 'undefined') return o.additionalInfoMapPaid[k];
      if (o?.additionalInfoMap && typeof o.additionalInfoMap[k] !== 'undefined') return o.additionalInfoMap[k];
    } catch (_) {}
    return undefined;
  };
  const getArrVal = (arr, key) => {
    try {
      const a = Array.isArray(arr) ? arr : [];
      const it = a.find(x => x && safe(x.key).toLowerCase() === String(key || '').toLowerCase());
      return it && typeof it.value !== 'undefined' ? it.value : undefined;
    } catch (_) { return undefined; }
  };
  const pick = (o, key) => {
    const a = getMapObj(o, key);
    if (typeof a !== 'undefined') return a;
    const b = getArrVal(o?.additionalInfoPaid, key);
    if (typeof b !== 'undefined') return b;
    const c = getArrVal(o?.additionalInfo, key);
    if (typeof c !== 'undefined') return c;
    return undefined;
  };
  const resolveUsername = (o) => {
    const u = safe(o?.instagramUsername || o?.instauser || pick(o, 'instagram_username') || pick(o, 'instauser')).toLowerCase();
    return u.replace(/^@/, '').replace(/\/+$/, '').split('/').pop().trim();
  };
  const resolveDateMs = (o) => {
    const t = new Date(o?.woovi?.paidAt || o?.paidAt || o?.createdAt || 0).getTime();
    return Number.isFinite(t) ? t : 0;
  };
  const isPrivateOrder = (o) => {
    const a = o?.isPrivate;
    const b = o?.profilePrivacy;
    const c = pick(o, 'isPrivate');
    return a === true || b === true || String(c || '').toLowerCase() === 'true';
  };

  const latestByUser = new Map();
  for await (const o of ordersCursor) {
    stats.ordersScanned += 1;
    const u = resolveUsername(o);
    if (!u) { stats.ordersSkippedNoUsername += 1; continue; }
    if (!monByUser.has(u)) { stats.ordersSkippedNoMonitor += 1; continue; }
    const tipoRaw = safe(o?.tipoServico || o?.tipo || pick(o, 'tipo_servico')).toLowerCase();
    if (tipoRaw && /seguidores_organicos|organicos/.test(tipoRaw)) { stats.ordersSkippedOrganicos += 1; continue; }
    if (isPrivateOrder(o)) stats.ordersSkippedPrivate += 1;
    const ms = resolveDateMs(o);
    const prev = latestByUser.get(u);
    if (!prev || ms > prev.ms) latestByUser.set(u, { ms, order: o });
  }
  stats.ordersLatestByUser = latestByUser.size;

  const out = [];
  for (const [u, rec] of latestByUser.entries()) {
    stats.candidatesScanned += 1;
    const o = rec.order;
    const mon = monByUser.get(u);
    if (!o || !mon) continue;
    const qty = Number(o?.qtd || o?.quantidade || pick(o, 'quantidade') || pick(o, 'qtd') || pick(o, 'quantity') || 0) || 0;
    const initialRaw = (typeof o?.initialFollowersCount === 'number')
      ? o.initialFollowersCount
      : Number(pick(o, 'start_count') || pick(o, 'initial_followers') || pick(o, 'inicial') || 0) || 0;
    const initial = (initialRaw > 0)
      ? initialRaw
      : (() => {
        const vu = vuByUser.get(u);
        if (vu && typeof vu.followersCount === 'number' && vu.followersCount > 0) return vu.followersCount;
        if (typeof mon.followersCount === 'number' && mon.followersCount > 0) return mon.followersCount;
        return 0;
      })();
    if (!(qty > 0 && initial > 0)) { stats.candidatesSkippedMissingQtyOrInitial += 1; continue; }
    const expected = initial + qty;
    const current = mon.followersCount;
    if (current == null) { stats.candidatesSkippedNoCurrent += 1; continue; }
    const dropAbs = Math.max(0, expected - current);
    if (!(current < expected)) { stats.candidatesSkippedDropBelow100 += 1; continue; }
    if (dropAbs < 100) { stats.candidatesSkippedDropBelow100 += 1; continue; }

    const notify = (o && o.recoveryNotify && typeof o.recoveryNotify === 'object') ? o.recoveryNotify : {};
    const nEmail = (notify && notify.email && typeof notify.email === 'object') ? notify.email : {};
    const nSms = (notify && notify.sms && typeof notify.sms === 'object') ? notify.sms : {};
    const emailOk = String(nEmail.lastStatus || '').trim().toLowerCase() === 'sent';
    const smsOk = !!safe(nSms.sentAt);
    const emailHist = (Array.isArray(nEmail.history) ? nEmail.history : []);
    const hasEmailHistory = emailHist.length > 0;
    let emailSentCountFromHist = 0;
    let lastEmailSentAtMs = 0;
    for (const h of emailHist) {
      try {
        if (!h || typeof h !== 'object') continue;
        const st = String(h.status || '').trim().toLowerCase();
        if (st !== 'sent') continue;
        emailSentCountFromHist += 1;
        const atMs = parseDateMsLoose(h.at || h.sentAt || h.lastSentAt || h.lastAttemptAt || '');
        if (atMs && atMs > lastEmailSentAtMs) lastEmailSentAtMs = atMs;
      } catch (_) {}
    }
    const fallbackEmailAtMs = parseDateMsLoose(nEmail.lastSentAt || nEmail.lastAttemptAt || nEmail.sentAt || '');
    if (!lastEmailSentAtMs && fallbackEmailAtMs) lastEmailSentAtMs = fallbackEmailAtMs;

    const emailSentCount = Math.max(emailSentCountFromHist, emailOk ? 1 : 0);
    const checkedAtMs = Number(mon.checkedAtMs || 0) || 0;
    const hasNewCheckSinceEmail = (!!lastEmailSentAtMs && checkedAtMs > lastEmailSentAtMs);

    let stage = 0;
    if (emailSentCount <= 0) stage = 0;
    else if (emailSentCount === 1) {
      if (!hasNewCheckSinceEmail) { stats.candidatesStage1SkippedNoNewCheck += 1; continue; }
      stage = 1;
    } else {
      stats.candidatesSkippedAlreadyNotified += 1;
      continue;
    }
    if (stage === 0) stats.candidatesStage0FirstEmail += 1;
    if (stage === 1) stats.candidatesStage1SecondEmail += 1;

    out.push({ orderId: String(o._id), username: u, checkedAtMs, dropAbs, stage, emailSentCount, lastEmailSentAtMs, hasEmailHistory, smsOk });
  }
  stats.eligible = out.length;

  out.sort((a, b) => {
    const sa = Number(a.stage || 0);
    const sb = Number(b.stage || 0);
    if (sa !== sb) return sa - sb;
    const ha = a.hasEmailHistory ? 1 : 0;
    const hb = b.hasEmailHistory ? 1 : 0;
    if (ha !== hb) return ha - hb;
    const ca = Number(a.checkedAtMs || 0);
    const cb = Number(b.checkedAtMs || 0);
    if (ca !== cb) return ord === 'oldest' ? (ca - cb) : (cb - ca);
    const da = Number(a.dropAbs || 0);
    const db = Number(b.dropAbs || 0);
    if (da !== db) return db - da;
    return 0;
  });
  const dailyCap = remainingRecoveryToday > 0 ? remainingRecoveryToday : 0;
  const capLimit = dailyCap > 0 ? dailyCap : 0;
  const maxCandidates = (lim > 0 && capLimit > 0) ? Math.min(lim, capLimit) : (lim > 0 ? lim : (capLimit > 0 ? capLimit : 0));
  const sliced = maxCandidates > 0 ? out.slice(0, maxCandidates) : out;

  return {
    ok: true,
    total: out.length,
    candidates: sliced,
    emailBudget: {
      todayBrtKey,
      dailyMax,
      reservePct,
      paidEmailCountToday,
      createdEmailCountToday,
      pedidosEmailCountToday,
      availableAfterPedidos,
      allowedForRecoveryToday,
      recoveryEmailSentEventsToday,
      recoveryEmailSentOrdersToday,
      remainingRecoveryToday
    },
    stats
  };
}

app.get('/api/painel/gerenciamento-seguidores/auto-notify-candidates', requireAdmin, async (req, res) => {
  try {
    const limitRaw = parseInt(String(req.query.limit || '0'), 10);
    const limit = Math.max(0, Math.min(5000, Number.isFinite(limitRaw) ? limitRaw : 0));
    const orderRaw = String(req.query.order || 'recent').trim().toLowerCase();
    const order = (orderRaw === 'oldest') ? 'oldest' : 'recent';
    const data = await followersMgmtComputeAutoNotifyCandidates({ limit, order });
    return res.json(data);
    const safe = (v) => String(v == null ? '' : v).trim();
    const brtOffsetMs = 3 * 60 * 60 * 1000;
    const dayKeyBrt = (ms) => {
      const d = new Date(Number(ms || 0) - brtOffsetMs);
      const y = String(d.getUTCFullYear());
      const m = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd = String(d.getUTCDate()).padStart(2, '0');
      return `${y}-${m}-${dd}`;
    };
    const dayRangeBrtUtcMs = (dayKey) => {
      try {
        const s = String(dayKey || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return { startMs: 0, endMs: 0 };
        const parts = s.split('-').map(Number);
        const y = parts[0];
        const m = parts[1];
        const d = parts[2];
        const startUtcMs = Date.UTC(y, m - 1, d, 0, 0, 0, 0) + brtOffsetMs;
        const endUtcMs = startUtcMs + (24 * 60 * 60 * 1000);
        return { startMs: startUtcMs, endMs: endUtcMs };
      } catch (_) {
        return { startMs: 0, endMs: 0 };
      }
    };

    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');
    const monitorCol = await getCollection('followers_monitor');

    const stats = {
      monitorDocs: 0,
      monitorUsable: 0,
      monitorSkippedNoFollowers: 0,
      monitorSkippedNoCheckedAt: 0,
      ordersScanned: 0,
      ordersSkippedNoUsername: 0,
      ordersSkippedNoMonitor: 0,
      ordersSkippedPrivate: 0,
      ordersSkippedOrganicos: 0,
      ordersLatestByUser: 0,
      candidatesScanned: 0,
      candidatesSkippedMissingQtyOrInitial: 0,
      candidatesSkippedNoCurrent: 0,
      candidatesSkippedDropBelow100: 0,
      candidatesSkippedAlreadyNotified: 0,
      eligible: 0
    };

    const todayBrtKey = dayKeyBrt(Date.now());
    const { startMs: todayStartMs, endMs: todayEndMs } = dayRangeBrtUtcMs(todayBrtKey);
    const toIso = (ms) => (Number.isFinite(ms) && ms > 0) ? new Date(ms).toISOString() : '';
    const todayStartIso = toIso(todayStartMs);
    const todayEndIso = toIso(todayEndMs);
    const dailyMaxRaw = parseInt(String(process.env.RECOVERY_EMAIL_DAILY_LIMIT || process.env.EMAIL_DAILY_LIMIT || '1000'), 10);
    const dailyMax = Math.max(1, Number.isFinite(dailyMaxRaw) ? dailyMaxRaw : 1000);
    const reservePctRaw = Number(String(process.env.RECOVERY_EMAIL_RESERVE_PCT || '0.2'));
    const reservePct = (Number.isFinite(reservePctRaw) && reservePctRaw >= 0 && reservePctRaw <= 0.9) ? reservePctRaw : 0.2;
    let paidEmailCountToday = 0;
    let createdEmailCountToday = 0;
    let recoveryEmailSentEventsToday = 0;
    let recoveryEmailSentOrdersToday = 0;
    try {
      if (todayStartIso && todayEndIso) {
        paidEmailCountToday = await col.countDocuments({
          $or: [
            { 'woovi.paidAt': { $gte: todayStartIso, $lt: todayEndIso } },
            { paidAt: { $gte: todayStartIso, $lt: todayEndIso } }
          ]
        });
        createdEmailCountToday = await col.countDocuments({
          createdAt: { $gte: todayStartIso, $lt: todayEndIso }
        });
        const agg = await col.aggregate([
          { $match: { 'recoveryNotify.email.history': { $exists: true, $ne: [] } } },
          { $unwind: '$recoveryNotify.email.history' },
          { $match: { 'recoveryNotify.email.history.status': 'sent', 'recoveryNotify.email.history.at': { $gte: todayStartIso, $lt: todayEndIso } } },
          { $count: 'c' }
        ]).toArray();
        recoveryEmailSentEventsToday = agg && agg[0] && typeof agg[0].c === 'number' ? agg[0].c : 0;
        const agg2 = await col.aggregate([
          { $match: { 'recoveryNotify.email.history': { $exists: true, $ne: [] } } },
          { $unwind: '$recoveryNotify.email.history' },
          { $match: { 'recoveryNotify.email.history.status': 'sent', 'recoveryNotify.email.history.at': { $gte: todayStartIso, $lt: todayEndIso } } },
          { $group: { _id: '$_id' } },
          { $count: 'c' }
        ]).toArray();
        recoveryEmailSentOrdersToday = agg2 && agg2[0] && typeof agg2[0].c === 'number' ? agg2[0].c : 0;
      }
    } catch (_) {}
    const pedidosEmailCountToday = Math.max(0, Number(paidEmailCountToday || 0) + Number(createdEmailCountToday || 0));
    const availableAfterPedidos = Math.max(0, dailyMax - pedidosEmailCountToday);
    const allowedForRecoveryToday = Math.max(0, Math.floor(availableAfterPedidos * (1 - reservePct)));
    const remainingRecoveryToday = Math.max(0, allowedForRecoveryToday - Number(recoveryEmailSentEventsToday || 0));

    const monDocs = await monitorCol.find(
      { checkedAt: { $exists: true, $ne: '' }, hidden: { $ne: true } },
      { projection: { _id: 0, username: 1, followersCount: 1, checkedAt: 1, hidden: 1 } }
    ).limit(50000).toArray();
    const parseDateMsLoose = (raw) => {
      try {
        const s0 = String(raw || '').trim();
        if (!s0) return 0;
        const s = s0.replace(',', ' ').replace(/\s+/g, ' ').trim();
        const mBr = s.match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?/);
        if (mBr) {
          const yyyy = String(mBr[3]);
          const mm = String(mBr[2]).padStart(2, '0');
          const dd = String(mBr[1]).padStart(2, '0');
          const hh = String(mBr[4] || '00').padStart(2, '0');
          const mi = String(mBr[5] || '00').padStart(2, '0');
          const ss = String(mBr[6] || '00').padStart(2, '0');
          const iso = `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}-03:00`;
          const t = new Date(iso).getTime();
          return Number.isFinite(t) ? t : 0;
        }
        const t = new Date(s).getTime();
        return Number.isFinite(t) ? t : 0;
      } catch (_) {
        return 0;
      }
    };
    const monByUser = new Map();
    stats.monitorDocs = Array.isArray(monDocs) ? monDocs.length : 0;
    for (const m of (monDocs || [])) {
      const u = safe(m && m.username).toLowerCase().replace(/^@/, '');
      if (!u) continue;
      const checkedAtMs = parseDateMsLoose(m && m.checkedAt);
      const followersCount = (typeof m?.followersCount === 'number') ? m.followersCount : null;
      if (!checkedAtMs) { stats.monitorSkippedNoCheckedAt += 1; continue; }
      if (followersCount == null) { stats.monitorSkippedNoFollowers += 1; continue; }
      stats.monitorUsable += 1;
      monByUser.set(u, { checkedAtMs, followersCount });
    }
    if (!monByUser.size) return res.json({ ok: true, total: 0, candidates: [] });

    const followersQuery = {
      $and: [
        {
          $or: [
            { status: 'paid' },
            { paymentStatus: 'paid' },
            { paymentStatus: 'approved' },
            { paymentStatus: 'succeeded' },
            { paymentStatus: 'received' },
            { 'woovi.status': { $in: ['PAID', 'COMPLETED'] } },
            { paidAt: { $exists: true, $ne: null } },
            { 'woovi.paidAt': { $exists: true, $ne: null } }
          ]
        },
        {
          $or: [
            { categoria_servico: { $regex: '^seguidores$', $options: 'i' } },
            { 'additionalInfoMapPaid.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
            { 'additionalInfoMap.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
            { tipo: { $regex: 'seguidores', $options: 'i' } },
            { tipoServico: { $regex: 'seguidores', $options: 'i' } }
          ]
        }
      ]
    };
    const ordersCursor = col.find(followersQuery, {
      projection: {
        _id: 1, createdAt: 1, paidAt: 1, woovi: 1, tipo: 1, tipoServico: 1, qtd: 1, quantidade: 1,
        instagramUsername: 1, instauser: 1, initialFollowersCount: 1, isPrivate: 1, profilePrivacy: 1,
        additionalInfo: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfoMapPaid: 1,
        recoveryNotify: 1
      }
    }).sort({ createdAt: -1 }).limit(50000);

    const getMapObj = (o, k) => {
      try {
        if (o?.additionalInfoMapPaid && typeof o.additionalInfoMapPaid[k] !== 'undefined') return o.additionalInfoMapPaid[k];
        if (o?.additionalInfoMap && typeof o.additionalInfoMap[k] !== 'undefined') return o.additionalInfoMap[k];
      } catch (_) {}
      return undefined;
    };
    const getArrVal = (arr, key) => {
      try {
        const a = Array.isArray(arr) ? arr : [];
        const it = a.find(x => x && safe(x.key).toLowerCase() === String(key || '').toLowerCase());
        return it && typeof it.value !== 'undefined' ? it.value : undefined;
      } catch (_) { return undefined; }
    };
    const pick = (o, key) => {
      const a = getMapObj(o, key);
      if (typeof a !== 'undefined') return a;
      const b = getArrVal(o?.additionalInfoPaid, key);
      if (typeof b !== 'undefined') return b;
      const c = getArrVal(o?.additionalInfo, key);
      if (typeof c !== 'undefined') return c;
      return undefined;
    };
    const resolveUsername = (o) => {
      const u = safe(o?.instagramUsername || o?.instauser || pick(o, 'instagram_username') || pick(o, 'instauser')).toLowerCase();
      return u.replace(/^@/, '').replace(/\/+$/, '').split('/').pop().trim();
    };
    const resolveDateMs = (o) => {
      const t = new Date(o?.woovi?.paidAt || o?.paidAt || o?.createdAt || 0).getTime();
      return Number.isFinite(t) ? t : 0;
    };
    const isPrivateOrder = (o) => {
      const a = o?.isPrivate;
      const b = o?.profilePrivacy;
      const c = pick(o, 'isPrivate');
      return a === true || b === true || String(c || '').toLowerCase() === 'true';
    };

    const latestByUser = new Map();
    for await (const o of ordersCursor) {
      stats.ordersScanned += 1;
      const u = resolveUsername(o);
      if (!u) { stats.ordersSkippedNoUsername += 1; continue; }
      if (!monByUser.has(u)) { stats.ordersSkippedNoMonitor += 1; continue; }
      const tipoRaw = safe(o?.tipoServico || o?.tipo || pick(o, 'tipo_servico')).toLowerCase();
      if (tipoRaw && /seguidores_organicos|organicos/.test(tipoRaw)) { stats.ordersSkippedOrganicos += 1; continue; }
      const ms = resolveDateMs(o);
      const prev = latestByUser.get(u);
      if (!prev || ms > prev.ms) latestByUser.set(u, { ms, order: o });
    }
    stats.ordersLatestByUser = latestByUser.size;

    const out = [];
    for (const [u, rec] of latestByUser.entries()) {
      stats.candidatesScanned += 1;
      const o = rec.order;
      const mon = monByUser.get(u);
      if (!o || !mon) continue;
      const qty = Number(o?.qtd || o?.quantidade || pick(o, 'quantidade') || pick(o, 'qtd') || pick(o, 'quantity') || 0) || 0;
      const initial = (typeof o?.initialFollowersCount === 'number') ? o.initialFollowersCount : Number(pick(o, 'start_count') || pick(o, 'initial_followers') || pick(o, 'inicial') || 0) || 0;
      if (!(qty > 0 && initial > 0)) { stats.candidatesSkippedMissingQtyOrInitial += 1; continue; }
      const expected = initial + qty;
      const current = mon.followersCount;
      if (current == null) { stats.candidatesSkippedNoCurrent += 1; continue; }
      const dropAbs = Math.max(0, expected - current);
      if (!(current < expected)) { stats.candidatesSkippedDropBelow100 += 1; continue; }
      if (dropAbs < 100) { stats.candidatesSkippedDropBelow100 += 1; continue; }

      const notify = (o && o.recoveryNotify && typeof o.recoveryNotify === 'object') ? o.recoveryNotify : {};
      const nEmail = (notify && notify.email && typeof notify.email === 'object') ? notify.email : {};
      const nSms = (notify && notify.sms && typeof notify.sms === 'object') ? notify.sms : {};
      const emailOk = String(nEmail.lastStatus || '').trim().toLowerCase() === 'sent';
      const smsOk = !!safe(nSms.sentAt);
      if (emailOk && smsOk) { stats.candidatesSkippedAlreadyNotified += 1; continue; }

      out.push({ orderId: String(o._id), username: u, checkedAtMs: Number(mon.checkedAtMs || 0) || 0, dropAbs });
    }
    stats.eligible = out.length;

    out.sort((a, b) => order === 'oldest' ? (a.checkedAtMs - b.checkedAtMs) : (b.checkedAtMs - a.checkedAtMs));
    const dailyCap = remainingRecoveryToday > 0 ? remainingRecoveryToday : 0;
    const capLimit = dailyCap > 0 ? dailyCap : 0;
    const maxCandidates = (limit > 0 && capLimit > 0) ? Math.min(limit, capLimit) : (limit > 0 ? limit : (capLimit > 0 ? capLimit : 0));
    const sliced = maxCandidates > 0 ? out.slice(0, maxCandidates) : out;
    return res.json({
      ok: true,
      total: out.length,
      candidates: sliced,
      emailBudget: {
        todayBrtKey,
        dailyMax,
        reservePct,
        paidEmailCountToday,
        createdEmailCountToday,
        pedidosEmailCountToday,
        availableAfterPedidos,
        allowedForRecoveryToday,
        recoveryEmailSentEventsToday,
        recoveryEmailSentOrdersToday,
        remainingRecoveryToday
      },
      stats
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.get('/api/painel/gerenciamento-seguidores/recovery-email-audit', requireAdmin, async (req, res) => {
  try {
    const safe = (v) => String(v == null ? '' : v).trim();
    const dayKey = safe(req.query.day || '');
    const brtOffsetMs = 3 * 60 * 60 * 1000;
    const dayKeyBrt = (ms) => {
      const d = new Date(Number(ms || 0) - brtOffsetMs);
      const y = String(d.getUTCFullYear());
      const m = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd = String(d.getUTCDate()).padStart(2, '0');
      return `${y}-${m}-${dd}`;
    };
    const todayKey = dayKeyBrt(Date.now());
    const useKey = /^\d{4}-\d{2}-\d{2}$/.test(dayKey) ? dayKey : todayKey;
    const parts = useKey.split('-').map(Number);
    const startUtcMs = Date.UTC(parts[0], parts[1] - 1, parts[2], 0, 0, 0, 0) + brtOffsetMs;
    const endUtcMs = startUtcMs + (24 * 60 * 60 * 1000);
    const startIso = new Date(startUtcMs).toISOString();
    const endIso = new Date(endUtcMs).toISOString();

    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');

    const baseMatch = {
      'recoveryNotify.email.history': { $exists: true, $ne: [] }
    };
    const sentMatch = {
      'recoveryNotify.email.history.status': 'sent',
      'recoveryNotify.email.history.at': { $gte: startIso, $lt: endIso }
    };
    const totalAgg = await col.aggregate([
      { $match: baseMatch },
      { $unwind: '$recoveryNotify.email.history' },
      { $match: sentMatch },
      { $count: 'c' }
    ]).toArray();
    const totalEvents = totalAgg && totalAgg[0] && typeof totalAgg[0].c === 'number' ? totalAgg[0].c : 0;

    const ordersAgg = await col.aggregate([
      { $match: baseMatch },
      { $unwind: '$recoveryNotify.email.history' },
      { $match: sentMatch },
      { $group: { _id: '$_id' } },
      { $count: 'c' }
    ]).toArray();
    const distinctOrders = ordersAgg && ordersAgg[0] && typeof ordersAgg[0].c === 'number' ? ordersAgg[0].c : 0;

    const byHour = await col.aggregate([
      { $match: baseMatch },
      { $unwind: '$recoveryNotify.email.history' },
      { $match: sentMatch },
      {
        $addFields: {
          atDate: {
            $convert: {
              input: '$recoveryNotify.email.history.at',
              to: 'date',
              onError: null,
              onNull: null
            }
          }
        }
      },
      { $match: { atDate: { $ne: null } } },
      { $group: { _id: { $hour: '$atDate' }, c: { $sum: 1 } } },
      { $sort: { _id: 1 } }
    ]).toArray();

    const sample = await col.aggregate([
      { $match: baseMatch },
      { $unwind: '$recoveryNotify.email.history' },
      { $match: sentMatch },
      { $sort: { 'recoveryNotify.email.history.at': -1 } },
      { $limit: 25 },
      { $project: { _id: 1, at: '$recoveryNotify.email.history.at', status: '$recoveryNotify.email.history.status' } }
    ]).toArray();

    return res.json({ ok: true, dayBrtKey: useKey, startIso, endIso, totalEvents, distinctOrders, byHour, sample });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.get('/api/painel/gerenciamento-seguidores/stats/pacote-seguidores-sem-categoria', requireAdmin, async (req, res) => {
  try {
    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');

    const paidQuery = { $or: [{ status: 'pago' }, { 'woovi.status': 'pago' }, { status: 'paid' }, { paymentStatus: 'paid' }, { paymentStatus: 'approved' }] };
    const pacoteRegex = { $regex: '\\bseguidores\\b', $options: 'i' };
    const hasPacoteSeguidores = {
      $or: [
        { additionalInfoPaid: { $elemMatch: { key: 'pacote', value: pacoteRegex } } },
        { additionalInfo: { $elemMatch: { key: 'pacote', value: pacoteRegex } } },
        { 'additionalInfoMapPaid.pacote': pacoteRegex },
        { 'additionalInfoMap.pacote': pacoteRegex }
      ]
    };
    const hasCategoriaSeguidores = {
      $or: [
        { additionalInfoPaid: { $elemMatch: { key: 'categoria_servico', value: { $regex: '^seguidores$', $options: 'i' } } } },
        { 'additionalInfoMapPaid.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
        { 'additionalInfoMap.categoria_servico': { $regex: '^seguidores$', $options: 'i' } }
      ]
    };
    const hasTipoSeguidores = {
      $or: [
        { tipo: { $regex: 'seguidores', $options: 'i' } },
        { tipoServico: { $regex: 'seguidores', $options: 'i' } }
      ]
    };

    const query = { $and: [paidQuery, hasPacoteSeguidores, { $nor: [hasCategoriaSeguidores, hasTipoSeguidores] }] };
    const total = await col.countDocuments(query);
    const sampleDocs = await col.find(query, {
      projection: {
        _id: 1,
        identifier: 1,
        createdAt: 1,
        paidAt: 1,
        woovi: 1,
        instauser: 1,
        instagramUsername: 1,
        tipo: 1,
        tipoServico: 1,
        additionalInfoMapPaid: 1,
        additionalInfoMap: 1
      }
    }).sort({ createdAt: -1 }).limit(25).toArray();

    const sample = (Array.isArray(sampleDocs) ? sampleDocs : []).map((d) => {
      const pacote = (d.additionalInfoMapPaid && d.additionalInfoMapPaid.pacote) || (d.additionalInfoMap && d.additionalInfoMap.pacote) || null;
      return {
        id: String(d._id),
        identifier: d.identifier || null,
        username: d.instagramUsername || d.instauser || null,
        tipo: d.tipoServico || d.tipo || null,
        createdAt: d.createdAt || null,
        paidAt: d.paidAt || (d.woovi && d.woovi.paidAt) || null,
        pacote
      };
    });

    return res.json({ ok: true, total, sample });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.post('/api/painel/gerenciamento-seguidores/fix-checked-global', requireAdmin, async (req, res) => {
  try {
    const body = req.body || {};
    const limitRaw = parseInt(String(body.limit || '0'), 10);
    const limit = Math.max(0, Math.min(20000, Number.isFinite(limitRaw) ? limitRaw : 0));
    const orderRaw = String(body.order || 'recent').trim().toLowerCase();
    const order = (orderRaw === 'oldest') ? 'oldest' : 'recent';
    const safe = (v) => String(v == null ? '' : v).trim();

    const { getCollection } = require('./mongodbClient');
    const col = await getCollection('checkout_orders');
    const monitorCol = await getCollection('followers_monitor');

    const parseDateMsLoose = (raw) => {
      try {
        const s0 = String(raw || '').trim();
        if (!s0) return 0;
        const s = s0.replace(',', ' ').replace(/\s+/g, ' ').trim();
        const mBr = s.match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?/);
        if (mBr) {
          const yyyy = String(mBr[3]);
          const mm = String(mBr[2]).padStart(2, '0');
          const dd = String(mBr[1]).padStart(2, '0');
          const hh = String(mBr[4] || '00').padStart(2, '0');
          const mi = String(mBr[5] || '00').padStart(2, '0');
          const ss = String(mBr[6] || '00').padStart(2, '0');
          const iso = `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}-03:00`;
          const t = new Date(iso).getTime();
          return Number.isFinite(t) ? t : 0;
        }
        const t = new Date(s).getTime();
        return Number.isFinite(t) ? t : 0;
      } catch (_) {
        return 0;
      }
    };
    const dayMs = 24 * 60 * 60 * 1000;
    const brtOffsetMs = 3 * 60 * 60 * 1000;
    const dayNumFromMsBrt = (ms) => {
      const d = new Date(Number(ms || 0) - brtOffsetMs);
      return Math.floor(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / dayMs);
    };

    const monDocs = await monitorCol.find(
      { checkedAt: { $exists: true, $ne: '' }, hidden: { $ne: true } },
      { projection: { _id: 0, username: 1, checkedAt: 1, hidden: 1 } }
    ).limit(80000).toArray();
    const monByUser = new Map();
    for (const m of (monDocs || [])) {
      const u = safe(m && m.username).toLowerCase().replace(/^@/, '');
      if (!u) continue;
      const checkedAtMs = parseDateMsLoose(m && m.checkedAt);
      if (!checkedAtMs) continue;
      monByUser.set(u, { checkedAtMs });
    }
    if (!monByUser.size) return res.json({ ok: true, total: 0, fixedCount: 0 });

    const followersQuery = {
      $and: [
        {
          $or: [
            { status: 'paid' },
            { paymentStatus: 'paid' },
            { paymentStatus: 'approved' },
            { paymentStatus: 'succeeded' },
            { paymentStatus: 'received' },
            { 'woovi.status': { $in: ['PAID', 'COMPLETED'] } },
            { paidAt: { $exists: true, $ne: null } },
            { 'woovi.paidAt': { $exists: true, $ne: null } }
          ]
        },
        {
          $or: [
            { categoria_servico: { $regex: '^seguidores$', $options: 'i' } },
            { 'additionalInfoMapPaid.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
            { 'additionalInfoMap.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
            { tipo: { $regex: 'seguidores', $options: 'i' } },
            { tipoServico: { $regex: 'seguidores', $options: 'i' } }
          ]
        }
      ]
    };
    const ordersCursor = col.find(followersQuery, {
      projection: {
        _id: 1, createdAt: 1, paidAt: 1, woovi: 1, tipo: 1, tipoServico: 1,
        instagramUsername: 1, instauser: 1,
        isPrivate: 1, profilePrivacy: 1,
        additionalInfo: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfoMapPaid: 1
      }
    }).sort({ createdAt: -1 }).limit(80000);

    const getMapObj = (o, k) => {
      try {
        if (o?.additionalInfoMapPaid && typeof o.additionalInfoMapPaid[k] !== 'undefined') return o.additionalInfoMapPaid[k];
        if (o?.additionalInfoMap && typeof o.additionalInfoMap[k] !== 'undefined') return o.additionalInfoMap[k];
      } catch (_) {}
      return undefined;
    };
    const getArrVal = (arr, key) => {
      try {
        const a = Array.isArray(arr) ? arr : [];
        const it = a.find(x => x && safe(x.key).toLowerCase() === String(key || '').toLowerCase());
        return it && typeof it.value !== 'undefined' ? it.value : undefined;
      } catch (_) { return undefined; }
    };
    const pick = (o, key) => {
      const a = getMapObj(o, key);
      if (typeof a !== 'undefined') return a;
      const b = getArrVal(o?.additionalInfoPaid, key);
      if (typeof b !== 'undefined') return b;
      const c = getArrVal(o?.additionalInfo, key);
      if (typeof c !== 'undefined') return c;
      return undefined;
    };
    const resolveUsername = (o) => {
      const u = safe(o?.instagramUsername || o?.instauser || pick(o, 'instagram_username') || pick(o, 'instauser')).toLowerCase();
      return u.replace(/^@/, '').replace(/\/+$/, '').split('/').pop().trim();
    };
    const resolveDateMs = (o) => {
      const t = new Date(o?.woovi?.paidAt || o?.paidAt || o?.createdAt || 0).getTime();
      return Number.isFinite(t) ? t : 0;
    };
    const isPrivateOrder = (o) => {
      const a = o?.isPrivate;
      const b = o?.profilePrivacy;
      const c = pick(o, 'isPrivate');
      return a === true || b === true || String(c || '').toLowerCase() === 'true';
    };

    const purchaseByUser = new Map();
    for await (const o of ordersCursor) {
      const u = resolveUsername(o);
      if (!u) continue;
      if (!monByUser.has(u)) continue;
      if (isPrivateOrder(o)) continue;
      const ms = resolveDateMs(o);
      if (!ms) continue;
      const prev = purchaseByUser.get(u) || 0;
      if (!prev || ms > prev) purchaseByUser.set(u, ms);
    }

    const candidates = [];
    for (const [u, mon] of monByUser.entries()) {
      const purchaseMs = Number(purchaseByUser.get(u) || 0) || 0;
      if (!purchaseMs) continue;
      const checkedDay = dayNumFromMsBrt(mon.checkedAtMs);
      const purchaseDay = dayNumFromMsBrt(purchaseMs);
      if (checkedDay <= purchaseDay) {
        candidates.push({ username: u, checkedAtMs: mon.checkedAtMs, purchaseMs });
      }
    }

    candidates.sort((a, b) => order === 'oldest' ? (a.checkedAtMs - b.checkedAtMs) : (b.checkedAtMs - a.checkedAtMs));
    const picked = (limit > 0) ? candidates.slice(0, limit) : candidates;
    if (!picked.length) return res.json({ ok: true, total: candidates.length, fixedCount: 0 });

    const ops = picked.map(it => ({
      updateOne: {
        filter: { username: it.username },
        update: { $unset: { checkedAt: '', followersCount: '', source: '', error: '', isPrivate: '' } },
        upsert: false
      }
    }));
    await monitorCol.bulkWrite(ops, { ordered: false });
    return res.json({ ok: true, total: candidates.length, fixedCount: picked.length });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.post('/api/painel/gerenciamento-seguidores/extend-refil-expired', requireAdmin, async (req, res) => {
  try {
    const body = (req && req.body && typeof req.body === 'object') ? req.body : {};
    const daysRaw = parseInt(String(body.days || body.daysToAdd || body.extendDays || '30'), 10);
    const daysToAdd = Math.min(365, Math.max(1, Number.isFinite(daysRaw) ? daysRaw : 30));
    const dryRun = String(body.dryRun || body.preview || '').trim() === '1' || body.dryRun === true || body.preview === true;

    const { getCollection } = require('./mongodbClient');
    const ordersCol = await getCollection('checkout_orders');
    const tlCol = await getCollection('temporary_links');

    if (!ordersCol || typeof ordersCol.find !== 'function' || !tlCol || typeof tlCol.find !== 'function') {
      return res.status(500).json({ ok: false, error: 'mongo_disabled' });
    }

    const paidQuery = { $or: [{ status: 'pago' }, { 'woovi.status': 'pago' }] };
    const seguidoresQuery = {
      $or: [
        { additionalInfoPaid: { $elemMatch: { key: 'categoria_servico', value: { $regex: '^seguidores$', $options: 'i' } } } },
        { 'additionalInfoMapPaid.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
        { 'additionalInfoMap.categoria_servico': { $regex: '^seguidores$', $options: 'i' } },
        { tipo: { $regex: 'seguidores', $options: 'i' } },
        { tipoServico: { $regex: 'seguidores', $options: 'i' } }
      ]
    };
    // Modo "marcados": estende a reposição expirada apenas dos pedidos selecionados (orderIds e/ou
    // usernames vindos das linhas marcadas). Sem seleção → comportamento antigo (quem recebeu email).
    const { ObjectId } = require('mongodb');
    const selOrderIds = Array.isArray(body.orderIds) ? Array.from(new Set(body.orderIds.map(x => String(x || '').trim()).filter(s => /^[0-9a-fA-F]{24}$/.test(s)))).slice(0, 5000) : [];
    const selUsernames = Array.isArray(body.usernames) ? Array.from(new Set(body.usernames.map(x => String(x || '').trim().replace(/^@+/, '').toLowerCase()).filter(Boolean))).slice(0, 5000) : [];
    const markedMode = (selOrderIds.length > 0 || selUsernames.length > 0);

    let query;
    if (markedMode) {
      const idObjs = selOrderIds.map(s => { try { return new ObjectId(s); } catch (_) { return null; } }).filter(Boolean);
      const markedOr = [];
      if (idObjs.length) markedOr.push({ _id: { $in: idObjs } });
      if (selUsernames.length) {
        const rxs = selUsernames.map(u => new RegExp('^@?' + u.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$', 'i'));
        markedOr.push({ instauser: { $in: rxs } });
        markedOr.push({ instagramUsername: { $in: rxs } });
        markedOr.push({ 'additionalInfoMapPaid.instagram_username': { $in: rxs } });
        markedOr.push({ 'additionalInfoMap.instagram_username': { $in: rxs } });
      }
      query = { $and: [paidQuery, seguidoresQuery, { $or: markedOr }] };
    } else {
      query = { $and: [paidQuery, seguidoresQuery, { 'recoveryNotify.email.history': { $elemMatch: { status: 'sent' } } }] };
    }

    const extractInfoAny = (o, key) => {
      try {
        if (o?.additionalInfoMapPaid && typeof o.additionalInfoMapPaid[key] !== 'undefined') return o.additionalInfoMapPaid[key];
        if (o?.additionalInfoMap && typeof o.additionalInfoMap[key] !== 'undefined') return o.additionalInfoMap[key];
        const arrPaid = Array.isArray(o?.additionalInfoPaid) ? o.additionalInfoPaid : [];
        const itemPaid = arrPaid.find(i => i && String(i.key || '').trim() === key);
        if (itemPaid && typeof itemPaid.value !== 'undefined') return itemPaid.value;
        const arr = Array.isArray(o?.additionalInfo) ? o.additionalInfo : [];
        const item = arr.find(i => i && String(i.key || '').trim() === key);
        if (item && typeof item.value !== 'undefined') return item.value;
      } catch (_) {}
      return '';
    };
    const normalizeUsernameKey = (u) => {
      try {
        let s = String(u || '').trim();
        if (!s) return '';
        if (/^https?:\/\//i.test(s)) {
          s = s.replace(/^https?:\/\/(www\.)?instagram\.com\//i, '');
          s = s.split('?')[0].split('#')[0];
          s = s.replace(/\/+$/, '');
          const parts = s.split('/').filter(Boolean);
          s = parts.length ? String(parts[parts.length - 1] || '') : s;
        }
        s = s.trim();
        if (s.startsWith('@')) s = s.slice(1);
        return s.toLowerCase().trim();
      } catch (_) {
        return '';
      }
    };
    const normalizePhoneDigits = (raw) => {
      try {
        let digits = String(raw || '').replace(/\D/g, '');
        if (digits.startsWith('55') && digits.length > 11) digits = digits.slice(2);
        if (!(digits.length === 10 || digits.length === 11)) return '';
        return digits;
      } catch (_) {
        return '';
      }
    };

    const cursor = ordersCol.find(query, {
      projection: {
        _id: 1,
        refilLinkId: 1,
        paidAt: 1,
        createdAt: 1,
        woovi: 1,
        customer: 1,
        telefone: 1,
        instagramUsername: 1,
        instauser: 1,
        additionalInfo: 1,
        additionalInfoPaid: 1,
        additionalInfoMap: 1,
        additionalInfoMapPaid: 1
      }
    });
    if (!cursor || typeof cursor[Symbol.asyncIterator] !== 'function') {
      return res.status(500).json({ ok: false, error: 'mongo_cursor_not_iterable' });
    }

    let ordersMatched = 0;
    const orderIdStrs = [];
    const usernamesSet = new Set();
    const phonesSet = new Set();
    const ordersLite = [];
    for await (const o of cursor) {
      ordersMatched += 1;
      const orderIdStr = (o && o._id) ? String(o._id) : '';
      if (orderIdStr) orderIdStrs.push(orderIdStr);
      const iu = normalizeUsernameKey(o?.instagramUsername || o?.instauser || extractInfoAny(o, 'instagram_username') || '');
      if (iu) usernamesSet.add(iu);
      const cust = (o && o.customer && typeof o.customer === 'object') ? o.customer : {};
      const phoneRaw = cust.phone_number || cust.phone || cust.telefone || cust.whatsapp || o?.telefone || extractInfoAny(o, 'phone') || extractInfoAny(o, 'telefone') || extractInfoAny(o, 'whatsapp') || '';
      const phoneDigits = normalizePhoneDigits(phoneRaw);
      if (phoneDigits) phonesSet.add(phoneDigits);
      const baseMs = (() => {
        try {
          const t = new Date(o?.woovi?.paidAt || o?.paidAt || o?.createdAt || 0).getTime();
          return Number.isFinite(t) ? t : 0;
        } catch (_) {
          return 0;
        }
      })();
      const bumpsStr = String((o?.additionalInfoMapPaid && typeof o.additionalInfoMapPaid.order_bumps !== 'undefined') ? o.additionalInfoMapPaid.order_bumps : ((o?.additionalInfoMap && typeof o.additionalInfoMap.order_bumps !== 'undefined') ? o.additionalInfoMap.order_bumps : (extractInfoAny(o, 'order_bumps') || ''))).trim();
      const refilLinkId = (o && o.refilLinkId) ? String(o.refilLinkId).trim() : '';
      if (orderIdStr) {
        ordersLite.push({ orderIdStr, iu, phoneDigits, baseMs, bumpsStr, refilLinkId });
      }
      if (orderIdStrs.length > 250000) break;
    }

    const orderIdsUnique = Array.from(new Set(orderIdStrs));
    const usernames = Array.from(usernamesSet).slice(0, 50000);
    const phones = Array.from(phonesSet).slice(0, 50000);
    if (!orderIdsUnique.length) {
      return res.json({ ok: true, daysToAdd, dryRun, ordersMatched, ordersUnique: 0, linksFound: 0, linksExpired: 0, updatesPlanned: 0, updated: 0 });
    }

    const or = [{ orderId: { $in: orderIdsUnique } }, { orders: { $in: orderIdsUnique } }];
    if (usernames.length) {
      or.push({ instauser: { $in: usernames } });
      or.push({ instausers: { $in: usernames } });
    }
    if (phones.length) {
      or.push({ phone: { $in: phones } });
    }
    const tlDocs = await tlCol.find(
      { purpose: 'refil', $or: or },
      { projection: { _id: 1, id: 1, orderId: 1, orders: 1, phone: 1, instauser: 1, instausers: 1, expiresAt: 1, warrantyMode: 1 } }
    ).toArray();

    const nowMs = Date.now();
    const dayMs = 24 * 60 * 60 * 1000;
    const brtOffsetMs = 3 * 60 * 60 * 1000;

    const brtYmdFromMs = (ms) => {
      const d = new Date(Number(ms || 0) - brtOffsetMs);
      return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
    };
    const dayNumFromYmd = (y, m, d) => Math.floor(Date.UTC(Number(y), Number(m) - 1, Number(d)) / dayMs);
    const ymdFromDayNum = (dayNum) => {
      const dt = new Date(Number(dayNum || 0) * dayMs);
      return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
    };
    const endOfDayBrtIsoFromYmd = (y, m, d) => {
      const utcMs = Date.UTC(Number(y), Number(m) - 1, Number(d), 23, 59, 59, 999) + brtOffsetMs;
      return new Date(utcMs).toISOString();
    };
    const addDaysEndOfDayBrtIso = (baseMs, days) => {
      const baseYmd = brtYmdFromMs(baseMs);
      const baseDayNum = dayNumFromYmd(baseYmd.y, baseYmd.m, baseYmd.d);
      const target = ymdFromDayNum(baseDayNum + Number(days || 0));
      return endOfDayBrtIsoFromYmd(target.y, target.m, target.d);
    };
    const safeDateMs = (iso) => {
      try {
        const t = new Date(iso).getTime();
        return Number.isFinite(t) ? t : 0;
      } catch (_) {
        return 0;
      }
    };

    const daysInMonth = (y, m) => new Date(Date.UTC(Number(y), Number(m), 0)).getUTCDate();
    const addMonthsEndOfDayBrtIso = (baseMs, monthsToAdd) => {
      const base = brtYmdFromMs(baseMs);
      let y = base.y;
      let m = base.m + Number(monthsToAdd || 0);
      while (m > 12) { y += 1; m -= 12; }
      while (m < 1) { y -= 1; m += 12; }
      const maxDay = daysInMonth(y, m);
      const d = Math.min(base.d, maxDay);
      const utcMs = Date.UTC(y, m - 1, d, 23, 59, 59, 999) + brtOffsetMs;
      return new Date(utcMs).toISOString();
    };
    const warrantyFromBumps = (bumpsStrRaw) => {
      const out = { isLifetime: false, mode: '30', months: 1 };
      try {
        const s = String(bumpsStrRaw || '').trim();
        if (!s) return out;
        const parts = s.split(';');
        let hasLife = false;
        let has6m = false;
        let has12m = false;
        for (const raw of parts) {
          const part = String(raw || '').trim();
          if (!part) continue;
          const segs = part.split(':');
          const key = String(segs[0] || '').trim().toLowerCase();
          const qtyRaw = segs.length > 1 ? String(segs[1] || '').trim() : '';
          const qtyParsed = qtyRaw ? Number(qtyRaw) : 1;
          const qty = Number.isFinite(qtyParsed) ? qtyParsed : 1;
          if (!(qty > 0)) continue;
          if (key === 'warranty_lifetime' || key === 'warranty_life' || key === 'warrenty') hasLife = true;
          else if (key === 'warranty_6m' || key === 'warranty6m') has6m = true;
          else if (key === 'warranty60' || key === 'warranty_60' || key === 'warrenty60' || key === 'warrenty_60') has12m = true;
        }
        if (hasLife) return { isLifetime: true, mode: 'life', months: null };
        if (has6m) return { isLifetime: false, mode: '6m', months: 6 };
        if (has12m) return { isLifetime: false, mode: '12m', months: 12 };
      } catch (_) {}
      return out;
    };

    const byOrderId = new Map();
    const byPhone = new Map();
    const byInsta = new Map();
    const byToken = new Map();
    for (const d of (tlDocs || [])) {
      const token = d && d.id ? String(d.id).trim() : '';
      if (token && !byToken.has(token)) byToken.set(token, d);
      const phone = d && d.phone ? String(d.phone).replace(/\D/g, '') : '';
      if (phone && !byPhone.has(phone)) byPhone.set(phone, d);
      const iu0 = d && d.instauser ? normalizeUsernameKey(d.instauser) : '';
      if (iu0 && !byInsta.has(iu0)) byInsta.set(iu0, d);
      const arrIu = Array.isArray(d && d.instausers) ? d.instausers : [];
      for (const x of arrIu) {
        const iu = normalizeUsernameKey(x);
        if (iu && !byInsta.has(iu)) byInsta.set(iu, d);
      }
      const linked = new Set();
      if (d && d.orderId) linked.add(String(d.orderId));
      const arr = Array.isArray(d && d.orders) ? d.orders : [];
      for (const x of arr) { if (x) linked.add(String(x)); }
      for (const oid of linked) {
        const s = String(oid || '').trim();
        if (s && !byOrderId.has(s)) byOrderId.set(s, d);
      }
    }

    const expiredOrders = [];
    for (const o of (ordersLite || [])) {
      const oid = String(o && o.orderIdStr || '').trim();
      if (!oid) continue;
      const baseMs = Number(o && o.baseMs || 0) || 0;
      if (!baseMs) continue;
      const w = warrantyFromBumps(o && o.bumpsStr);
      if (w && w.isLifetime) continue;
      const expIso = addMonthsEndOfDayBrtIso(baseMs, Number((w && w.months) || 1));
      const expMs = safeDateMs(expIso);
      if (!expMs) continue;
      if (expMs >= nowMs) continue;
      expiredOrders.push({ orderIdStr: oid, iu: o.iu || '', phoneDigits: o.phoneDigits || '', refilLinkId: o.refilLinkId || '' });
    }

    const crypto = require('crypto');
    const usedTokens = new Set(Array.from(byToken.keys()));
    const safeToken = () => crypto.randomBytes(10).toString('hex');
    const findUniqueToken = async () => {
      for (let i = 0; i < 50; i += 1) {
        const t = safeToken();
        if (usedTokens.has(t)) continue;
        const exists = await tlCol.findOne({ id: t }, { projection: { _id: 1 } });
        if (exists) continue;
        usedTokens.add(t);
        return t;
      }
      return safeToken();
    };

    let linksExpired = 0;
    let createdMissingLinks = 0;
    let updatedOrders = 0;
    const ops = [];
    const orderOps = [];
    const sample = [];

    const maybeQueueOrderRef = (linkRec, orderIdStr, iu, phoneDigits) => {
      try {
        const linkToken = String(linkRec?.id || '').trim();
        if (!linkToken) return;
        const setObj = {};
        if (phoneDigits && !String(linkRec?.phone || '').trim()) setObj.phone = phoneDigits;
        if (iu && !String(linkRec?.instauser || '').trim()) setObj.instauser = iu;
        const addToSet = {};
        if (orderIdStr) addToSet.orders = orderIdStr;
        if (iu) addToSet.instausers = iu;
        const upd = {};
        if (Object.keys(setObj).length) upd.$set = setObj;
        if (Object.keys(addToSet).length) upd.$addToSet = addToSet;
        if (!Object.keys(upd).length) return;
        ops.push({ updateOne: { filter: { id: linkToken, purpose: 'refil' }, update: upd, upsert: false } });
      } catch (_) {}
    };

    for (const it of expiredOrders) {
      const orderIdStr = String(it && it.orderIdStr || '').trim();
      if (!orderIdStr) continue;
      const iu = normalizeUsernameKey(it && it.iu || '');
      const phoneDigits = normalizePhoneDigits(it && it.phoneDigits || '');
      const tokenHint = String(it && it.refilLinkId || '').trim().replace(/[^0-9a-z]/gi, '');

      let link = null;
      if (tokenHint && byToken.has(tokenHint)) link = byToken.get(tokenHint);
      if (!link) link = byOrderId.get(orderIdStr) || null;
      if (!link && iu) link = byInsta.get(iu) || null;
      if (!link && phoneDigits) link = byPhone.get(phoneDigits) || null;

      if (link && phoneDigits) {
        const existingInsta = normalizeUsernameKey(link?.instauser || '');
        const existingList = Array.isArray(link?.instausers) ? link.instausers.map(normalizeUsernameKey).filter(Boolean) : [];
        const canReuse = !iu || !existingInsta || existingInsta === iu || existingList.includes(iu);
        if (!canReuse) link = byOrderId.get(orderIdStr) || null;
      }

      if (link) {
        maybeQueueOrderRef(link, orderIdStr, iu, phoneDigits);
        const mode = String((link && link.warrantyMode) || '').trim().toLowerCase();
        if (mode !== 'life') {
          const expMs = safeDateMs(link && link.expiresAt);
          if (expMs && expMs < nowMs) {
            linksExpired += 1;
            const baseMs = Math.max(expMs, nowMs);
            const newIso = addDaysEndOfDayBrtIso(baseMs, daysToAdd);
            if (newIso && String(newIso) !== String(link.expiresAt || '')) {
              if (sample.length < 25) sample.push({ id: link && link.id ? String(link.id) : null, expiresAt: link && link.expiresAt ? String(link.expiresAt) : null, newExpiresAt: newIso });
              const linkToken = String(link && link.id || '').trim();
              if (linkToken) ops.push({ updateOne: { filter: { id: linkToken, purpose: 'refil' }, update: { $set: { expiresAt: newIso } }, upsert: false } });
              link.expiresAt = newIso;
            }
          }
        }
        if (tokenHint && tokenHint === String(link.id || '').trim()) continue;
        orderOps.push({
          updateOne: { filter: { _id: new (require('mongodb').ObjectId)(orderIdStr), $or: [{ refilLinkId: { $exists: false } }, { refilLinkId: null }, { refilLinkId: '' }] }, update: { $set: { refilLinkId: String(link.id || '').trim() } }, upsert: false }
        });
        updatedOrders += 1;
        continue;
      }

      const token = await findUniqueToken();
      const newIso = addDaysEndOfDayBrtIso(nowMs, daysToAdd);
      const rec = {
        id: token,
        purpose: 'refil',
        orderId: orderIdStr,
        phone: phoneDigits || null,
        orders: [orderIdStr],
        instauser: iu || null,
        instausers: iu ? [String(iu)] : [],
        warrantyMode: '30',
        warrantyDays: null,
        createdAt: new Date(nowMs).toISOString(),
        expiresAt: newIso
      };
      if (sample.length < 25) sample.push({ id: token, expiresAt: null, newExpiresAt: newIso });
      ops.push({ insertOne: { document: rec } });
      createdMissingLinks += 1;
      byToken.set(token, rec);
      byOrderId.set(orderIdStr, rec);
      if (iu) byInsta.set(iu, rec);
      if (phoneDigits) byPhone.set(phoneDigits, rec);
      orderOps.push({
        updateOne: { filter: { _id: new (require('mongodb').ObjectId)(orderIdStr) }, update: { $set: { refilLinkId: token } }, upsert: false }
      });
      updatedOrders += 1;
    }

    if (dryRun) {
      return res.json({
        ok: true,
        daysToAdd,
        dryRun: true,
        ordersMatched,
        ordersUnique: orderIdsUnique.length,
        linksFound: Array.isArray(tlDocs) ? tlDocs.length : 0,
        linksExpired,
        updatesPlanned: ops.length,
        createdMissingLinks,
        ordersExpiredCandidates: expiredOrders.length,
        sample
      });
    }

    let modified = 0;
    if (ops.length) {
      const wr = await tlCol.bulkWrite(ops, { ordered: false });
      modified = Number(wr && wr.modifiedCount || 0) || 0;
    }
    if (orderOps.length) {
      try {
        const wr2 = await ordersCol.bulkWrite(orderOps, { ordered: false });
        updatedOrders = Number(wr2 && wr2.modifiedCount || 0) || updatedOrders;
      } catch (_) {}
    }

    return res.json({
      ok: true,
      daysToAdd,
      dryRun: false,
      ordersMatched,
      ordersUnique: orderIdsUnique.length,
      linksFound: Array.isArray(tlDocs) ? tlDocs.length : 0,
      linksExpired,
      updatesPlanned: ops.length,
      updated: modified,
      createdMissingLinks,
      ordersExpiredCandidates: expiredOrders.length,
      updatedOrders,
      sample
    });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

async function followersMgmtNotifyRecoveryForOrder(req, { orderIdRaw, usernameInput }) {
  try {
    const safe = (v) => String(v == null ? '' : v).trim();
    const orderIdRawSafe = safe(orderIdRaw || '');
    const usernameInputSafe = safe(usernameInput || '').toLowerCase().replace(/^@/, '');
    if (!/^[0-9a-fA-F]{24}$/.test(orderIdRawSafe)) return { code: 400, body: { ok: false, error: 'invalid_order_id' } };

    const { getCollection } = require('./mongodbClient');
    const { ObjectId } = require('mongodb');
    const col = await getCollection('checkout_orders');

    const order = await col.findOne(
      { _id: new ObjectId(orderIdRawSafe) },
      { projection: { _id: 1, customer: 1, telefone: 1, instagramUsername: 1, instauser: 1, tipo: 1, tipoServico: 1, qtd: 1, quantidade: 1, initialFollowersCount: 1, additionalInfoMapPaid: 1, additionalInfoPaid: 1, additionalInfoMap: 1, additionalInfo: 1, recoveryNotify: 1 } }
    );
    if (!order) return { code: 404, body: { ok: false, error: 'order_not_found' } };

    const addMapPaid = (order && order.additionalInfoMapPaid && typeof order.additionalInfoMapPaid === 'object') ? order.additionalInfoMapPaid : {};
    const addMap = (order && order.additionalInfoMap && typeof order.additionalInfoMap === 'object') ? order.additionalInfoMap : {};
    const addPaid = Array.isArray(order && order.additionalInfoPaid) ? order.additionalInfoPaid : [];
    const addOrig = Array.isArray(order && order.additionalInfo) ? order.additionalInfo : [];
    const pickAdd = (key) => {
      const k = safe(key);
      if (!k) return '';
      if (typeof addMapPaid[k] !== 'undefined') return safe(addMapPaid[k]);
      if (typeof addMap[k] !== 'undefined') return safe(addMap[k]);
      const itPaid = addPaid.find(x => x && safe(x.key) === k);
      if (itPaid && typeof itPaid.value !== 'undefined') return safe(itPaid.value);
      const it = addOrig.find(x => x && safe(x.key) === k);
      if (it && typeof it.value !== 'undefined') return safe(it.value);
      return '';
    };

    const orderUsername = safe(order.instagramUsername || order.instauser || pickAdd('instagram_username')).toLowerCase().replace(/^@/, '');
    if (usernameInputSafe && orderUsername && usernameInputSafe !== orderUsername) return { code: 400, body: { ok: false, error: 'username_mismatch' } };

    const tipoRawNotify = safe(order.tipoServico || order.tipo || pickAdd('tipo_servico')).toLowerCase();
    const isOrganicosNotify = !!(tipoRawNotify && /seguidores_organicos|organicos/.test(tipoRawNotify));

    const customer = (order && order.customer && typeof order.customer === 'object') ? order.customer : {};
    const emailRaw = safe(customer.email || pickAdd('email') || pickAdd('customer_email') || pickAdd('email_cliente'));
    const email = (emailRaw && emailRaw.includes('@')) ? emailRaw : '';

    const phoneRaw = safe(customer.phone_number || customer.phone || customer.telefone || customer.whatsapp || order.telefone || pickAdd('phone') || pickAdd('telefone') || pickAdd('whatsapp'));
    let phoneDigits = phoneRaw.replace(/\D/g, '');
    if (phoneDigits.startsWith('55') && phoneDigits.length > 11) phoneDigits = phoneDigits.slice(2);
    if (!(phoneDigits.length === 10 || phoneDigits.length === 11)) phoneDigits = '';

    if (orderUsername) {
      try {
        const { getCollection } = require('./mongodbClient');
        const monitorCol = await getCollection('followers_monitor');
        const mon = await monitorCol.findOne({ username: orderUsername }, { projection: { hidden: 1, followersCount: 1, checkedAt: 1 } });
        if (mon && mon.hidden === true) {
          return { code: 400, body: { ok: false, error: 'hidden_profile' } };
        }
        const qtyRaw = Number(order.qtd || order.quantidade || pickAdd('quantidade') || pickAdd('qtd') || pickAdd('quantity') || 0) || 0;
        const contracted = Number.isFinite(qtyRaw) ? qtyRaw : 0;
        const initRaw = (typeof order.initialFollowersCount === 'number') ? order.initialFollowersCount : Number(pickAdd('start_count') || pickAdd('initial_followers') || pickAdd('inicial') || 0) || 0;
        const initial = Number.isFinite(initRaw) ? initRaw : 0;
        const current = (mon && typeof mon.followersCount === 'number') ? mon.followersCount : null;
        const expected = (initial > 0 && contracted > 0) ? (initial + contracted) : 0;
        const dropAbs = (expected > 0 && current != null) ? Math.max(0, expected - current) : null;
        if (dropAbs == null) return { code: 400, body: { ok: false, error: 'drop_not_computable' } };
        if (dropAbs < 100) return { code: 400, body: { ok: false, error: 'drop_below_100', dropAbs } };
      } catch (_) {}
    }

    const baseUrl = (function () {
      const candidates = [process.env.SITE_URL, process.env.PUBLIC_URL, process.env.APP_URL, process.env.BASE_URL];
      const picked = candidates.map(s => safe(s)).find(Boolean);
      const u = picked || 'https://agenciaoppus.site';
      return u.replace(/\/+$/, '');
    })();
    const clientUrl = `${baseUrl}/cliente`;
    const clientUrlWithPhone = phoneDigits ? `${clientUrl}?phone=${encodeURIComponent(phoneDigits)}` : clientUrl;
    const waPhone = '553173425727';
    const whatsappHref = `https://wa.me/${waPhone}?text=${encodeURIComponent('Olá, preciso de ajuda com reposição de seguidores')}`;

    const subject = 'Recupere os seguidores perdidos';
    const greetingName = orderUsername ? `@${orderUsername}` : 'Cliente';
    const escapeHtml = (s) => String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
    const text = [
      `Olá, ${greetingName}`,
      '',
      'Identificamos que você teve queda dos seguidores, você pode repor com nossa ferramenta.',
      '',
      'Acesse o link abaixo:',
      clientUrlWithPhone,
      '',
      '1) Informe o número de telefone que registrou no momento da compra.',
      "2) Abra o detalhamento do seu pedido e clique em 'Acessar ferramenta'.",
      "3) Após isso clique em 'Solicitar reposição'.",
      '',
      'Regras de reposição: no detalhamento do pedido, clique em "Regras de reposição" (o texto expande a descrição).',
      '',
      `Suporte: ${whatsappHref}`,
      'Email: suporte@agenciaoppus.site'
    ].join('\n');
    const html = `
<div style="margin:0;padding:0;background:#f5f7fb;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f5f7fb" style="background:#f5f7fb;padding:16px 0;">
    <tr>
      <td align="center">
        <table width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
          <tr>
            <td bgcolor="#111827" style="padding:14px 20px;font-family:Arial,Helvetica,sans-serif;background:#111827;background-color:#111827;color:#ffffff;text-align:center;">
              <div style="font-size:14px;font-weight:800;letter-spacing:0.06em;color:#ffffff;">Agência Oppus</div>
            </td>
          </tr>
          <tr>
            <td style="padding:14px 20px;font-family:Arial,Helvetica,sans-serif;color:#111827;">
              <div style="font-size:16px;font-weight:700;margin:0 0 8px 0;">Olá, ${escapeHtml(greetingName)}, tudo bem?</div>
              <div style="font-size:14px;line-height:1.5;margin:0 0 12px 0;">
                Identificamos que você teve queda dos seguidores. Você pode repor com nossa ferramenta.
              </div>

              <div style="margin:14px 0 0 0;padding:12px 12px;border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;">
                <div style="font-size:13px;font-weight:800;margin:0 0 8px 0;color:#111827;">Como solicitar reposição</div>
                <div style="font-size:13px;line-height:1.6;color:#111827;margin:0 0 10px 0;">
                  Acesse o link abaixo e siga o passo a passo.
                </div>
                <div style="margin:0 0 10px 0;">
                  <a href="${escapeHtml(clientUrlWithPhone)}" style="display:inline-block;padding:9px 12px;background:#111827;color:#ffffff;border-radius:10px;font-size:13px;font-weight:800;text-decoration:none;">Abrir Clientes</a>
                </div>
                <ol style="margin:0 0 0 18px;padding:0;font-size:12px;line-height:1.6;color:#111827;">
                  <li>Informe o número de telefone que registrou no momento da compra.</li>
                  <li>Abra o detalhamento do seu pedido e clique em <strong>Acessar ferramenta</strong>.</li>
                  <li>Após isso clique em <strong>Solicitar reposição</strong>.</li>
                </ol>

                <details style="margin-top:12px;padding:10px 12px;border:1px solid #e5e7eb;border-radius:10px;background:#ffffff;">
                  <summary style="cursor:pointer;font-size:13px;font-weight:800;color:#111827;">Regras de reposição (clique para expandir)</summary>
                  <div style="margin-top:8px;font-size:12px;line-height:1.6;color:#111827;">
                    As regras completas aparecem no detalhamento do pedido. Clique no texto para expandir a descrição.
                  </div>
                </details>
              </div>

              <div style="margin:14px 0 0 0;padding:12px 12px;border:1px solid #e5e7eb;border-radius:10px;background:#ffffff;">
                <div style="font-size:13px;font-weight:800;margin:0 0 6px 0;color:#111827;">Precisa de suporte?</div>
                <div style="font-size:13px;color:#111827;line-height:1.6;">
                  <div>Email: <a href="mailto:suporte@agenciaoppus.site" style="color:#2563eb;text-decoration:none;">suporte@agenciaoppus.site</a></div>
                  <div>Chat de suporte: <a href="${escapeHtml(whatsappHref)}" style="color:#2563eb;text-decoration:none;">Clique aqui para acessar</a></div>
                </div>
              </div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</div>`;

    const brtOffsetMs = 3 * 60 * 60 * 1000;
    const dayKeyBrt = (ms) => {
      const d = new Date(Number(ms || 0) - brtOffsetMs);
      const y = String(d.getUTCFullYear());
      const m = String(d.getUTCMonth() + 1).padStart(2, '0');
      const dd = String(d.getUTCDate()).padStart(2, '0');
      return `${y}-${m}-${dd}`;
    };
    const dayRangeBrtUtcMs = (dayKey) => {
      try {
        const s = String(dayKey || '').trim();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return { startMs: 0, endMs: 0 };
        const parts = s.split('-').map(Number);
        const y = parts[0];
        const m = parts[1];
        const d = parts[2];
        const startUtcMs = Date.UTC(y, m - 1, d, 0, 0, 0, 0) + brtOffsetMs;
        const endUtcMs = startUtcMs + (24 * 60 * 60 * 1000);
        return { startMs: startUtcMs, endMs: endUtcMs };
      } catch (_) {
        return { startMs: 0, endMs: 0 };
      }
    };
    const nowIso = new Date().toISOString();
    const todayBrtKey = dayKeyBrt(Date.now());
    const notify = (order && order.recoveryNotify && typeof order.recoveryNotify === 'object') ? order.recoveryNotify : {};
    const notifyEmail = (notify && notify.email && typeof notify.email === 'object') ? notify.email : {};
    const notifySms = (notify && notify.sms && typeof notify.sms === 'object') ? notify.sms : {};
    const prevEmailCount = Number(notifyEmail.count || 0) || 0;
    const prevEmailDay = safe(notifyEmail.lastSentDay || '');
    const prevSmsSentAt = safe(notifySms.sentAt || '');

    const persistEmailNotify = async ({ status, error, response, increaseCount }) => {
      const setObj = {
        'recoveryNotify.email.lastStatus': safe(status || ''),
        'recoveryNotify.email.lastAttemptAt': nowIso,
        'recoveryNotify.email.lastError': safe(error || ''),
        'recoveryNotify.email.lastResponse': safe(response || '')
      };
      if (increaseCount) {
        setObj['recoveryNotify.email.count'] = prevEmailCount + 1;
        setObj['recoveryNotify.email.lastSentAt'] = nowIso;
        setObj['recoveryNotify.email.lastSentDay'] = todayBrtKey;
      }
      const historyItem = { at: nowIso, status: safe(status || ''), error: safe(error || ''), response: safe(response || '') };
      await col.updateOne(
        { _id: new ObjectId(orderIdRawSafe) },
        {
          $set: setObj,
          $push: { 'recoveryNotify.email.history': historyItem }
        }
      );
    };

    const emailOut = { ok: false, status: '', error: null };
    if (email) {
      if (isOrganicosNotify) {
        emailOut.status = 'skipped_tipo_organicos';
        emailOut.error = 'skipped_tipo_organicos';
        await persistEmailNotify({ status: 'skipped_tipo_organicos', error: emailOut.error, response: '', increaseCount: false });
      } else
      {
      const dailyMaxRaw = parseInt(String(process.env.RECOVERY_EMAIL_DAILY_LIMIT || process.env.EMAIL_DAILY_LIMIT || '1000'), 10);
      const dailyMax = Math.max(1, Number.isFinite(dailyMaxRaw) ? dailyMaxRaw : 1000);
      const reservePctRaw = Number(String(process.env.RECOVERY_EMAIL_RESERVE_PCT || '0.2'));
      const reservePct = (Number.isFinite(reservePctRaw) && reservePctRaw >= 0 && reservePctRaw <= 0.9) ? reservePctRaw : 0.2;
      const { startMs: todayStartMs, endMs: todayEndMs } = dayRangeBrtUtcMs(todayBrtKey);
      const toIso = (ms) => (Number.isFinite(ms) && ms > 0) ? new Date(ms).toISOString() : '';
      const todayStartIso = toIso(todayStartMs);
      const todayEndIso = toIso(todayEndMs);
      let paidEmailCountToday = 0;
      let createdEmailCountToday = 0;
      let recoveryEmailSentEventsToday = 0;
      try {
        if (todayStartIso && todayEndIso) {
          paidEmailCountToday = await col.countDocuments({
            $or: [
              { 'woovi.paidAt': { $gte: todayStartIso, $lt: todayEndIso } },
              { paidAt: { $gte: todayStartIso, $lt: todayEndIso } }
            ]
          });
          createdEmailCountToday = await col.countDocuments({
            createdAt: { $gte: todayStartIso, $lt: todayEndIso }
          });
          const agg = await col.aggregate([
            { $match: { 'recoveryNotify.email.history': { $exists: true, $ne: [] } } },
            { $unwind: '$recoveryNotify.email.history' },
            { $match: { 'recoveryNotify.email.history.status': 'sent', 'recoveryNotify.email.history.at': { $gte: todayStartIso, $lt: todayEndIso } } },
            { $count: 'c' }
          ]).toArray();
          recoveryEmailSentEventsToday = agg && agg[0] && typeof agg[0].c === 'number' ? agg[0].c : 0;
        }
      } catch (_) {}
      const pedidosEmailCountToday = Math.max(0, Number(paidEmailCountToday || 0) + Number(createdEmailCountToday || 0));
      const availableAfterPedidos = Math.max(0, dailyMax - pedidosEmailCountToday);
      const allowedForRecoveryToday = Math.max(0, Math.floor(availableAfterPedidos * (1 - reservePct)));
      const remainingRecoveryToday = Math.max(0, allowedForRecoveryToday - Number(recoveryEmailSentEventsToday || 0));
      if (remainingRecoveryToday <= 0) {
        emailOut.status = 'skipped_daily_cap';
        emailOut.error = 'daily_recovery_limit_reached';
        await persistEmailNotify({ status: 'skipped_daily_cap', error: emailOut.error, response: `paid_today=${paidEmailCountToday};created_today=${createdEmailCountToday};sent_today=${recoveryEmailSentEventsToday};max=${dailyMax};reserve=${reservePct}`, increaseCount: false });
      } else
      if (prevEmailCount >= 2) {
        emailOut.status = 'skipped_limit';
        emailOut.error = 'email_limit_reached';
        await persistEmailNotify({ status: 'skipped_limit', error: emailOut.error, response: '', increaseCount: false });
      } else if (prevEmailDay && prevEmailDay === todayBrtKey) {
        emailOut.status = 'skipped_same_day';
        emailOut.error = 'email_already_sent_today';
        await persistEmailNotify({ status: 'skipped_same_day', error: emailOut.error, response: '', increaseCount: false });
      } else {
        const transporter = getRecoverySmtpTransporter() || getSmtpTransporter();
        if (!transporter) {
          emailOut.status = 'failed';
          emailOut.error = 'smtp_not_configured';
          await persistEmailNotify({ status: 'failed', error: emailOut.error, response: '', increaseCount: false });
        } else {
          try {
            const info = await transporter.sendMail({
              from: 'Agência Oppus <recuperacao@agenciaoppus.site>',
              to: email,
              subject,
              text,
              html
            });
            const accepted = Array.isArray(info && info.accepted) ? info.accepted.map(x => String(x || '').toLowerCase()) : [];
            const rejected = Array.isArray(info && info.rejected) ? info.rejected.map(x => String(x || '').toLowerCase()) : [];
            const responseText = safe((info && info.response) || '');
            const target = String(email || '').trim().toLowerCase();
            const targetAccepted = target ? accepted.some(v => v.includes(target)) : accepted.length > 0;
            const hasRejected = rejected.length > 0;
            if (targetAccepted || (accepted.length > 0 && !hasRejected)) {
              emailOut.ok = true;
              emailOut.status = 'sent';
              await persistEmailNotify({ status: 'sent', error: '', response: responseText, increaseCount: true });
            } else {
              emailOut.status = 'failed';
              emailOut.error = hasRejected ? 'email_denied_or_rejected' : 'email_send_not_accepted';
              await persistEmailNotify({ status: 'failed', error: emailOut.error, response: responseText, increaseCount: false });
            }
          } catch (sendErr) {
            const sendMsg = safe(sendErr && (sendErr.response || sendErr.message || String(sendErr)));
            emailOut.status = 'failed';
            emailOut.error = sendMsg ? `email_send_failed:${sendMsg}` : 'email_send_failed';
            await persistEmailNotify({ status: 'failed', error: emailOut.error, response: sendMsg, increaseCount: false });
          }
        }
      }
      }
    } else {
      emailOut.status = 'failed';
      emailOut.error = 'missing_email';
      await persistEmailNotify({ status: 'failed', error: emailOut.error, response: '', increaseCount: false });
    }

    const smsOut = { ok: false, status: '', error: null };
    const mexToken = safe(process.env.MEX10_TOKEN || process.env.MEX10_SHORTCODE_TOKEN);
    if (emailOut && emailOut.error === 'daily_recovery_limit_reached') {
      smsOut.status = 'skipped_daily_email_cap';
      smsOut.error = 'skipped_daily_email_cap';
    } else if (!mexToken) {
      smsOut.status = 'failed';
      smsOut.error = 'missing_mex10_token';
    } else if (!phoneDigits) {
      smsOut.status = 'failed';
      smsOut.error = 'missing_phone';
    } else if (prevSmsSentAt) {
      smsOut.status = 'skipped_already_sent';
      smsOut.error = 'sms_already_sent';
    } else {
      const alreadyToPhone = await col.findOne(
        {
          _id: { $ne: new ObjectId(orderIdRawSafe) },
          'recoveryNotify.sms.sentTo': phoneDigits,
          'recoveryNotify.sms.sentAt': { $exists: true, $ne: '' }
        },
        { projection: { _id: 1 } }
      );
      if (alreadyToPhone) {
        smsOut.status = 'skipped_already_sent_to_phone';
        smsOut.error = 'sms_already_sent_to_phone';
      } else {
      const msg = 'Oppus: Voce perdeu seguidores. Enviamos no seu e-mail cadastrado na compra as orientacoes para recuperar seus seguidores.';
      const resp = await axios.get('https://mex10.com/api/shortcodev2.aspx', getMex10RequestOpts({
        params: { token: mexToken, t: 'send', n: phoneDigits, m: msg },
        timeout: 20000,
        validateStatus: () => true,
        headers: { 'Accept': 'application/json' }
      }));
      const data = resp && resp.data ? resp.data : null;
      const success = !!(data && data.data && data.data.success === true);
      const errFlag = !!(data && data.errors && data.errors.error === true);
      if (resp.status >= 200 && resp.status < 300 && success && !errFlag) {
        smsOut.ok = true;
        smsOut.status = 'sent';
        await col.updateOne(
          { _id: new ObjectId(orderIdRawSafe) },
          {
            $set: { 'recoveryNotify.sms.sentAt': nowIso, 'recoveryNotify.sms.sentTo': phoneDigits },
            $push: { 'recoveryNotify.sms.history': nowIso }
          }
        );
      } else {
        smsOut.status = 'failed';
        smsOut.error = (data && data.errors && data.errors.description) ? safe(data.errors.description) : ('HTTP ' + String(resp.status));
      }
      }
    }

    const smsSkippedOk = !!(smsOut && smsOut.ok !== true && typeof smsOut.error === 'string' && (smsOut.error === 'sms_already_sent' || smsOut.error === 'sms_already_sent_to_phone' || smsOut.error === 'missing_phone'));
    const overallOk = isOrganicosNotify ? (smsOut.ok || smsSkippedOk) : (emailOut.ok && (smsOut.ok || smsSkippedOk));
    return { code: 200, body: { ok: overallOk, orderId: orderIdRawSafe, username: orderUsername || null, email: emailOut, sms: smsOut } };
  } catch (e) {
    return { code: 500, body: { ok: false, error: e?.message || String(e) } };
  }
}

