function followersMgmtSerializeRefil2BulkJob(jobRaw) {
  const job = jobRaw || null;
  if (!job) return null;
  return {
    id: job.id,
    status: job.status,
    startedAt: job.startedAt,
    finishedAt: job.finishedAt,
    total: job.total,
    done: job.done,
    ok: job.ok,
    failed: job.failed,
    skipped: job.skipped,
    lastUsername: job.lastUsername || null,
    lastError: job.lastError || null,
    batchId: job.batchId || null
  };
}

function followersMgmtKickRefil2BulkJob() {
  const job = global.followersMgmtRefil2BulkJob || null;
  if (!job) return;
  if (job._runnerActive) return;
  if (job.status !== 'running') return;
  job._runnerActive = true;

  const isEligibleTipo = (tipoRaw) => {
    const t = String(tipoRaw || '').toLowerCase();
    if (t.includes('organ')) return false;
    return t.includes('misto') || t.includes('brasileir');
  };
  const isEligibleDropAbs = (v) => {
    const n = Number(v || 0);
    return Number.isFinite(n) && n >= 101;
  };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  (async () => {
    try {
      const targets = Array.isArray(job.targets) ? job.targets : [];
      try { console.log(`🤖 [followers-refil2-bulk] start job=${String(job.id || '')} total=${targets.length} batch=${String(job.batchId || '')}`); } catch (_) {}
      while (job.status === 'running' && job.done < targets.length) {
        const t = targets[job.done] || {};
        const username = String(t.username || '').trim().replace(/^@+/, '').toLowerCase();
        job.lastUsername = username || null;
        job.lastError = null;
        if (!username) {
          job.skipped += 1;
          job.done += 1;
          continue;
        }
        if (!isEligibleTipo(t.tipo)) {
          job.skipped += 1;
          job.done += 1;
          continue;
        }
        if (!isEligibleDropAbs(t.diffAbs)) {
          job.skipped += 1;
          job.done += 1;
          continue;
        }
        try {
          const baseUrl = String(job.baseUrl || '').trim();
          if (!baseUrl) throw new Error('base_url_missing');
          const payload = {
            username,
            via: 'painel_refil2_bulk',
            automated: true,
            automationBatchId: job.batchId || ''
          };
          const resp = await axios.post(`${baseUrl}/api/refil/simple`, payload, {
            timeout: 120000,
            validateStatus: () => true,
            headers: { 'Accept': 'application/json' }
          });
          const status = Number(resp && resp.status ? resp.status : 0) || 0;
          const body = resp ? resp.data : null;
          const ok = !!(status >= 200 && status < 300 && body && body.ok === true);
          if (ok) job.ok += 1;
          else job.failed += 1;
          if (!ok) {
            const msg = String((body && (body.message || body.error)) || '').trim();
            job.lastError = msg || (`HTTP ${status}`);
          }
          try { console.log(`🤖 [followers-refil2-bulk] job=${String(job.id || '')} i=${job.done + 1}/${targets.length} ok=${ok ? '1' : '0'} @${username} http=${status}`); } catch (_) {}
        } catch (e) {
          job.failed += 1;
          job.lastError = e?.message || String(e);
          try { console.warn(`🤖 [followers-refil2-bulk] job=${String(job.id || '')} i=${job.done + 1}/${targets.length} fail @${username}:`, job.lastError); } catch (_) {}
        } finally {
          job.done += 1;
          await sleep(250);
        }
      }
      if (job.status === 'running' && job.done >= (Array.isArray(job.targets) ? job.targets.length : 0)) {
        job.status = 'done';
        job.finishedAt = new Date().toISOString();
      }
    } catch (e) {
      job.status = 'error';
      job.lastError = e?.message || String(e);
      job.finishedAt = new Date().toISOString();
    } finally {
      job._runnerActive = false;
    }
  })();
}

// ── Job de PEDIDOS NOVOS (action=add) para repor a queda ──────────────────────
// Diferente do refil2 (action=refill no pedido original), aqui criamos um pedido
// NOVO no Fama24h com quantidade = diffAbs (a queda) para cada @ do filtro.
// Cada novo orderid é logado em refil2_requests (forceRefil.orderId = cobrável).
function followersMgmtSerializeNewOrdersJob(jobRaw) {
  const job = jobRaw || null;
  if (!job) return null;
  return {
    id: job.id, status: job.status, startedAt: job.startedAt, finishedAt: job.finishedAt,
    total: job.total, done: job.done, ok: job.ok, failed: job.failed, skipped: job.skipped,
    qtyTotal: job.qtyTotal || 0, lastUsername: job.lastUsername || null,
    lastError: job.lastError || null, batchId: job.batchId || null
  };
}

function followersMgmtKickNewOrdersJob() {
  const job = global.followersMgmtNewOrdersJob || null;
  if (!job) return;
  if (job._runnerActive) return;
  if (job.status !== 'running') return;
  job._runnerActive = true;

  const normTipo = (tipoRaw) => {
    const t = String(tipoRaw || '').toLowerCase();
    if (t.includes('organ')) return '';
    if (t.includes('brasileir')) return 'brasileiros';
    if (t.includes('misto')) return 'mistos';
    return '';
  };
  const isEligibleDropAbs = (v) => { const n = Number(v || 0); return Number.isFinite(n) && n >= 101; };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  (async () => {
    try {
      const key = String(process.env.NUVRASMM_API_KEY || '').trim();
      const apiUrl = String(process.env.FAMA24H_API_URL || 'https://nuvrasmm.com/api/v2').trim();
      const targets = Array.isArray(job.targets) ? job.targets : [];
      let refilCol = null; try { refilCol = await getCollection('refil2_requests'); } catch (_) {}
      try { console.log(`🆕 [followers-new-orders] start job=${String(job.id || '')} total=${targets.length}`); } catch (_) {}
      while (job.status === 'running' && job.done < targets.length) {
        const t = targets[job.done] || {};
        const username = String(t.username || '').trim().replace(/^@+/, '').toLowerCase();
        const tipo = normTipo(t.tipo);
        const qty = Math.floor(Number(t.diffAbs || 0));
        job.lastUsername = username || null;
        job.lastError = null;
        if (!username || !tipo || !isEligibleDropAbs(qty)) { job.skipped += 1; job.done += 1; continue; }
        if (!key) { job.failed += 1; job.lastError = 'missing_key'; job.done += 1; continue; }
        try {
          const _md = await resolveMainDispatch({ ctx: 'seguidores', key: tipo, fallbackId: (tipo === 'brasileiros' ? 23 : 663) });
          const serviceId = _md.serviceId;
          const link = 'https://instagram.com/' + username;
          const payload = new URLSearchParams({ key: _md.key, action: 'add', service: String(serviceId), link, quantity: String(qty) });
          const resp = await postFormWithRetry(_md.url, payload.toString(), 60000, 3, { validateStatus: () => true });
          const data = normalizeProviderResponseData(resp && resp.data);
          const orderId = extractProviderOrderId(data);
          if (orderId) {
            job.ok += 1; job.qtyTotal += qty;
            if (refilCol) {
              try {
                await refilCol.insertOne({
                  requestedAt: new Date(), source: 'painel_novo_pedido_bulk', username, tipo,
                  execStatus: 'success', decisionStatus: 'initiated', decisionReason: 'new_add_order_ok',
                  automated: true, automationBatchId: job.batchId || '',
                  forceRefil: { orderId: String(orderId), provider: _md.provider, quantity: qty, at: new Date() },
                  lastRefilId: String(orderId), lastRefilProvider: _md.provider, lastRefilAt: new Date(),
                  pedido: { id: String(orderId), link }
                });
              } catch (_) {}
            }
            try { console.log(`🆕 [followers-new-orders] job=${String(job.id || '')} i=${job.done + 1}/${targets.length} @${username} qty=${qty} order=${orderId}`); } catch (_) {}
          } else {
            job.failed += 1;
            const err = (data && (data.error || (data.data && data.data.error) || (data.response && data.response.error))) || null;
            job.lastError = err ? (typeof err === 'string' ? err : JSON.stringify(err)) : 'sem_orderid';
            try { console.warn(`🆕 [followers-new-orders] job=${String(job.id || '')} i=${job.done + 1}/${targets.length} @${username} SEM orderid: ${job.lastError}`); } catch (_) {}
          }
        } catch (e) {
          job.failed += 1; job.lastError = e?.message || String(e);
          try { console.warn(`🆕 [followers-new-orders] job=${String(job.id || '')} i=${job.done + 1}/${targets.length} @${username} fail:`, job.lastError); } catch (_) {}
        } finally {
          job.done += 1; await sleep(300);
        }
      }
      if (job.status === 'running' && job.done >= (Array.isArray(job.targets) ? job.targets.length : 0)) {
        job.status = 'done'; job.finishedAt = new Date().toISOString();
      }
    } catch (e) {
      job.status = 'error'; job.lastError = e?.message || String(e); job.finishedAt = new Date().toISOString();
    } finally {
      job._runnerActive = false;
    }
  })();
}

app.post('/api/painel/gerenciamento-seguidores/refil-new-orders/start', requireAdmin, async (req, res) => {
  try {
    if (global.followersMgmtNewOrdersJob && global.followersMgmtNewOrdersJob.status === 'running') {
      return res.json({ ok: true, job: followersMgmtSerializeNewOrdersJob(global.followersMgmtNewOrdersJob) });
    }
    const rawTargets = (req.body && Array.isArray(req.body.targets)) ? req.body.targets : [];
    if (!rawTargets.length) return res.status(400).json({ ok: false, error: 'empty_targets' });
    const normalizeUsernameKey = (u) => String(u || '').trim().replace(/^@+/, '').toLowerCase();
    const toIntLoose = (v) => { try { const s = String(v == null ? '' : v).trim().replace(/[^\d\-]/g, ''); if (!s || s === '-') return 0; const n = parseInt(s, 10); return Number.isFinite(n) ? Math.trunc(n) : 0; } catch (_) { return 0; } };
    const unique = [];
    const seen = new Set();
    for (const r of rawTargets) {
      const u = normalizeUsernameKey(r && r.username ? r.username : '');
      if (!u || seen.has(u)) continue;
      seen.add(u);
      unique.push({ username: u, tipo: String(r && r.tipo ? r.tipo : ''), diffAbs: toIntLoose(r && r.diffAbs != null ? r.diffAbs : 0) });
      if (unique.length >= 5000) break;
    }
    const batchId = String(Date.now()) + '_' + String(Math.random()).slice(2);
    const job = { id: batchId, status: 'running', startedAt: new Date().toISOString(), finishedAt: null, total: unique.length, done: 0, ok: 0, failed: 0, skipped: 0, qtyTotal: 0, lastUsername: null, lastError: null, batchId, targets: unique };
    global.followersMgmtNewOrdersJob = job;
    followersMgmtKickNewOrdersJob();
    return res.json({ ok: true, job: followersMgmtSerializeNewOrdersJob(job) });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.get('/api/painel/gerenciamento-seguidores/refil-new-orders/status', requireAdmin, async (req, res) => {
  try {
    return res.json({ ok: true, job: followersMgmtSerializeNewOrdersJob(global.followersMgmtNewOrdersJob || null) });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

app.post('/api/painel/gerenciamento-seguidores/refil2/bulk-start', requireAdmin, async (req, res) => {
  try {
    if (global.followersMgmtRefil2BulkJob && global.followersMgmtRefil2BulkJob.status === 'running') {
      return res.json({ ok: true, job: followersMgmtSerializeRefil2BulkJob(global.followersMgmtRefil2BulkJob) });
    }
    const rawTargets = (req.body && Array.isArray(req.body.targets)) ? req.body.targets : [];
    if (!rawTargets.length) return res.status(400).json({ ok: false, error: 'empty_targets' });

    const normalizeUsernameKey = (u) => String(u || '').trim().replace(/^@+/, '').toLowerCase();
    const toIntLoose = (v) => {
      try {
        const s = String(v == null ? '' : v).trim().replace(/[^\d\-]/g, '');
        if (!s || s === '-') return 0;
        const n = parseInt(s, 10);
        return Number.isFinite(n) ? Math.trunc(n) : 0;
      } catch (_) {
        return 0;
      }
    };
    const unique = [];
    const seen = new Set();
    for (const r of rawTargets) {
      const u = normalizeUsernameKey(r && r.username ? r.username : '');
      if (!u) continue;
      if (seen.has(u)) continue;
      seen.add(u);
      const diffAbs = toIntLoose(r && r.diffAbs != null ? r.diffAbs : 0);
      unique.push({
        username: u,
        tipo: String(r && r.tipo ? r.tipo : ''),
        lastPurchaseAtMs: (r && typeof r.lastPurchaseAtMs === 'number' && Number.isFinite(r.lastPurchaseAtMs)) ? r.lastPurchaseAtMs : 0,
        diffAbs
      });
      if (unique.length >= 5000) break;
    }
    unique.sort((a, b) => Number(a.lastPurchaseAtMs || 0) - Number(b.lastPurchaseAtMs || 0));

    const xfProto = String((req.headers && (req.headers['x-forwarded-proto'] || req.headers['X-Forwarded-Proto'])) || '').split(',')[0].trim();
    const proto = xfProto ? xfProto : String(req.protocol || 'http');
    const host = String(req.get('host') || '').trim();
    const baseUrl = host ? `${proto}://${host}` : `http://localhost:${String(process.env.PORT || '3000')}`;
    const batchId = `${Date.now()}_${Math.random().toString(16).slice(2)}`;

    const job = {
      id: String(Date.now()) + '_' + String(Math.random()).slice(2),
      status: 'running',
      startedAt: new Date().toISOString(),
      finishedAt: null,
      total: unique.length,
      done: 0,
      ok: 0,
      failed: 0,
      skipped: 0,
      lastUsername: null,
      lastError: null,
      batchId,
      baseUrl,
      targets: unique
    };
    global.followersMgmtRefil2BulkJob = job;
    followersMgmtKickRefil2BulkJob();
    return res.json({ ok: true, job: followersMgmtSerializeRefil2BulkJob(job) });
  } catch (e) {
    return res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

