    const idsRaw = Array.isArray(body.ids) ? body.ids : [];
    const ids = Array.from(new Set(idsRaw.map(x => String(x || '').trim()).filter(s => /^[a-fA-F0-9]{24}$/.test(s)))).slice(0, 30);
