            const baseArr = Array.isArray(o.additionalInfo) ? o.additionalInfo : [];
            const pickArr = (arr, key) => {
              const it = (Array.isArray(arr) ? arr : []).find(x => x && String(x.key || '').trim() === key);
              return it && typeof it.value !== 'undefined' ? String(it.value) : '';
            };
